t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "De vuelta al norte, más allá de {area:918}, hasta la mina: los Cavadores kóbold trabajan dentro.",
		["Back to {area:108}"] = "Vuelve a {area:108}",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon."] = "Los Acechacaminos Defias y los Sacudillos recorren {area:20}; los Bandoleros (nivel 17) patrullan en parejas las colinas al sur y al este: sepáralos. La entrada a {area:1581}, en la herrería, es una mazmorra de grupo.",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}."] = "Los Saqueadores Defias y los Despojadores ocupan las granjas al oeste de {area:108}, entre el camino de la costa y {area:20}.",
		["Fill the vial at the farm's well"] = "Llena el vial en el pozo de la granja",
		["Fill the vial at the well"] = "Llena el vial en el pozo",
		["Fly or ride to {zone:1453}. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "Vuela o cabalga hasta {zone:1453}. Instructores: {object:2100} (guerreros, pícaros), la Catedral (paladines, sacerdotes), {object:2101} (magos, brujos), el Parque (druidas).",
		["Fly or ride to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Vuela o cabalga hasta {zone:1453}. {npc:376} está en la Catedral de la Luz.",
		["Fly or ride to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Vuela o cabalga hasta {zone:1453}. {npc:5480} entrena a los guerreros en {object:2100}; {npc:6089} y {npc:6090} están juntos junto a {object:2152}, allí mismo. {npc:6090} pelea contigo por su jarra.",
		["Follow the road north. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west."] = "Sigue el camino hacia el norte. {npc:233} está fuera, {npc:235} Saldean en la casa y {npc:253395} en el granero al oeste.",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "Para {npc:11026}, en {object:28027} de {zone:1453}",
		["For {npc:266} in {area:69}, Redridge"] = "Para {npc:266} en {area:69}, Montañas Crestagrana",
		["Further north along the road. The Furlbrows sit by their burned farm. Collect the oats from the Sacks of Oats in the fields as you go."] = "Más al norte por el camino. Los Cejade están sentados junto a su granja quemada. Recoge la avena de los Sacos de avena de los campos por el camino.",
		["Gnoll Paws"] = "Garras gnoll",
		["Harvest Watchers"] = "Vigilantes de la cosecha",
		["Hearthstone on cooldown? Follow the road north-east."] = "¿Piedra de hogar en reutilización? Sigue el camino hacia el noreste.",
		["Kobold Diggers"] = "Cavadores kóbold",
		["Level 12, 14 and 16 spells"] = "Hechizos de nivel 12, 14 y 16",
		["Longshore Murloc Gills"] = "Branquias de múrloc de Playa Larga",
		["Murloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time."] = "Los Correcostas múrloc y los Asaltantes ocupan la playa al norte de la mina. Huyen con poca salud: atráelos de uno en uno.",
		["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine."] = "Al norte de La Granja de Molsen. Los Tramperos Defias y los Contrabandistas Defias acampan fuera de la mina. {object:290} está junto a la casa en ruinas al este de la mina.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Solo si conseguiste una {item:1972} en el Bosque de Elwynn: haz clic derecho en ella",
		["Ride to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Cabalga hasta {zone:1453}. No tiene instructor de chamanes: toma el {area:2257} desde {object:28027} hasta {zone:1455}, entrena con {npc:258098} y vuelve en el tranvía para coger el barco.",
		["Riverpaw Gnolls and Scouts roam the hills between the coast and the {area:916}."] = "Los Gnolls Zarparrío y los Exploradores recorren las colinas entre la costa y {area:916}.",
		["Riverpaw Miners"] = "Mineros Zarparrío",
		["Sacks of Oats"] = "Sacos de avena",
		["Shaman training"] = "Instrucción de chamán",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "Al suroeste, hacia la costa, al oeste de {area:918}. Los Mineros Zarparrío trabajan en la cantera.",
		["The gnoll hills"] = "Las colinas de los gnolls",
		["The north coast"] = "La costa norte",
		["The western farms"] = "Las granjas del oeste",
		["The {area:113}"] = "{area:113}",
		["West of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "Al oeste de la Finca de Saldean. Los Vigilantes de la cosecha y los Gólems trabajan los campos; sueltan los isomuelles, los giroestabilizadores, {item:732} y a veces un {item:255155}. {npc:573}, un raro de nivel 20, anda por aquí: déjalo en paz. Sigue matando Dentosangre y Desgarradores en cada tramo de esta vuelta.",
		["Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way back."] = "Los Dentosangre jóvenes y los Desgarradores recorren los campos alrededor de la granja: empieza con los hígados y la carne del estofado a la vuelta.",
		["{area:20} and the Defias hills"] = "{area:20} y las colinas Defias",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} para Reunir los ingredientes del remedio (6123) en {zone:1439}: {npc:1313}, Suministros de alquimia; los herboristas la recogen allí",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, de las cajas alrededor de {area:20}",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, de {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729}: Desgarradores",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} y {npc:821} están en lo alto de la torre de piedra. {npc:491} está dentro de la torre; {npc:878}, en la ladera sur de la colina, junto a la posada y a {npc:523}, el maestro de grifos.",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, junto a {npc:878}",
		["{npc:523}; skip the free flight it offers"] = "{npc:523}; omite el vuelo gratis que te ofrece",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} vende suministros de pesca junto al canal, justo al oeste de {object:2096}; {npc:267118} pesca en el puerto, de camino al barco.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Sagrario del Mago: {quest:1861}",
		["{quest:153}: every Defias drops them"] = "{quest:153}: los suelta cualquier Defias",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "En el {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Vuelve al noreste, a las montañas, hasta el cristal.",
		["Back south"] = "De vuelta al sur",
		["Back to {npc:11802}"] = "De vuelta con {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702} (by way of {area:442})."] = "Vuelve con {npc:11802} en {area:2361} y luego vuela a {area:702} (pasando por {area:442}).",
		["Bears and the Blackwood camp"] = "Osos y el campamento Bosquenegro",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Los Abrecaminos Bosque Negro y los Soplavientos Bosquenegro ocupan el campamento al sureste de {area:442}.",
		["Blackwood furbolgs"] = "Furbolgs Bosquenegro",
		["Boat to {zone:1453}"] = "Barco a {zone:1453}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. Los adornos de altar ({item:15877}) están en los contenedores del fondo del {area:656}, bajo {area:2361}: lleva uno al {area:2362}, al noroeste, úsalo allí y habla con {npc:11799}. Después vuela de vuelta a {area:442} desde {area:2361}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; aprende allí la ruta de vuelo si no la tienes.",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Sube a las montañas orientales al este de {area:447}; el {object:175524} está en una cornisa.",
		["Crawler Legs"] = "Patas de reptador",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Escóltala fuera de la guja; la misión se entrega a Therysil en {zone:1440}",
		["Fill the tube at the moonwell in the village"] = "Llena el tubo en el pozo de la luna del pueblo",
		["Fine Moonstalker Pelts"] = "Pelambres de Acechalunas refinados",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Vuela de {area:442} a {area:702} y toma el portal para subir hasta {npc:4217} en el {area:1658}.",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Sigue la costa hacia el noreste hasta las {area:443}. {quest:951}: están entre las ruinas, custodiadas por Myrmidones, Hechiceras y Guerreros Escama Tormentosa, y las Maestras de bestias Escama Tormentosa recorren la orilla.",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Sigue la costa hacia el sur, más allá de {area:447}: una {quest:4728} yace en la orilla al oeste del Páramo y otra más al sur, cerca de {area:450}. Otros tres restos yacen más al suroeste entre Oráculos Brumagris y Cazamareas Brumagris (18-20): la guía los deja para la última vuelta, cuando estés más cerca de su nivel.",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Sigue las colinas hacia el norte hasta el {area:456} y sube hasta la cascada. Hay dos restos varados más en la orilla norte: cerca de las {area:443} y al norte de {quest:954}.",
		["Follow the road north."] = "Sigue el camino hacia el norte.",
		["Follow the road south. {quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "Sigue el camino hacia el sur. {quest:948} es el anciano del Páramo; {npc:270269} y {npc:11218} duermen a su lado.",
		["Grell Earrings"] = "Pendientes grell",
		["Grizzled Scalps"] = "Cueros cabelludos canosos",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Los Grisosos cardo deambulan por las colinas alrededor de la Arboleda; {quest:1003} está al oeste de ella, entre ellos.",
		["Hearth to {area:442}"] = "Usa la piedra de hogar para ir a {area:442}",
		["Hearthstone on cooldown? Follow the coast road back south."] = "¿Piedra de hogar en reutilización? Vuelve al sur por el camino de la costa.",
		["Highborne Relics"] = "Reliquias de Altonato",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Mata Osos Cardo rabiosos en las colinas al este de {area:442} y luego sube al campamento furbolg al sureste: aún no hay nada que matar.",
		["Moonstalker Fangs"] = "Colmillos de Acechalunas",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "Los Señores Acechalunas merodean por el bosque alrededor de la guja. El {object:10076} y el {object:12666} están en el fondo del cráter; {npc:3584} está en su lado norte.",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Los Acechalunas merodean por las colinas entre {quest:954} y la torre. {quest:1002} está en la colina al oeste de la torre.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Los elfos de la noche vuelan de {area:442} a {area:702}; los cielonatos toman el barco en el muelle de {area:442} y descubren allí la ruta de vuelo de Rut'theran. Toma el portal para subir hasta {npc:4217} en el {area:1658}.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Hacia el norte por las colinas. {npc:3650} espera en las ruinas de {quest:954}; están llenas de Greles salvajes y Duendes viles, y los Sátiros Deth'ryll ocupan el borde este. {quest:1001} está junto al camino, al oeste de las ruinas; una {quest:4723} yace en la orilla de camino hacia él.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Solo si un Discípulo o un Matón soltó {item:5352}: haz clic derecho en él",
		["Plagued bears"] = "Osos apestados",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Los Osos Cardo rabiosos deambulan por las colinas justo al este de {area:442}. Usa {quest:2139} con uno y llévalo hasta él.",
		["Read the {object:17188}"] = "Lee {object:17188}",
		["Read the {object:17189}"] = "Lee {object:17189}",
		["Scaber Stalks"] = "Níscalos",
		["She gives you the {item:15826}"] = "Te da el {item:15826}",
		["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "Toma el portal para subir hasta {npc:4217} y luego vuela de vuelta a {area:442} para tomar el barco a {zone:1453}.",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Las Flores de hongo lunar crecen en las cuevas de los lechúcicos, en las colinas justo al este de {area:442}; los lechúcicos de allí son irritables. {item:2449} requiere {skill:182}: los herboristas la recogen por toda {zone:1439}; los demás la traen de {zone:1453} ({npc:1313}) o de la casa de subastas.",
		["The WANTED poster"] = "El cartel de SE BUSCA",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The bay wrecks"] = "Los pecios de la bahía",
		["The beach"] = "La playa",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "El barco atraca al oeste del pueblo. El maestro de vuelo está en la colina al sur de la posada; los que dan misiones están repartidos por la calle principal.",
		["The cave and the {npc:6788}"] = "La cueva y la {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls; {object:177624} lies at the satyr camp north of her."] = "La cueva está al sur de la cascada: los níscalos ({item:5271}) crecen por toda ella y el {item:5270}, al fondo del todo. La {npc:6788} tiene su guarida en las colinas al sur de la cascada; {object:177624} está en el campamento sátiro al norte de ella.",
		["The flame burns in the south of {area:447}."] = "La llama arde en el sur de {area:447}.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Los medios colgantes están en {zone:1439} y {zone:1436}: más adelante en la ruta",
		["The naga"] = "Los naga",
		["The red crystal"] = "El cristal rojo",
		["The relics of the Barrow Dens"] = "Las reliquias del Túmulo de Tempestira",
		["The skeletal turtle"] = "La tortuga esquelética",
		["The southern beaches"] = "Las playas del sur",
		["The {area:443}"] = "Las {area:443}",
		["The {area:448}"] = "La {area:448}",
		["The {object:10076}"] = "El {object:10076}",
		["The {object:12666}"] = "El {object:12666}",
		["The {object:16393}"] = "La {object:16393}",
		["Thresher Eyes"] = "Ojos de trillador",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore."] = "Hay dos pecios en el fondo de la bahía al norte de {area:442}; cada uno guarda una caja fuerte. Correarrecifes y Corremareas escamados recorren esta orilla.",
		["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil."] = "{area:450} está en la costa al sur de la playa de {npc:10323}. Protege al prospector mientras busca el fósil.",
		["{item:12238}: fish from the pier"] = "{item:12238}: pesca desde el muelle",
		["{item:12289}, on the beach west of the docks"] = "{item:12289}, en la playa al oeste de los muelles",
		["{item:12349}, at the waterfall"] = "{item:12349}, en la cascada",
		["{item:12355}, in {object:177624}"] = "{item:12355}, en {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: en la entrada de la cueva junto a la cascada",
		["{item:15851} and {item:2449}"] = "{item:15851} y {item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de un {object:177785} del lago",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: {object:177792} bajo el agua frente a la costa norte, al oeste de las ruinas",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: Discípulos y Matones Crepusculares",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Sátiros Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: Fanáticos de la Facción Oscura",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}, en el muelle: solo con {skill:356}",
		["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of {area:450}."] = "{npc:10323} acampa en la playa al oeste de la guja: mata a los múrlocs de la hoguera; él llega en la tercera oleada con su perro. Hay tres restos varados en las playas al oeste y al suroeste de {area:450}.",
		["{npc:10323}'s beach"] = "La playa de {npc:10323}",
		["{npc:11218}: his escort to {area:413} is done on the {zone:1440} leg"] = "{npc:11218}: su escolta hasta {area:413} se hace en el tramo de {zone:1440}",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: la bienvenida de Sheldras Moontree",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: usa el {item:15826} con ellos; deambulan por toda {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}, en el Páramo",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} está en el borde norte de las ruinas. Altonatos malditos, Altonatos en pena y {npc:2178} las recorren; el fantasma de {npc:3667} camina entre ellos y el búho {npc:270196} vuela en círculos al este. Las dos tablillas están en las ruinas; una {quest:4722} yace en la orilla al oeste.",
		["{npc:3644}, on the pier"] = "{npc:3644}, en el muelle",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: para {npc:1646} en {zone:1453}",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661} se esconde al pie de la torre entre los Fanáticos de la Facción Oscura. Guarda su carta para Delgren el Purificador en {zone:1440}.",
		["{npc:3666}, by the inn"] = "{npc:3666}, junto a la posada",
		["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692} se esconde en las colinas al este de {area:449}. Ayúdale a volver al camino; pelea mientras sale.",
		["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}: para {npc:3691} en {area:415}, en el tramo posterior de {zone:1440}",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} se esconde en el islote frente a las ruinas. Las piezas de la llave las sueltan los Zancudos del bosque gigantes (arriba), los múrlocs Brumagris (centro) y los Reptadores Correarrecifes enfurecidos (abajo).",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: llena el muestreador en {area:445}",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} la ofrece cuando hayas entregado los nueve restos varados",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (elfos de la noche) y el {npc:272054} (Cielonato) esperan en el sur de {area:493}. Las tres reliquias están en las {area:2363}, al este. Según informes de las primeras semanas, una reliquia no da botín mientras otro jugador la está despojando: espera un momento y vuelve a intentarlo.",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "Vuelve a {area:69}",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "Cruza el largo puente hacia el norte hasta el pueblo. {npc:341} y {npc:382} están en el extremo norte del puente; {npc:900}, en el ayuntamiento; {npc:381} y {npc:266}, en los muelles; {npc:343}, en la posada; {npc:342}, en su huerto del extremo oeste.",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite."] = "Al este, pasado el molino, cruza el río. Los gnols Pielsombra llenan el valle; {npc:703} (26, muy por encima de ti) los dirige en el extremo norte: acaba primero con su escolta y lucha contra él con la salud al máximo. No entres en {area:2099}, al sur: sus orcos son élite.",
		["Fly to {area:108} and ride north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then ride east along the road through Elwynn to Redridge."] = "Vuela a {area:108} y cabalga al noroeste hasta la costa: la {object:177790} está en el fondo del mar frente a la orilla. Después cabalga al este por el camino a través de Bosque de Elwynn hasta Montañas Crestagrana.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "Sigue el camino por la orilla sur de {area:68} hasta la maestra de grifos. {npc:1070} y {npc:903} están junto al camino, a su lado.",
		["For {npc:3649}, on the return to {area:442} (06-ashenvale)"] = "Para {npc:3649}, a la vuelta a {area:442} (06-ashenvale)",
		["Gnolls toward {area:1002}"] = "Gnols hacia {area:1002}",
		["Greater Tarantulas crawl on the slopes around the mill north-east of the lake; Blackrock Renegades hold the mill itself."] = "Las Tarántulas mayores recorren las laderas alrededor del molino al noreste del lago; los Renegados Roca Negra ocupan el propio molino.",
		["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "Sal de {area:69} hacia el norte, sube por {area:95} hasta {area:997}. Los Campeones Roca Negra acampan en el valle.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "Keeshan se esconde en el extremo norte del valle, junto a la frontera de {zone:1428}. Escóltalo hasta {area:69}; los orcos Roca Negra te tienden emboscadas por el camino.",
		["Lake murlocs"] = "Múrlocs del lago",
		["Level 18 and 20 spells"] = "Hechizos de nivel 18 y 20",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin."] = "Los Comecarnes múrloc y los llamamareas ocupan la orilla sur al este del puente. Cualquiera de ellos puede llevar un {item:1467} o una aleta.",
		["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Dire Condors and Great Goretusks roam the same hills."] = "Los Bastardos de Crestagrana y otros gnols ocupan las colinas al este de {area:1002}, al norte del camino; los Vándalos de Crestagrana merodean entre ellos y los furtivos acampan al sur del camino. Dire Condors y Grandes dentosangre recorren las mismas colinas.",
		["Shaman training"] = "Entrenamiento de chamán",
		["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "Nada al este desde el puente hasta {area:68}; el cofre está en el fondo del lago.",
		["The Wanted poster by the inn: {npc:703}, in {area:1000}"] = "El cartel de Se busca junto a la posada: {npc:703}, en {area:1000}",
		["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "El camino desde Bosque de Elwynn entra en Montañas Crestagrana por {area:1002}. {npc:464} está donde se cruzan los caminos a Montañas Crestagrana y {zone:1431}.",
		["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "El barco de {area:442} atraca en {area:17203}. Sube a la ciudad para entrenar y ver a {npc:1646}; después sal por la puerta principal y sigue el camino hacia el este por {zone:1429}.",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: cualquier gnol Pielsombra",
		["{item:15882}: the {object:177790}"] = "{item:15882}: la {object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: Vándalos de Crestagrana",
		["{item:3014}: the Blackrock Renegades at the mill"] = "{item:3014}: los Renegados Roca Negra del molino",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: la carta de Thundris desde {area:442}",
		["{npc:266}, by the docks"] = "{npc:266}, junto a los muelles",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332} está en el IV:7 de {object:2100}; {npc:6122}, en el sótano de {object:2164}, en {object:2101}; {npc:376}, en la catedral.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}: la recoge {npc:7024} en {zone:1436}, al final de {zone:1431}",
		["{npc:341}: after {quest:89}"] = "{npc:341}: después de {quest:89}",
		["{npc:344}, in the town hall"] = "{npc:344}, en el ayuntamiento",
		["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345} (nivel 24) hoza en el corral justo al oeste de {area:69}. Apártalo de los demás jabalíes y lucha con la salud al máximo.",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: la recoge {npc:11401} en {zone:1457}, más adelante",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: la recoge {npc:11406} en {zone:1455}, más adelante",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: la recoge {npc:258785} en {zone:1455}, más adelante",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: la recoge {npc:6244} en {zone:1413}, más adelante",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, junto a los grifos al sur del puente",
		["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "Ahora toca {zone:1431}: sigue el camino al oeste hasta {area:1002} y luego al sur hasta {area:42}.",
		["{zone:1453} class quests"] = "Misiones de clase de {zone:1453}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} no tiene instructor de chamanes: toma el {area:2257} desde {object:28027} hasta {zone:1455}, entrena con {npc:258098} y vuelve en el tranvía.",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "Usa /lay para tumbarte junto a {npc:7207}",
		["Back to {area:42}"] = "Vuelta a {area:42}",
		["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "Sigue al oeste hasta {area:94}. El {object:673515} brilla junto a la casa en ruinas al sur del camino.",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters."] = "Cualquier necrófago de la mitad norte del {area:492} puede soltar una costilla: Comecarnes, Masticahuesos Oseral, Propagadores de la Peste y Comesesos.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Sigue el camino al noroeste, pasado el cementerio, hasta el campamento de {npc:311}, en el extremo oeste del bosque. {npc:893} está junto a {npc:311}.",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "Sigue el camino al sur desde {area:1002} hasta {zone:1431}; {area:42} está en el lado este del bosque.",
		["Ghoul Ribs"] = "Costillas de necrófago",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "Su casa está en la colina al sureste de {area:42}, por encima del {area:121}.",
		["Level 22 and 24 spells"] = "Hechizos de nivel 22 y 24",
		["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "Después: {zone:1453} para entrenar y luego el barco de {area:17203} a {area:442} para ir a {zone:1440}.",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang."] = "Los Lobos feroces rabiosos recorren el bosque alrededor del cementerio y de {npc:289}; los Lobos feroces hambrientos, las colinas al noreste de él. Las Telarácnidas pigmeovenenosas merodean al este del cementerio y sueltan el veneno. Cualquier necrófago de la mitad norte del cementerio puede soltar un colmillo.",
		["Ride back east along the road to the {area:245}."] = "Vuelve al este por el camino hasta {area:245}.",
		["Ride back east to {area:42}."] = "Vuelve al este hasta {area:42}.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Ve al norte por el Bosque de Elwynn hasta {zone:1453}; Mathias Shaw está en el SI:7, en {object:2100}.",
		["Ride west along the road once more."] = "Ve otra vez al oeste por el camino.",
		["Ride west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Ve al oeste por el camino, sal de {area:94} y entra en {zone:1436}. {npc:7024} vigila la torre de {npc:7053} desde las colinas, justo pasada la frontera. El {npc:7051} (nivel 23) que guarda la torre lleva su llave; el diario de Klaven está en el cofre de arriba.",
		["Ride west to the hermit once more."] = "Ve otra vez al oeste hasta el ermitaño.",
		["Rot Blossoms"] = "Flores podridas ({item:1598})",
		["Shaman training"] = "Entrenamiento de chamán",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "Los horrores esqueléticos ({npc:202}) recorren la ladera entre {area:42} y el {area:121}, al sureste del pueblo; sueltan las flores podridas ({item:1598}).",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}."] = "Guerreros esqueléticos y Magos esqueléticos deambulan entre las tumbas al sureste de {area:42}, bajo la casa de {npc:302} en la colina. Cualquier esqueleto de {zone:1431} puede soltar un {item:2378}.",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "El cementerio está al norte de la aldea. Horrores esqueléticos y Mefistos esqueléticos recorren su mitad sur. {npc:522}, un élite, deambula entre las tumbas: mantente lejos de él.",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "La choza del ermitaño está en el bosque al noreste del {area:492}.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "El montón de tierra suelta está al sur de la granja, junto al viejo tocón.",
		["Train in {zone:1453}, north through {zone:1429}. Then take the boat from {area:17203} to {area:442}."] = "Entrena en {zone:1453}, al norte a través de {zone:1429}. Luego toma el barco de {area:17203} a {area:442}.",
		["Wolves, spiders and ghouls"] = "Lobos, arañas y necrófagos",
		["{area:492}, south"] = "{area:492}, sur",
		["{item:281046}, from the {object:673515}"] = "{item:281046}, del {object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, Suministros de alquimia",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{item:4371}, de {npc:3133}: existencias limitadas. ¿Agotado? {npc:1448}, en {area:150}, también lo vende.",
		["{item:7908}, in the chest"] = "{item:7908}, en el cofre",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, en el extremo norte del pueblo",
		["{npc:264}, in the town hall"] = "{npc:264}, en el ayuntamiento",
		["{npc:265}, in her house by the tavern"] = "{npc:265}, en su casa junto a la taberna",
		["{npc:267}, in the town hall"] = "{npc:267}, en el ayuntamiento",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, en la casa detrás del ayuntamiento",
		["{npc:273}, in the tavern"] = "{npc:273}, en la taberna",
		["{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "La casa de {npc:276} está en el extremo este del pueblo. {npc:3133} vende artículos de ingeniería en la casa de al lado.",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288} se esconde en la casa del extremo oeste de {area:94}.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: Venenos y {item:18160}",
		["{npc:633}, at the south end of town"] = "{npc:633}, en el extremo sur del pueblo",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Mesón del Cuervo Escarlata",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888} está al sur del camino, en {area:245}.",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, en el sótano del Cuartel",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: botín poco frecuente de los enemigos de {zone:1431}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the {area:442} boat."] = "{zone:1453} no tiene instructor de chamanes: toma el {area:2257} desde el {object:28027} hasta {zone:1455}, entrena con {npc:258098} y vuelve en el tren para tomar el barco a {area:442}.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "Vuelve a la catedral: {npc:928} está dentro.",
		["Black Oozes"] = "Mocos negros",
		["Black Oozes creep through the marsh north of the {area:1025} road, west of {npc:2093}'s camp. Any ooze may hold {npc:2111}'s bag."] = "Los Mocos negros se arrastran por la marisma al norte del camino de {area:1025}, al oeste del campamento de {npc:2093}. Cualquier moco puede llevar la bolsa de {npc:2111}.",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Cathedral of Light"] = "La catedral",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "Los Acechadores de cuevas y los Acechadores sanguijuela llenan {area:1021}, la cueva al sureste de la excavación.",
		["Dragonmaw camp"] = "Campamento Faucedraco",
		["Escort Kerlonian to {area:413} in {zone:1440}."] = "Escolta a Kerlonian hasta {area:413}, en {zone:1440}.",
		["Fen Creepers"] = "Trepadores del cubil",
		["Fen Creepers hide in the marsh pools north-west of the {area:1025}."] = "Los Trepadores del cubil se esconden en las charcas de la marisma al noroeste de {area:1025}.",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "Sigue la costa al norte desde Puerto de Menethil. Los Múrlocs Branquiazul llenan la marisma; {npc:1259} camina con un grupo en medio.",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Sigue la costa al norte hasta {area:414}. {npc:3846} acampa en la playa; los nagas Colafuria llenan la orilla.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Sigue el camino al este hasta {area:419}; {npc:3916} está junto al pozo de la luna.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Sigue el camino al este. Los crocoliscos jóvenes de Los Humedales ({npc:1417}) acechan en las charcas al norte de la excavación.",
		["Follow the road north to {area:205}, at the foot of the {area:881}. {npc:1071} stands in the dwarves' camp."] = "Sigue el camino al norte hasta {area:205}, al pie de {area:881}. {npc:1071} está en el campamento de los enanos.",
		["Follow the road south-east to {area:415}, on the island in the lake."] = "Sigue el camino al sureste hasta {area:415}, en la isla del lago.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Para el Alto Señor Bolvar Fordragon en {object:2117}: guárdalo",
		["For the giant crocolisks of the north coast, on your next visit"] = "Para los crocoliscos gigantes de la costa norte, en tu próxima visita",
		["For {npc:2228} in {area:271}: keep it"] = "Para {npc:2228} en {area:271}: guárdalo",
		["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then ride south along the road through {zone:1439}."] = "Desde {area:17203}, toma el barco a {area:442}; {npc:3649} está en el extremo norte del pueblo. Después cabalga al sur por el camino a través de {zone:1439}.",
		["Hearth to Menethil"] = "Usa la piedra de hogar para ir a Puerto de Menethil",
		["Hearthstone on cooldown? Ride back north through the {area:1276}."] = "¿Piedra de hogar en reutilización? Cabalga de vuelta al norte por {area:1276}.",
		["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep."] = "Kerlonian duerme en {area:448}, al sur de {zone:1439}. Usa el {item:13536} para despertarlo y llévalo al sur por el camino hasta {zone:1440}, con {npc:11219} en {area:413}; vuelve a tocar el cuerno cada vez que se duerma.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "Mata a los elementales para conseguir 5 brazales elementales intactos ({item:12220}) y luego usa el {item:5456}",
		["Mosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Los Correcubiles Pellejomusgo y los tejebrumas recorren las orillas del río justo al oeste y al sur de {npc:1244}; casi todos sueltan pedernal.",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "Los Gnolls Pellejomusgo y los bastardos ocupan las colinas al sureste de {area:1025}.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site."] = "Los Raptores jaspeados y los estridadores recorren las colinas al oeste de la excavación.",
		["Next: fly to {area:42}."] = "Siguiente: vuela a {area:42}.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Al norte de Atalaya de Maestra, hay haces de plantas alrededor de las ruinas de {area:411}. Los sectarios de la Facción Oscura ocupan las ruinas justo al sur: cualquiera de ellos puede soltar la {item:5366}.",
		["Only if you looted {quest:337} in {zone:1431}"] = "Solo si despojaste {quest:337} en {zone:1431}",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Solo con {item:5352} de {zone:1439}: {npc:2786}, {object:32383}",
		["Raptor valley"] = "El valle de los raptores",
		["Ride east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "Cabalga al este por el camino de {zone:1437}, al sur por {area:836} hasta {zone:1432} y al oeste por el túnel hasta {zone:1426}, hasta {area:1537}.",
		["Ride south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "Cabalga al sur pasando {area:421} hasta el túnel de {area:1276}; sale en {area:461}, en Sierra Espolón. {npc:4080} y {npc:4077} acampan en {area:1076}, al suroeste del risco.",
		["Ride west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Cabalga al oeste hasta la orilla de {area:441}. Teronis yace entre los múrlocs Gapo Salino; cualquier múrloc puede soltar la {item:5463}.",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "Al sur de los múrlocs, {npc:3585} espera en {area:416}.",
		["Take the boat from {area:17203} to {area:442} and fly to {area:702}; {npc:11401} is in the Temple of the Moon. Then fly back to {area:442}."] = "Toma el barco de {area:17203} a {area:442} y vuela a {area:702}; {npc:11401} está en el templo. Después vuelve volando a {area:442}.",
		["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then fly to {area:702} (by way of {area:442})."] = "Toma el barco de {area:17203} a {area:442}. Une las dos mitades del colgante en {item:15885} y lanza {spell:18960}: {npc:11802} está en {area:2361}. Después vuela a {area:702} (pasando por {area:442}).",
		["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "Toma el portal para subir a {area:1658} y luego vuelve volando a {area:442}.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Toma el {area:2257} desde {object:171524} hasta {object:28027} de {zone:1453} y luego camina hasta {object:2098}.",
		["The Bluegill hovels"] = "Las chozas Branquiazul",
		["The Dragonmaw camp lies south of the road, just west of the {area:1025}: Raiders, Swamprunners and Bonewarders. {npc:2092}'s quest in {zone:1426} needs level 28."] = "El campamento Faucedraco está al sur del camino, justo al oeste de {area:1025}: asaltantes, correpantanos y guardahuesos. La misión de {npc:2092} en {zone:1426} requiere nivel 28.",
		["The Foulweald"] = "Los fúrbolgs Maderiza",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "Los fúrbolgs Maderiza viven en el bosque al sur del camino, al sureste de {area:415}. El Vigilante del cubil Maderiza y los ursas Maderiza guardan el cubil.",
		["The Mosshide gnolls"] = "Los gnols Pellejomusgo",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "Ventura y Cía. tala el bosque de {area:461}. Leñeros y deforestadores trabajan por todas partes; los operadores manejan las trituradoras y uno lleva los planos.",
		["The bigger raptors hunt in the valley just west of the dig."] = "Los raptores más grandes cazan en el valle justo al oeste de la excavación.",
		["The excavation site sits on the hill south of the road."] = "La excavación está en la colina al sur del camino.",
		["The raptor hills"] = "Las colinas de los raptores",
		["The tears glow on the small isle east of {area:415}."] = "Las lágrimas brillan en el islote al este de {area:415}.",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Tres contenedores en las chozas de los múrlocs, de sur a norte: {object:261}, luego {object:142151} y luego {object:259}, en el extremo norte.",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "Hay montones de madera y hierro alrededor del castillo y a lo largo de las murallas del puerto.",
		["To {area:150}"] = "Hacia {area:150}",
		["Venture Co. loggers"] = "Leñeros de Ventura y Cía.",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "Al oeste del Lago Mystral, los arbustos de polvo estelar crecen entre las ruinas.",
		["Young crocolisks"] = "Crocoliscos jóvenes",
		["grind on Dragonmaw Raiders and Swamprunners at the Dragonmaw camp, {zone:1437}"] = "mata Asaltantes Faucedraco y correpantanos en el campamento Faucedraco, {zone:1437}",
		["{item:15885}: join the two halves"] = "{item:15885}: une las dos mitades",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, en las ruinas de la orilla",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} y {npc:258785} están en {object:32386}, en {object:32362}.",
		["{npc:1239}, in the inn"] = "{npc:1239}, en la posada",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, en el muelle al norte de la posada",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: para {npc:2104}, en el castillo",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, en la biblioteca real",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, en {object:2098}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, en {object:32372}",
		["{npc:2086}, by the keep"] = "{npc:2086}, junto al castillo",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} acampa junto al camino; {npc:1244} está más al este, junto al río.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, junto a la puerta norte",
		["{npc:2096}, by the north gate"] = "{npc:2096}, junto a la puerta norte",
		["{npc:2097}, by the north gate"] = "{npc:2097}, junto a la puerta norte",
		["{npc:2104} stands in {area:2103}, a short walk from {npc:1242}."] = "{npc:2104} está en {area:2103}, a poca distancia de {npc:1242}.",
		["{npc:3649}: Alexston's reply"] = "{npc:3649}: la respuesta de Alexston",
		["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664} y sus abisarios ocupan {area:412}, al sur del santuario. Atrae primero a sus guardias.",
		["{npc:3691}, in the inn"] = "{npc:3691}, en la posada",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885} está en {area:420}, en la orilla este de {area:421}; {npc:210995} acampa en su orilla oeste. Los Elementales de agua podrida vadean el lago entre ellos.",
		["{npc:3987} (25) leads the Thistlefur gnolls at the camp north of {area:415}. Clear his guards first, one at a time."] = "{npc:3987} (25) dirige a los gnols Piel de Cardo en el campamento al norte de {area:415}. Acaba primero con sus guardias, de uno en uno.",
		["{npc:4201}, in the hut north of them"] = "{npc:4201}, en la choza al norte de ellos",
		["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines."] = "{npc:4276} extrae en {area:2160}, en el extremo este del risco. Habla con él y rechaza a los asaltantes de Ventura y Cía. mientras extrae.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, la quesería de {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} y {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, en la catedral",
		["{object:2164} is in the {object:2101}."] = "{object:2164} está en {object:2101}.",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009} recorre la punta norte de {area:414} con guardias Colafuria.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, de los haces de plantas",
		["{zone:1455} priests"] = "Sacerdotes de {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to Menethil"] = "Vuelta a Menethil",
		["Back to {area:42}"] = "Vuelta a {area:42}",
		["Bluegill Raiders"] = "Asaltantes Branquiazul",
		["Dragonmaw camp"] = "Campamento Faucedraco",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Sigue los cañones al este hasta El Desierto de Sal. Los goblins y gnomos del {area:2240} son neutrales y dan misiones a ambas facciones.",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it."] = "Sigue la costa al norte hasta el barco naufragado. Los marineros malditos ({npc:1157}) recorren la playa y los marinos malditos ({npc:1158}), la cubierta; {npc:1159} está en la playa junto a la proa. Los crocoliscos gigantes de Los Humedales ({npc:2089}) acechan en la costa, justo al norte.",
		["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "Sigue la costa al noreste, pasado el naufragio: los Asaltantes Branquiazul ocupan la marisma más allá de los Crocoliscos gigantes.",
		["Follow the road east to the excavation site."] = "Sigue el camino al este hasta la excavación.",
		["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "Para la catapulta Faucedraco, en la vuelta por {zone:1437} de la siguiente guía",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Para {npc:1212}, en {zone:1453}, en la siguiente guía",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "Para {npc:1284}, en {zone:1453}, en la siguiente guía",
		["For {npc:4048} in {zone:1444}, much later"] = "Para {npc:4048}, en {zone:1444}, mucho más tarde",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Para {npc:482}, en {zone:1453}, en la siguiente guía",
		["For {quest:5762} in Stranglethorn, later"] = "Para {quest:5762}, en la Vega de Tuercespina, más tarde",
		["From Theramore follow the road west out of Dustwallow into the {zone:1413} and south along it; give {area:378} a wide berth. {area:485} at the {zone:1413}' south end takes you down into {zone:1441}. The journal lies at the foot of the lift."] = "Desde Theramore sigue el camino al oeste, sal del Marjal Revolcafango, entra en {zone:1413} y baja al sur por él; mantente bien lejos de {area:378}. {area:485}, en el extremo sur de {zone:1413}, te baja a {zone:1441}. El diario está al pie del elevador.",
		["From {npc:352} in {zone:1453}"] = "De {npc:352}, en {zone:1453}",
		["Her house stands on the hill south-east of {area:42}."] = "Su casa está en la colina al sureste de {area:42}.",
		["Nightbane Dark Runners"] = "Correoscuros Nocturnos",
		["Nightbane Shadow Weavers"] = "Tejesombras Nocturnos",
		["Nightbane Vile Fangs and the {npc:511}"] = "Colmilloviles Nocturnos y el {npc:511}",
		["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too."] = "¿No tienes {item:4371} para {quest:174}? {npc:3133} lo vende en la casa junto a la de {npc:276}, con existencias limitadas; {npc:1448}, en {area:150}, también lo vende.",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "En el camino al sur por {zone:1413}, {npc:6244} acampa al este del camino, al noreste de {area:378}; acércate desde el este y evita a los guardias de la Horda.",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Solo si un {npc:272273} soltó {quest:96138}: haz clic derecho en él",
		["Plague Spreaders"] = "Propagadores de la Peste",
		["Ride back west along the road to {area:150}."] = "Vuelve al oeste por el camino hasta {area:150}.",
		["Ride east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "Cabalga de nuevo al este, hasta el campamento Faucedraco. Los cuatro juegos de Planes de ataque están en {area:1036}; {npc:2091}, un élite, también está en el campamento.",
		["Ride east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Ve al este hasta el túmulo de los ogros. {object:119} está en el campamento de la entrada; lo vigilan ogros Puñastilla.",
		["Ride west along the road; the hermit's shack stands north-east of the {area:492}."] = "Ve al oeste por el camino; la choza del ermitaño está al noreste del {area:492}.",
		["Skeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp."] = "Asaltantes, Sanadores y Guardas esqueléticos ocupan la parte oeste del cementerio, justo al este del campamento de {npc:311}.",
		["Take the boat from Menethil's pier to {area:513} in {zone:1445}."] = "Toma el barco del muelle de Menethil a {area:513}, en {zone:1445}.",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Los Correoscuros merodean por el bosque al sur del camino, al oeste de {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "El campamento Defias está en el suroeste de {zone:1431}, al sur de {area:94}, cerca de la frontera con {zone:1436}. La caja fuerte está entre las tiendas.",
		["The Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Los orcos Faucedraco acampan al este de la excavación. Los Asaltantes y Correpantanos llevan los estandartes de guerra.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him."] = "Los Propagadores de la Peste recorren la mitad norte del {area:492}. {npc:522}, un élite, deambula entre las tumbas: mantente lejos de él.",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "El capitán recorre la cubierta del barco naufragado; su caja fuerte está en la bodega.",
		["The dig and {npc:1353}"] = "La excavación y {npc:1353}",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "Las reliquias están en la propia excavación. {npc:1353}, un Tajobuche grande, merodea por el valle de los raptores, justo al oeste.",
		["The salt flats"] = "El Desierto de Sal",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery."] = "Los ferocanis más fuertes recorren el bosque al sur de {area:42}, al oeste y al sur del {area:121}. El {npc:511} se esconde en la pequeña cripta junto al cementerio.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Los ferocanis ocupan el bosque de la Arboleda del Destello, al oeste de {area:42} y al norte del camino. Atráelos de uno en uno.",
		["The wreck of the Third Fleet"] = "El naufragio de la Tercera Flota",
		["To Theramore"] = "A Theramore",
		["Wait a moment, then speak with her again"] = "Espera un momento y vuelve a hablar con ella",
		["{area:492}, west"] = "{area:492}, oeste",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, de {npc:1464}",
		["{item:2661}: the {object:331}"] = "{item:2661}: el {object:331}",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, de {npc:3133}, si no tienes",
		["{npc:1078} and Whelgar"] = "{npc:1078} y Whelgar",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}, en el piso de arriba de la posada",
		["{npc:1239}, in the inn"] = "{npc:1239}, en la posada",
		["{npc:2104}, by the keep"] = "{npc:2104}, junto a la fortaleza",
		["{npc:2104}, in {area:2103}"] = "{npc:2104}, en {area:2103}",
		["{npc:263}, in the town hall"] = "{npc:263}, en el ayuntamiento",
		["{npc:267}, in the town hall"] = "{npc:267}, en el ayuntamiento",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, en la casa detrás del ayuntamiento",
		["{npc:276}, at the east end of town"] = "{npc:276}, en el extremo este del pueblo",
		["{npc:311}'s Camp"] = "El campamento de {npc:311}",
		["{npc:4454}: for Martek in the {zone:1418}, later"] = "{npc:4454}: para Martek, en {zone:1418}, más tarde",
		["{npc:661}, by {npc:633}'s house"] = "{npc:661}, junto a la casa de {npc:633}",
		["{npc:663}, by the town hall"] = "{npc:663}, junto al ayuntamiento",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Mesón del Cuervo Escarlata",
		["{npc:840}, at the north entrance of town"] = "{npc:840}, en la entrada norte del pueblo",
		["{object:19868} lies all over the flats. Scorpid Reavers, Sparkleshell Tortoises and Saltstone Basilisks roam the north half, Crystalhides, Scorpid Terrors and Snappers the middle, and the Gazers (34-35, five levels above you: one at a time) the far south. Vultures circle over all of it."] = "Hay {object:19868} por todo el desierto. Atracadores escórpidos, Tortugas caparallantes y Basiliscos Gapo Salino recorren la mitad norte; Vitropieles, Terrores escórpidos y Sacudidores, el centro; y los Observadores (34-35, cinco niveles por encima de ti: de uno en uno), el extremo sur. Los buitres sobrevuelan toda la zona.",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: en {zone:1440}, de camino a {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: el íncubo, junto a la súcubo; la {item:190309} está cerca de {quest:1738}",
		["{quest:98221}: {quest:465} comes after it on Forever"] = "{quest:98221}: en Forever, {quest:465} viene después",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}"] = "Una nueva {item:279996}, para los cuatro vigías titánicos de {zone:1437}",
		["A report for {object:2117}"] = "Un informe para {object:2117}",
		["Back south down the road to the excavation site."] = "Vuelve al sur por el camino hasta la excavación.",
		["Back to the same murlocs; not every one drops a head."] = "Vuelve a los mismos múrlocs; no todos sueltan una cabeza.",
		["Boat to {area:271}"] = "Barco a {area:271}",
		["Cathedral of Light"] = "Catedral de la Luz",
		["Daggerspine naga"] = "Nagas Espinadaga",
		["Druid training"] = "Instrucción de druida",
		["Farren"] = "Teniente Farren Orinelle",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east to {area:118}."] = "Sigue el camino hacia el este hasta {area:118}.",
		["Follow the road north-east into the {area:1025}: {npc:270637} camps beside it, {npc:1244} a short way east."] = "Sigue el camino hacia el noreste hasta {area:1025}: {npc:270637} acampa junto a él y {npc:1244}, un poco al este.",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Para el Rey Magni Barbabronce en {zone:1455}, al final de esta guía",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Para {npc:2916} en {zone:1455}, al final de esta guía",
		["From {npc:2432} in {area:271}"] = "Desde {npc:2432} en {area:271}",
		["Level 30 and 32 spells"] = "Hechizos de nivel 30 y 32",
		["Murloc heads"] = "Cabezas de múrloc",
		["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "Al norte por el camino hasta {area:205}. {npc:271460} está en las ruinas (usa la {item:279996}); {npc:271481} está retenido en el lado oeste: llévalo hasta {npc:1072}.",
		["North-east to the {area:1038}: the {npc:271373} are held there, and {npc:271338} stands at the gates (use the {item:279996})."] = "Al noreste, hasta {area:1038}: allí retienen a {npc:271373} y {npc:271338} está en las puertas (usa la {item:279996}).",
		["Pick up everything in town before heading out. Off the boat, {npc:251493} is the first you meet, north-west of the flight master; {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Recoge todo en el pueblo antes de salir. Al bajar del barco, {npc:251493} es el primero que encuentras, al noroeste del maestro de vuelo; {npc:2381} y {npc:2438} están entre el maestro de vuelo y la posada; el Teniente Farren Orinelle y {npc:2366}, en la posada; el Magistrado Henry Maleb, en el ayuntamiento.",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; {npc:271458} stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised."] = "Las Crías rojas llenan las colinas al oeste de las puertas; los Garrapútrea enajenados, {area:1025}; los Tajobuche, las laderas del norte. {npc:271458} está en el noreste (usa la {item:279996}).\n{quest:98283} es élite: se recomienda ir en grupo.",
		["Snapjaws"] = "Quijafortes",
		["South to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Al sur, hasta {area:1036} de los Faucedraco: la primera catapulta está de camino y {object:671518} está en el campamento.",
		["Syndicate camp"] = "Campamento del Sindicato",
		["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "Toma el {area:2257} desde {object:28027} hasta {zone:1455}.",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "Los Guardianes de Goaz están justo al oeste del campamento del Prospector Whelgar: usa junto a uno la {item:279996} que te dio.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Las tortugas Quijaforte toman el sol junto al río al este de {area:271}, al sur de {area:272} (Horda).",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "El campamento del Sindicato está en la frontera con las Montañas de Alterac, al norte de {area:287}, al oeste de {area:272} (Horda); los documentos están en el campamento.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}."] = "Los múrlocs Rompeanca abarrotan {area:295}, al suroeste de {area:271}.",
		["The Villards"] = "Los Villardo",
		["The cheese shop in the {object:2096}."] = "La quesería de {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Los nagas ocupan la costa al sureste de {area:271}.",
		["The next step, Defeat Nek'rosh, pits you against an elite chieftain: skip it."] = "El siguiente paso, Derrota a Nek'rosh, te enfrenta a un jefe élite: sáltatelo.",
		["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "Los yetis viven en la cueva de las colinas al norte de {area:271}, de camino de vuelta al sur.",
		["Torn Fin murlocs"] = "Múrlocs Rompeanca",
		["West along the road to Menethil."] = "Al oeste por el camino hasta Puerto de Menethil.",
		["West to the farms of {area:287}: place the {item:279386} on the bookkeeping table in the town hall, where {npc:2335} and the councilmen stand."] = "Al oeste, hasta las granjas de {area:287}: pon la {item:279386} en la mesa de contabilidad del ayuntamiento, donde están {npc:2335} y los Consejeros de Trabalomas.",
		["Whelps, raptors and {npc:271458}"] = "Crías, raptores y {npc:271458}",
		["Yeti cave"] = "Cueva de los yetis",
		["{area:287} town hall"] = "Ayuntamiento de {area:287}",
		["{area:287}'s town hall"] = "Ayuntamiento de {area:287}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, de {npc:2381}",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}: {quest:98283}, un raptor élite",
		["{npc:2104} stands in {area:2103}; {npc:2094} stands by the north gate."] = "{npc:2104} está en {area:2103}; {npc:2094} está junto a la puerta norte.",
		["{npc:2104}: for {npc:270637}"] = "{npc:2104}: para {npc:270637}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, en la posada: para {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: los leones vienen después",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438} Ginsetti también quiere una {item:3719}, un {item:2997} e {item:2321}: fabricados o comprados; la capa se entrega cuando vuelvas a {area:271} más tarde.",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708} está en {object:2164}; {npc:211033}, cerca del canal; {npc:5081}, al sur de {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: su rastro lleva a las Tierras Altas de Arathi",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462} está en las colinas del sureste: usa la {item:279996} junto a él.",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera en la taberna del Cerdo y el Silbato, en {object:2100}; él y sus dos matones pelean contigo, pero paran al ser derrotados.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} entrena a los guerreros en {object:2100}, junto al Cerdo y el Silbato. {npc:6236} espera en {area:720}, en {zone:1413}, de camino a {area:392} mucho más tarde (40-50/01).",
		["{npc:5683} waits north of {area:205} by the {area:881}; {npc:271322} a short walk further north-east."] = "{npc:5683} espera al norte de {area:205}, junto a {area:881}; {npc:271322}, un poco más al noreste.",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455} no tiene instructor de druidas: entrena con {npc:5504} en {zone:1453} antes del tranvía.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort the caravan"] = "Escolta la caravana",
		["Escort {npc:5644}"] = "Escolta a {npc:5644} Malem",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Sigue el camino hacia el oeste pasando {area:460} (Horda) y al suroeste por {area:465} hasta {zone:1443}; {area:608} está en lo alto del paso.",
		["From {area:415} head south-west to the {area:1276}, a tunnel through the mountains into Stonetalon."] = "Desde {area:415}, ve al suroeste hasta {area:1276}, un túnel a través de las montañas hasta Sierra Espolón.",
		["From {area:415} ride north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "Desde {area:415}, cabalga hacia el noroeste por las colinas: {quest:1738} es un árbol brillante al norte del camino a {area:413}. Si aceptaste {quest:65602}, la {item:190309} está en una casa entre los árboles al norte de {area:413} (26.6,22.0). Después vuelve pasando por {area:415} hasta {area:1276}.",
		["From {zone:1455}'s {npc:1573}"] = "Desde {npc:1573}, en {zone:1455}",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "Su hermano {npc:5643} Malem (36) recorre la fortaleza con los Fieles Filo Ardiente (30-33): atráelo solo. {npc:13019} guarda el cetro en el edificio principal de la fortaleza.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Saca a {npc:5644} Malem de la fortaleza; se marcha cuando estéis fuera. {npc:5642} recibe la entrega en {area:608} al final de la guía.",
		["Malem chest"] = "Cofre de Malem",
		["Out of Thunder Axe Fortress"] = "Fuera de la Fortaleza del Hacha de Trueno",
		["Scorpashi venom"] = "Veneno Scorpashi",
		["Take the boat to {area:442} from Menethil's docks."] = "Toma el barco a {area:442} en los muelles de Puerto de Menethil.",
		["The Gizelton Caravan waits at {area:2407}."] = "La caravana Gizelton espera en {area:2407}.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}."] = "Los sátiros Odio Feroz ocupan las ruinas de {area:603}, al este de {area:608}.",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Los Kolkar recorren las llanuras alrededor de {area:609}; sus orejas son para {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "Los escórpidos Scorpashi cazan en las colinas alrededor de {area:2407}, en el camino al sur.",
		["The chest lies in the ruins south-west of {area:608}."] = "El cofre está en las ruinas al suroeste de {area:608}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Usa el {item:13892} de {npc:11596} en un {npc:4700} y lleva el kodo domado a su campamento, cinco veces; los Kodos envejecidos también sueltan los pellejos.",
		["Walk with the caravan south past {area:609}; Kolkar ambushers jump it on the way. Stay close until it stops at {area:2617}. The ambushers are 34-35 and come in waves: skip it if you are below 33."] = "Acompaña a la caravana hacia el sur pasando {area:609}; los Emboscadores Kolkar la asaltan por el camino. Quédate cerca hasta que pare en {area:2617}. Los emboscadores son de nivel 34-35 y vienen en oleadas: omítela si eres de nivel inferior a 33.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, al norte de {area:413}",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "El campamento de {npc:11596} está en el camino al sur de {area:609}, junto a {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "La torre de {npc:11863} Aldamort está en la colina al oeste de {area:599}: acepta antes su misión; el cetro que quiere está en la fortaleza.",
		["{npc:5643} and the Seer"] = "{npc:5643} Malem y el Vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} Malem se esconde en la fortaleza del Filo Ardiente, al suroeste de {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Vara de transformación de Dartol",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Sigue el camino hacia el este hasta los campamentos sátiros de {area:429}; {npc:3920} se esconde en su borde.",
		["Follow the road west out of {area:415}; {area:413} lies north of it."] = "Sigue el camino hacia el oeste desde {area:415}; {area:413} queda al norte.",
		["From {area:608}"] = "Desde {area:608}",
		["Insane druids"] = "Druidas dementes",
		["Lightforge Ingots"] = "Lingotes Forjaluz",
		["Melyria and {npc:3901}"] = "Melyria e {npc:3901}",
		["Rusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel."] = "Hay cofres oxidados alrededor de los campamentos furbolg Sombramatorral al oeste de los Renegados; ábrelos hasta que uno tenga el pomo.",
		["Take the boat to {area:150} from {area:442}'s docks."] = "Toma el barco a {area:150} en los muelles de {area:442}.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Entra por el túnel en {area:419}; el tomo está en las ruinas de su extremo oeste.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Los múrlocs Branquiazul de la playa al suroeste de Menethil llevan los lingotes.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Los Ancianos enloquecidos y los Ancianos marchitos al norte del pozo de la luna llevan la {item:5475}; el cofre gastado que abre está entre ellos.",
		["The Forsaken's camp lies in the woods south of {area:2358}."] = "El campamento de los Renegados está en el bosque al sur de {area:2358}.",
		["The moonwell lies in the hills north-east of {area:415}."] = "El pozo de la luna está en las colinas al noreste de {area:415}.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "El segundo {object:19901} está en el valle de {area:428}, de camino al oeste.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "El santuario está en la colina justo al sureste del pozo de la luna; sube por el sendero sinuoso.",
		["The three druids stand together at the Forsaken camp south of {area:2358}."] = "Los tres druidas están juntos en el campamento de los Renegados al sur de {area:2358}.",
		["The two stand together at the western end of the road."] = "Las dos están juntas en el extremo oeste del camino.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "El pecio del Flying Osprey está en las aguas poco profundas al sur del torreón.",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way."] = "El {npc:3931} recorre la orilla del {quest:1035}, al suroeste de los cofres; el {object:669176} está al norte del lago, de camino.",
		["The {object:19901} stands in the satyr camp of {area:430}, further east along the road."] = "El {object:19901} está en el campamento sátiro de {area:430}, más al este por el camino.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}, el puesto de los elfos de la noche en el extremo este del camino: allí está {npc:3848}.",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} está en la planta superior del torreón de Menethil.",
		["{npc:3696} and his guards camp just east of {npc:3897}."] = "{npc:3696} y sus guardias acampan justo al este de {npc:3897}.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, un furbolg al que no ha tocado la corrupción, está sentado al sur del camino, bajo {area:421}.",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide"] = "{npc:3970}: para {npc:1480} en Menethil, al final de esta guía",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} lidera a los sátiros de {area:429}; él lleva la rama.",
		["{npc:5082}, {npc:4963} and Tapoke Jahn are all at Menethil's inn; {npc:4962} fights you when you talk to {npc:4963}, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn."] = "{npc:5082}, {npc:4963} y {npc:4962} están en la posada de Menethil; Tapoke te ataca cuando hablas con {npc:4963}, pero se rinde al ser derrotado. {npc:1480} está a poca distancia al noreste de la posada.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: para {npc:3961} en {area:415}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Vuelve al sur, pasado Nesingwary: las Panteras y los Raptores de Tuercespina corren por los claros al oeste del campamento, hacia la costa; los tigres mayores ocupan las colinas del suroeste.",
		["Bloodscalp trolls"] = "Trols Cabellesangre",
		["Both roam the grass around the camp and along the road north."] = "Ambos recorren la hierba alrededor del campamento y a lo largo del camino al norte.",
		["Down to {area:35}"] = "Bajada a {area:35}",
		["Druid training"] = "Entrenamiento de druida",
		["Fly from {area:150} to {area:1537} and train."] = "Vuela de {area:150} a {area:1537} y entrena.",
		["Fly to {area:42}: {npc:1573} in {area:1537}'s {object:32372}, or {npc:352} in {zone:1453}'s {object:2096}."] = "Vuela a {area:42}: {npc:1573}, en {object:32372} de {area:1537}, o {npc:352}, en {object:2096} de {zone:1453}.",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Sigue el camino principal al sur a lo largo de toda la selva, pasado el desvío a {object:3202}, hasta {area:35}, en el cabo sur.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Sigue la costa oeste al norte; la isla fantasma está frente a la orilla, al oeste del campamento de Nesingwary. Basta con llegar a ella.",
		["For Archmage Ansirem in {zone:1416}"] = "Para el Archimago Ansirem, en {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Desde {zone:1431} toma el camino al sur hasta la Vega de Tuercespina; las tiendas de los cazadores están justo al oeste del camino, pasado el desvío al {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un múrloc raro de la costa al oeste del campamento, suelta el {item:4614}: cógelo si te lo encuentras",
		["Gyll, on the top floor by the docks"] = "Gyll, en el piso de arriba junto a los muelles",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "Los Reductores de cabezas están en el interior de la base; los Comandos acechan en sigilo a su alrededor y en la cueva. Recoge las páginas de Las verdes colinas según caigan.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Los documentos de Herod están en una cabaña del lado oeste de la base; su caja fuerte está más al este, junto a la entrada de la cueva.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Recorre en círculo las ruinas trols del norte y del centro: cada una guarda una tablilla de piedra con las leyendas trols. Las Panteras Faucesombría merodean en sigilo por la selva que las rodea; en el campamento de Ventura y Cía. del {area:37} están los Cristales caídos.",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores y tigres mayores",
		["River Crocolisks swim the river by the {area:99}."] = "Los Crocoliscos fluviales nadan en el río junto al {area:99}.",
		["River crocolisks"] = "Crocoliscos fluviales",
		["Skullsplitter trolls"] = "Trols Machacacráneos",
		["Snapjaw Crocolisks"] = "Crocoliscos Quijaforte",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "Los Crocoliscos Quijaforte toman el sol en la orilla y en las islas de la costa al norte de {area:35}.",
		["Stranglethorn Tigers"] = "Tigres de Tuercespina",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Toma el camino al norte; {npc:738} lo patrulla y el campamento está en las colinas del oeste.",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Los trols Cabellesangre ocupan las ruinas de la costa al oeste del campamento de Nesingwary.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Los rebeldes de Kurzen ocupan el campamento al este del {area:99}; recorre su borde exterior, donde están los Jíbaros y los Auxiliadores, y saquea las cajas de suministros junto a las tiendas.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Los trols Machacacráneos ocupan las ruinas al este del camino entre Nesingwary y {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Los tigres adultos merodean por las colinas justo al sur y al oeste del campamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Los tigres mayores vienen después, a la vuelta del {area:99}",
		["The haunted island"] = "La isla fantasma",
		["The jungle ruins"] = "Las ruinas de la selva",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "El mineral lo sueltan los kóbolds Mostacho Seco de {zone:1417}",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "Thorsen patrulla el camino al norte del campamento, hacia el {area:99}.",
		["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards."] = "Vuelve al norte; la {area:310} está al oeste del camino, en el centro de la selva. Los Basiliscos Espina de Cristal de allí sueltan los fragmentos.",
		["Young tigers and panthers"] = "Tigres y panteras jóvenes",
		["{area:1537} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{area:1537} no tiene instructor de druidas: toma el {area:2257} desde {object:171524} hasta {zone:1453} y entrena con {npc:5504}.",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de una caja de {object:263}",
		["{npc:2495}, by the bank"] = "{npc:2495}, junto al banco",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, en la {object:56910}",
		["{npc:469}, in the hut"] = "{npc:469}, en la cabaña",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, desde {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} colecciona {item:2755}: casi todos los humanoides de la selva sueltan las páginas. Convierte las páginas en capítulos sobre la marcha.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} y los raptores colazote",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, el gran tigre, tiene su guarida en la cima de la colina al suroeste del campamento; los Raptores colazote corren al sur de ella, de camino a {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, en la taberna",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773}, en {area:35}",
		["{npc:773}, in the tavern"] = "{npc:773}, en la taberna",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: basta con echar un vistazo por el campamento de los cazadores",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Un {npc:2434} acecha sin ser visto en las afueras de {area:271}; mátalo y lee el contrato que lleva.",
		["Back west through {zone:1430} to {area:42}."] = "Vuelve al oeste por {zone:1430} hasta {area:42}.",
		["Crushridge ogres"] = "Ogros Aplastacresta",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}."] = "Cada llave está en uno de los círculos de piedras de las Tierras Altas: al este de los fragmentos, cerca de {area:320} y en el oeste. La {object:2702} está al oeste de {area:320}.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Al este por el camino hasta {area:76}. Los {npc:256028} sueltan los cristales; Noboru recorre las ruinas y suelta su garrote.",
		["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "Escolta al profesor hasta la playa al norte de la cala y protégelo mientras trabaja; los nagas atacan en oleadas.",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Sigue el camino al este desde {area:287}, por {area:1057}, hasta {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Sigue el camino al norte desde {area:271} hacia las montañas. Los leones monteses recorren las laderas; los miembros del Sindicato de {area:280} llevan los anillos de sello, y {npc:2306} recorre los terrenos de la mansión en el lado norte del pueblo.",
		["Follow the road north to the draenei of the {area:657}."] = "Sigue el camino al norte hasta los draenei de {area:657}.",
		["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "Sigue el camino al sur por el puente hasta {area:205}, en el extremo de {zone:1437}, donde espera {npc:1075}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} en {zone:1453}: guárdalo",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} en {area:35}: guárdalo",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} en {area:35}: guárdalo",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} en {area:271}",
		["From {area:42} follow the road east through {zone:1430} into the {zone:1435}; Biggs guards the road junction just inside it. {npc:217412} stands a short way north of him."] = "Desde {area:42}, sigue el camino al este por {zone:1430} hasta {zone:1435}; Biggs vigila el cruce de caminos nada más entrar. {npc:217412} está un poco al norte de él.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Desde {zone:1455}, toma el túnel al este por {zone:1426} hasta {zone:1432} y sigue el camino hasta {area:144}.",
		["Gyll, {area:35}"] = "Gyll, {area:35}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Ve al norte pasando {area:314}; los fragmentos brillan en la colina junto a {area:333}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Solo si Gluggle te dio el colgante en Vega de Tuercespina",
		["Phizzlethorpe"] = "Fiseltor",
		["Ride back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "Cabalga de vuelta al noreste pasando {area:320}; {npc:2712} y {npc:2713} acampan en las colinas al norte de {area:314}.",
		["Shaman training"] = "Entrenamiento de chamán",
		["South-east along the loch to the dig site."] = "Al sureste por el lago hasta la excavación.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Al suroeste hasta el campamento del Kirin Tor en la orilla del lago al oeste de {area:279}, justo al otro lado de la frontera de {zone:1421}: allí está {npc:269127}. El archimago Ansirem está al sureste, junto a la cúpula.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way."] = "Quédate con {npc:2713} mientras se cuela en {area:314} y vuelve; los orcos de la Horda te atacan por el camino.",
		["Subdue the succubus"] = "Somete a la súcubo",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Los ogros Aplastacresta ocupan las colinas al norte de {area:280}. Más al norte, un cofre de madera gastado contiene el {item:3706}; {npc:2320}, de {quest:537}, está justo a su lado.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore."] = "Los kóbolds Mostacho Seco excavan en la garganta al este de {area:321} (Horda); rodea el pueblo por el norte. Sueltan tanto las motas como el mineral de Krazek.",
		["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off."] = "El Sindicato ocupa la granja al noroeste de {area:320}. Un {npc:217589} corretea por la granja: atrapa uno con el kit de iniciación a la entomología de {npc:217412} y márcalo.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Los trols Secacorteza viven en las colinas al sur de {area:314}; los médicos brujos están en el poblado y los cazadores de las Sombras guardan el fondo del valle.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "El mensajero recorre el camino al oeste de {area:314} con dos guardias; atráelos fuera del camino.",
		["The shards lie at the far end of {area:318}."] = "Los fragmentos están en el extremo de {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins."] = "Los tomos están en el castillo en ruinas al oeste de {area:280}; los Magos oscuros Artus ocupan las ruinas.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Los dos naufragios están en la bahía al oeste de la cala. Las cartas de navegación y los diarios están dentro; las gemas están en el fondo del mar a su alrededor. Los nagas Espinadaga nadan por toda la bahía.",
		["The western swamp"] = "El oeste de la ciénaga",
		["The wrecked caravan lies off the road near Biggs."] = "La caravana destrozada está fuera del camino, cerca de Biggs.",
		["The wrecks"] = "Los naufragios",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Vuelve al puente: Ebenezer yace bajo su extremo de Arathi.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Al oeste por la costa hasta la cala de los goblins; Lolo vigila desde las rocas de encima.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jóvenes, Girapenas y Jaguares del pantano recorren la ciénaga alrededor del camino.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} para la capa de {npc:2438}, de {npc:2381}, si no tienes",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Aplastacresta",
		["{item:3659}: the {object:1760}"] = "{item:3659}: la {object:1760}",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, camino de {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, en la catedral",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la biblioteca real del castillo",
		["{npc:185335}, at the same circle"] = "{npc:185335}, en el mismo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: tres bichos que atrapar en Tierras Altas de Arathi, {zone:1443} y Vega de Tuercespina",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: atrápalo, para {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} y {npc:2713}",
		["{npc:2713}'s errand"] = "El encargo de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, un ogro mago, ocupa la cueva del extremo sur del valle Secacorteza.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está enjaulado en el extremo norte del santuario. Libéralo y mantenlo con vida mientras salís; después, su cofre te espera junto al camino.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula el íncubo a ti",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}. Usa el {item:6913} en el círculo de invocación de allí y derrota a la súcubo que aparece. Si aceptaste {quest:65602}, entrégale también la {item:190309}, colócala en el mismo círculo y derrota al íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si la aceptaste",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train with {npc:258098}. {npc:1573} in the {object:32372} flies to {area:271} too."] = "{zone:1453} no tiene instructor de chamanes: toma el {area:2257} desde {object:28027} hasta {zone:1455} y entrena con {npc:258098}. {npc:1573}, en {object:32372}, también vuela a {area:271}.",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Vuela a Theramore",
		["Follow the road north to {area:608}."] = "Sigue el camino hacia el norte hasta {area:608}.",
		["Follow the road south to {area:2407}."] = "Sigue el camino hacia el sur hasta {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Sigue el camino hacia el oeste por el norte de {zone:1443} hasta las ruinas de {area:2405}. La torre de {npc:11863} está en la colina de allí, de camino al naufragio.",
		["Greater Rock Elementals"] = "Elementales de piedra mayores",
		["Lesser Rock Elementals"] = "Elementales de piedra inferiores",
		["Maraudine centaurs"] = "Centauros Maraudine",
		["Ogres and buzzards"] = "Ogros y águilas ratoneras",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Vuelve al oeste hasta el camino y síguelo hacia el sur, fuera de {zone:1432}, por el paso hasta {zone:1418}. {npc:2910} y {npc:2860} acampan juntos en la excavación.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Cabalga al noreste hasta la excavación abandonada; el Cajón de provisiones de excavación está allí, entre los ogros Rotapolvo.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Cabalga al noreste hasta las ruinas enanas del norte de {zone:1418}; el cofre está entre los enanos Forjatiniebla. {npc:2745}, cerca, es élite: mantén la distancia.",
		["Ride south to {area:345}."] = "Cabalga al sur hasta {area:345}.",
		["Ride west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Cabalga al oeste hasta {area:1878}; {npc:2921} Veriatus trabaja junto a sus máquinas en el centro.",
		["Rock Elementals"] = "Elementales de piedra",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "El siguiente encargo del Prospector Ryedol es en {area:1517}: omítelo.",
		["Shadowforge camp"] = "Campamento Forjatiniebla",
		["Take the boat to Theramore from the far pier."] = "Toma el barco a Theramore en el muelle del fondo.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Los ogros Rotapolvo acampan justo al sur del valle; cualquiera suelta chatarra. Las águilas ratoneras sobrevuelan la llanura al este.",
		["The Greater Rock Elementals (level 42) walk the far south-west corner below {area:342}; pull them one at a time. The Dustbelcher Wyrmhunters and Maulers at {area:342} also drop scrap."] = "Los Elementales de piedra mayores (nivel 42) recorren el extremo suroeste, por debajo de {area:342}; atráelos de uno en uno. Los Cazavermis Rotapolvo y los Destructores de {area:342} también sueltan chatarra.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}."] = "Los Elementales de piedra inferiores deambulan por {area:1878}, al oeste de {npc:2921} Veriatus.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Los centauros Maraudine ocupan {area:607}, al oeste del cementerio; todos sueltan los tótems.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Los elementales de piedra ({npc:92}) recorren el sureste de {npc:2921}; las águilas ratoneras gigantes ({npc:2831}) y los coyotes del risco mayores ({npc:2729}) comparten la llanura al oeste.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Los enanos Forjatiniebla acampan justo al norte de la excavación; el Mapa arrugado está entre sus tiendas. Los Tuneladores y los Tejeoscuros llevan el Pico de la suerte de Ryedol. Los Coyotes del risco recorren las laderas de alrededor.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "El esqueleto maltrecho está justo al este de los ogros, al borde del campamento de los troggs Grutacanto; los Partehuesos y los Chamanes de alrededor sueltan las escamas. Theldurin el Perdido está sentado junto al campamento en ruinas, más al sur.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Las almejas están en la costa noroeste de la Vega de Tuercespina, en la siguiente guía: guárdala",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit."] = "Los demonios se reúnen en {area:602}, al sur de {zone:1443}: canes manáfagos (Devoradores de maná, Cazadores de magos y Cazadores Ley), Doncellas infernales y Hermanas infernales, y Capitanes Guardiavil alrededor del foso.",
		["The excavation crate"] = "El cajón de la excavación",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "El maestro de vuelo está junto a la puerta de {area:514}; {npc:5083} y {npc:4964} están dentro de la ciudadela.",
		["The next guide starts in Theramore."] = "La siguiente guía empieza en Theramore.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "La siguiente tarea del esqueleto, Murdaloc, espera a la guía posterior de {zone:1418}, a nivel 43.",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "El cofre del barco naufragado está en la orilla, justo al oeste de la torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Los Devastadores no-muertos recorren los campos de huesos al sur del Poblado Magram, al este del aquelarre; en el extremo sureste, usa el {item:15848} para atraer a los Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolta a {npc:12277} de vuelta hacia el cementerio",
		["for the Dustwallow loop in the next guide"] = "para la vuelta por Marjal Revolcafango de la siguiente guía",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} en {zone:1455}: guárdala",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} en {area:271}: guárdala",
		["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "para {npc:4454} en {area:439}: la guía de {zone:1446} pasa por allí a nivel 45, guárdala",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} en {zone:1455}: guárdala",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "solo si llevas {item:2868} (los fabrica un herrero)",
		["{npc:11626}'s caravan stops on the road east of {area:606}. Take the quest and walk with the kodos past the {area:602}, killing the demons that jump them; talk to {npc:11596} at his camp east of the {area:596} afterwards."] = "La caravana de {npc:11626} se detiene en el camino al este de {area:606}. Acepta la misión y acompaña a los kodos pasando {area:602}, matando a los demonios que los asaltan; después habla con {npc:11596} en su campamento al este de {area:596}.",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} está presa en el campamento centauro al oeste del cementerio. Libérala y mantenla con vida al salir; se detiene junto al cementerio.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, un jefe centauro, acampa en la costa noroeste, al norte de la torre de {npc:11863} Aldamort.",
		["{npc:1470}, in the inn"] = "{npc:1470}, en la posada",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: atrápalo, para My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, junto a {npc:2921} Veriatus",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "La siguiente prueba de {npc:2921} Veriatus requiere equipo fabricado: omítela.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} y {npc:2817} acampan juntos en {area:1877}, en el centro de {zone:1418}.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "La siguiente tarea de {npc:5638} Ungor, {item:6245}, se consigue en la costa lejana: omítela.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} está al borde de {area:596}, al suroeste de {area:2407}; {object:176751} están entre los esqueletos. Un {npc:217590} se arrastra por el cementerio: atrapa uno con el Entomology Starter Kit y márcalo.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Ignatz el \"Apestoso\"",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files {spell:1285849} under the one Riding skill, so {npc:4732} at {area:88} in eastern {zone:1429}, the nearest trainer to {zone:1453}, should teach it (unconfirmed). The Galestriders are sold by {npc:265756} in {area:16638} on Zephras Isle; Collectibles, Mounts · Level 40 lists them."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. No se conoce ningún instructor de equitación cielonato; el cliente de Forever incluye {spell:1285849} en la única habilidad de Equitación, así que {npc:4732}, en el {area:88}, en el este de {zone:1429}, el instructor más cercano a {zone:1453}, debería enseñarla (sin confirmar). Los zancavendavales los vende {npc:265756} en {area:16638}, en la Isla de Zephras; Coleccionables, Monturas · Nivel 40, los muestra.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:4732} enseña a los humanos en el {area:88}, en el este de {zone:1429}, junto a los caballos de {npc:384}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:4753} enseña a los elfos de la noche en {zone:1457}, junto a los sables de {npc:4730}: el barco de {area:17203} a {area:442} y luego el vuelo a {area:702}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar), como {npc:4732}, en el {area:88}, en {zone:1429}. Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:4772} enseña a los enanos en la {area:803}, al este de {area:131}, en el camino a {zone:1432}, junto a los carneros de {npc:1261}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:7954} enseña a los gnomos en el {area:189}, justo al este de {area:131}, junto a los mecazancudos de {npc:7955}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "De vuelta en Theramore: Tervosh espera con Lady Jaina en la torre de la {area:514}.",
		["Bloodsail camp"] = "Campamento Velasangre",
		["Bloodsail pirates"] = "Piratas Velasangre",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Cold Eye Basilisks"] = "Basiliscos Ojogélido",
		["Defeat the challengers and {npc:6238}"] = "Derrota a los aspirantes y a {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todos los Velasangre sueltan Barril de tabaco y uno de ellos lleva el ojo de {npc:2493}; los Aventureros recorren la orilla justo al norte del pueblo. Las cartas de navegación y las órdenes están en el campamento pirata de la {area:43}, al sur de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Cualquier seguidor de Zanzil puede soltar el mejunje; {npc:2537} recorre el sur del campamento.",
		["Fly to {area:42} and ride east through {zone:1430} into the {zone:1435}; {npc:5476} stands by the road just past the border."] = "Vuela a {area:42} y ve al este por {zone:1430} hasta {zone:1435}; {npc:5476} está junto al camino, justo pasada la frontera.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Sigue el camino al este de vuelta a Theramore. Tervosh, Lady Jaina y los oficiales están en la torre y en la {area:514}.",
		["Follow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals."] = "Sigue el camino al noreste hasta el campamento de Ventura y Cía. de la {area:310}; los mineros, peritos y supervisores sueltan los cristales.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "Sigue el camino al noroeste desde Theramore hasta la atalaya de {area:503}. Los Hurgadores Fangorroca recorren el pantano a su alrededor.",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "Zancavendavales: {npc:265756}, en {area:16638}, en la Isla de Zephras.",
		["Gorilla hills"] = "Colinas de los gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entrega los colmillos y quédate: llegan tres oleadas de gorilas, la última con {npc:1514}. Lucha con la salud al máximo.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Sal del pueblo por el túnel y sigue la costa al norte; la carta está en el campamento Velasangre de la playa, por donde camina \"El Guapo\" Duncan.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "La siguiente tarea de MacKinley te manda a por ogros élite: omítela.",
		["Mirefin murlocs"] = "Múrlocs Ancalodo",
		["Mudrock tortoises"] = "Tortugas Fangorroca",
		["Naga Explorers"] = "Expedicionarios Naga",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "De camino al norte hacia {area:392}, la {area:720} está frente a {area:391}, al sur del pueblo: cruza vadeando los bajíos del banco de arena. {npc:6236} te envía cuatro aspirantes y luego a {npc:6238} (nivel 33), de uno en uno.",
		["Paladin: {quest:1661}"] = "Paladín: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Vuelve a bajar al pueblo; Trémulo está en la entrada del túnel.",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "Vuelve al oeste por el camino; {npc:217412} está un poco al norte de Biggs.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Ve al este; los Horrores enredados del camino también sueltan los ensayos. Busca en la orilla de la {area:74}, donde las ruinas del templo asoman del agua.",
		["Ride from Theramore west along the Dustwallow road into the {zone:1413} and north to {area:392} on the coast. Learn the flight path from {npc:16227}, then take the boat to {area:35} from the dock."] = "Ve desde Theramore al oeste por el camino del Marjal Revolcafango hasta {zone:1413} y al norte hasta {area:392}, en la costa. Aprende la ruta de vuelo con {npc:16227} y luego toma el barco a {area:35} en el muelle.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Ve tierra adentro hasta las colinas de los gorilas del Valle del Velo de Bruma. Los Gorilas del Valle Velo de Bruma viejos sueltan las tripas; {npc:1449} está sentado entre ellos.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Ve al norte hasta las colinas al oeste del camino. {npc:2535} y {npc:2536} están juntos justo al norte del poblado de Zanzil.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Ve al noreste, pasado el campamento de Nesingwary, y sigue el camino al norte hasta el campamento en lo alto de la vega. Por el camino, una {npc:217588} se arrastra por la selva al sureste del campamento de Nesingwary: atrapa una con el Kit de iniciación a la entomología y márcala.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Ve al noroeste desde la mina hasta la bahía de la costa noroeste. Las Almejas gigantes están en el fondo y guardan las perlas; {npc:2624} nada entre ellas y suelta la {item:4034}.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Ve al sur hasta la cabaña del gigante, en mitad del pantano.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "El siguiente encargo de Cuernomarino te lleva de vuelta a las Tierras Altas de Arathi: omítelo.",
		["Skullsplitter ruins"] = "Ruinas Machacacráneos",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Apestoso espera al oeste de la mansión, en el pantano bajo la {area:504}. Llévalo hasta sus hojas de cienagrana y mantén alejadas de él a las criaturas del pantano.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Toma el camino al norte hasta la mansión en ruinas; Jarl vive en la choza de al lado y la tierra suelta está en la esquina de la casa.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "Toma el {area:2257} desde el {object:28027}. {npc:5637} está en la sala de los Reclaimers junto a {object:32356}, {npc:1356} en la propia sala y {npc:2786} en {object:32383}. La siguiente guía continúa en vuelo hasta {area:144}.",
		["The Bloodsail captains"] = "Los capitanes Velasangre",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Los Basiliscos Ojogélido descansan en las rocas al oeste de la mina.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "Las arañas Niebla Negra anidan alrededor de la cueva del noroeste del pantano; todas las arañas sueltan ojos.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Los múrlocs Ancalodo abarrotan la costa norte pasada la {area:497}; termina las lenguas con las tortugas que hay a su lado.",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "Las Tortugas Fangorroca y los Caparapicos toman el sol en la orilla al noreste de la mansión.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "Los trols Machacacráneos ocupan las ruinas justo al este de la mina; cualquiera de ellos puede soltar colmillos, y sus panteras siempre los sueltan.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "La posada quemada está en el camino del oeste, hacia {zone:1413}; la insignia del guardia está entre las cenizas y las huellas de pezuñas, en el barro junto a la posada.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Los capitanes están en los barcos fondeados frente a la {area:43}, cada uno con una tripulación de piratas de nivel 42-45: Aguasmansas (45) y Sinquilla (46) en las cubiertas más cercanas, y {npc:2546} (48) en el buque insignia. A nivel 42 es una pelea para un grupo o para el final de la guía; si vas, limpia antes cada cubierta. El pergamino de Cortello está en el naufragio junto a la orilla.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Los desertores acampan al sur del camino, al oeste de la cabaña de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "La madera a la deriva llega a la orilla oriental.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Los naga recorren las playas al norte del campamento Velasangre; sueltan los juncos.",
		["The north-west coast"] = "La costa noroeste",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "El siguiente pergamino del enigma está en el oeste del Marjal Revolcafango: omítelo.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "El pergamino está en el pantano al norte de Biggs. Los Caminalodos al norte de él pueden soltar los ensayos de Khadgar.",
		["The sunken temple"] = "El Templo Sumergido",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "El ritual de Unbagwa",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Zanzil's village"] = "El poblado de Zanzil",
		["for Stoley in {zone:1446}: keep it"] = "para Stoley, en {zone:1446}: guárdalo",
		["for the {zone:1435} later"] = "para {zone:1435}, más tarde",
		["for {area:1438}: keep it"] = "para el {area:1438}: guárdalo",
		["for {npc:2616} in Theramore: keep it"] = "para {npc:2616}, en Theramore: guárdalo",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635}, en {area:348}: guárdalo",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770}, en el {area:99}, en la vuelta por el norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "solo si llevas una {item:3853} (la fabrica un herrero)",
		["with the spices from Theramore"] = "con las especias de Theramore",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para \"Ojolodo\" Jarl",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cocina en {object:2169}; {npc:5384} está en el {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: otros colores, 20 o",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}: para {npc:1344}, en {zone:1432}; guárdalo",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, el Archivo Real en {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: atrápala, para {quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}, último piso",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "El siguiente encargo de {npc:2498} sobre Zanzil empieza en {zone:1441}: omítelo.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} y {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada frente a la costa noroeste, en la vuelta por el norte",
		["{npc:384}: other colours, 20g"] = "{npc:384}: otros colores, 20 o",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, en {object:2164}: {npc:6251}, en {area:392}, la recoge al final de la siguiente guía",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: otros colores, 20 o",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966} ocupa la torre con unos cuantos desertores. Se vuelve contra ti: pelea con él hasta que se rinda.",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: para el {area:1438}; guárdalo",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, en la Catedral de la Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} ofrece después El Cazavientos (1791): la cadena del arma torbellino, con un élite al final, está en la guía de clase de guerrero Arma torbellino.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864}, en {zone:1446}; guárdalo",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: otros colores, 20 o",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} es el edificio alto sobre el puerto; la mayoría de los PNJ de misiones están en sus pisos o en los muelles de abajo.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} está cerca de la posada; {npc:4897}, una proveedora de comercio unos pasos al sur, vende las especias que quiere Jarl.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Perlas azules de la Vega de Tuercespina",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "Vuela a {area:392}; {npc:6251} enseña en la casa junto al banco. Después vuelve volando a Theramore.",
		["Fly to {area:608}, ride south through {zone:1443} into {zone:1444} and follow the road to the dock on the {area:1108}; the boat crosses to {area:1116}, where the next guide starts."] = "Vuela a {area:608}, cabalga al sur por {zone:1443} hasta {zone:1444} y sigue el camino hasta el muelle de {area:1108}; el barco cruza hasta {area:1116}, donde empieza la siguiente guía.",
		["On to Feathermoon"] = "Rumbo a Bastión Plumaluna",
		["Raleigh's next errand is in the {area:796}: skip it."] = "El siguiente encargo de Raleigh el Devoto es en {area:796}: omítelo.",
		["Ride back east to {area:1898}."] = "Vuelve al este hasta {area:1898}.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "Cabalga al norte hasta {area:144} y vuela a {area:271}. {npc:3980} predica junto a la posada.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Cabalga al noreste, fuera de {area:271}, por el camino hacia {zone:1425}; {area:348} está justo pasada la frontera. {npc:5635} recibe en lo alto, {quest:1450} cuida del aviario y {npc:7884} está junto a la posada.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cabalga al sur, fuera de {zone:1432}, por el paso hasta {zone:1418}; {npc:2860} acampa en la excavación.",
		["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Cabalga al oeste por {zone:1418} hasta el campamento Rotapolvo de {area:342}. {npc:2944} está en el centro, rodeado de Cazavermis y Destructores.",
		["Ride west to the {area:1877} in the middle of the {zone:1418}; {npc:2817} camps beside Martek."] = "Cabalga al oeste hasta {area:1877}, en el centro de {zone:1418}; {npc:2817} acampa junto a Martek el Exiliado.",
		["Take the boat to Theramore from the far pier."] = "Toma el barco a Theramore en el muelle del fondo.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La siguiente tarea del Maestro de grifos Garracha espera a una guía posterior de {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Las Crías hirvientes anidan en el barranco al este de {npc:2888}; deja en paz a los Guardianes abrasados (élite). El {item:4612} cae muy pocas veces: cógelo si sale mientras subes de nivel.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "El esqueleto maltrecho está al borde del campamento de los troggs Grutacanto; {quest:739}, el asesino de Agmond, anda entre los Partehuesos.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Las dos primeras jaulas están juntas en el poblado Secacorteza al sur de {npc:5634}; la tercera, en el siguiente poblado al este. Cualquier trol Secacorteza puede soltar un collar.",
		["Theramore"] = "Theramore",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Witherbark villages"] = "Poblados Secacorteza",
		["grind on {npc:2725} at {area:339}, {zone:1418}"] = "sube de nivel con {npc:2725} en {area:339}, {zone:1418}",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} está en los muelles donde atraca el barco.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La siguiente misión de {npc:2817} no da experiencia: omítela.",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} acampa solo en {area:1898}, al sureste de la excavación.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La siguiente tarea de {npc:2888} es una caza élite: omítela.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa en el camino al este de {area:348}.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "El cubata de {npc:5634} requiere ingredientes de Kalimdor: omítelo.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, junto al maestro de vuelo, en lo alto",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} sigue pagando por los collares: entrega los que te sobren",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Vuelve a las {area:1117}. Cualquier naga Crestafuria de allí puede soltar escamas.",
		["Boat to the {area:1108} and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Toma el barco a {area:1108} y cabalga hacia el este por {zone:1444} hasta los Dominios Tótem Siniestro, al norte del camino. {npc:7956} espera fuera; libera a los Duendes dardo del cercado del centro y mantén con vida a {npc:7956} y al menos a seis de ellos.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "Toma el barco a {area:1108} y cabalga hacia el este hasta {area:1105}. Las misiones de {npc:14637} en la costa requieren nivel 45.",
		["From Theramore, fly to {area:608} and ride south out of {zone:1443} into {zone:1444}; the road leads west to the {area:1108} dock, where the boat crosses to Feathermoon on {area:1120}."] = "Desde Theramore, vuela a {area:608} y cabalga hacia el sur desde {zone:1443} hasta {zone:1444}; el camino lleva al oeste hasta el muelle de {area:1108}, donde el barco cruza a Plumaluna, en {area:1120}.",
		["Giants and elementals"] = "Gigantes y elementales",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Dominios Tótem Siniestro",
		["Grimtotem tauren"] = "Tauren Tótem Siniestro",
		["Grind to 45"] = "Farmea hasta el 45",
		["Hatecrest naga"] = "Nagas Crestafuria",
		["Hearth to Feathermoon."] = "Usa la piedra de hogar para ir a Plumaluna.",
		["Rage Scar yetis"] = "Yetis Estigmodio",
		["Ride back north-west to the {area:1108} dock and take the boat to the island."] = "Vuelve al noroeste hasta el muelle de {area:1108} y toma el barco a la isla.",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Vuelve a {area:1108}; el goblin está junto al muelle.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Vuelve al oeste por el camino y luego al norte hasta las colinas de los Dominios de los Cicatriz de Rabia. Cualquier yeti de aquí puede soltar un pellejo; alguno puede soltar un {quest:7735}, que {npc:7852} McGrubben también paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cabalga hacia el este hasta la Avanzada Gordunni, en las colinas al sureste del valle de los yetis: Brujos y Chamanes Gordunni ocupan el campamento y los Toscos Gordunni deambulan por las laderas de alrededor y más al norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cabalga hacia el norte hasta el valle de los yetis. Cualquier yeti Cicatriz Feral puede soltar un pellejo grueso; {npc:5346} (nivel 48) merodea por el centro.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cabalga hacia el noreste hasta el puesto de los elfos de la noche en la frontera de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cabalga hacia el sureste hasta los gnolls Zarpaleña; las mochilas del mensajero están en su campamento del sur, y un paquete que hay dentro inicia una entrega a {area:489}. La colmena Zukk'ash está justo al sur: abre paso hasta la vaina que retiene a Raschal el Mensajero, libéralo y mantenlo con vida al salir.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Cabalga hacia el oeste hasta el gigante de montaña amistoso al pie de las colinas. Los Caminantes de la tierra y los Gigantes del risco que lo rodean son élite: mantén la distancia.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Toca la campana cada vez que {npc:7774} se pare a deambular y llévala hacia el sur hasta {npc:7765}.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in northern {zone:1446}, the next zone on the route; come back to {npc:14637} on the {area:1108} afterwards."] = "Hacer {area:978} en grupo en vez de farmear te lleva allí más rápido. La ciudad trol está en el norte de {zone:1446}, la siguiente zona de la ruta; después vuelve con {npc:14637} en {area:1108}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Zancacostas, Zancaprofundas y Asaltaolas (gigantes élite) vadean la costa al norte del muelle: dispara a uno con {item:18904} y mata al gigante encogido. Elementales marinos y Rocíos del mar flotan entre las mismas olas.",
		["Swim south from the island to the {area:1121}. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "Nada hacia el sur desde la isla hasta {area:1121}. La ocupan Guardias serpiente y Hechiceras Crestafuria; {npc:8136} (nivel 47) espera en la cueva de su extremo sur. Atrae primero a sus guardias.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Toma el barco a {area:1108} y sigue la orilla hacia el sur hasta el bote de remos destrozado en la playa.",
		["The courier's boat"] = "El bote del mensajero",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Camina hacia el sur por la isla hasta las ruinas naga; el cenador está entre ellas.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "Terminas en el muelle de {area:1108}: la guía de {zone:1446} empieza con el viaje hacia el este desde aquí.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande en {zone:1457}: la ruta te lleva allí a nivel 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "farmea {npc:5292} en {area:1105}, {zone:1444}",
		["if you carry {quest:1100} from {zone:1441}"] = "si llevas {quest:1100} de {zone:1441}",
		["{area:978} instead of grinding"] = "{area:978} en vez de farmear",
		["{item:11463}, from the backpacks"] = "{item:11463}, de las mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "Las recargas de {npc:14637} son de nivel 55: omítelas.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "Después {npc:3936} te pide que lleves noticias a {zone:1457}: omítelo, {area:976} te enviará allí en su lugar.",
		["{npc:3936}, beside him"] = "{npc:3936}, a su lado",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: su respuesta espera en {area:702}, más adelante",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} deambula por las colinas al norte de {npc:7765}, entre las arpías Nortearroyo; su campana está en el cofre a su lado.",
		["{npc:7774}'s escort"] = "La escolta de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, en lo alto del bastión",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} espera hasta el final del recorrido por el continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Fly from {area:976} to Theramore, take the boat to {area:150} and fly to {area:1537}. Train."] = "Vuela de {area:976} a Theramore, toma el barco a {area:150} y vuela a {area:1537}. Entrena.",
		["Fly to {area:348}. {zone:1425} guide starts here."] = "Vuela a {area:348}. La guía de {zone:1425} empieza aquí.",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Sigue la costa hacia el sur hasta la cala pirata. Los piratas del Mar del Sur abarrotan la playa y los barcos: avanza por el borde y atráelos de uno en uno. {npc:7883} está en el lado opuesto; la carga robada de {npc:7881} está en el campamento.",
		["From the {area:1108} dock, boat to Feathermoon and fly to {area:489}, then ride east through {zone:1441} to the {area:2240} on the {area:439}. {npc:4454} and {npc:4630} are in the camps beside the track; {npc:4709} stands by the goblin camp."] = "Desde el muelle de {area:1108}, toma el barco a Plumaluna y vuela a {area:489}; luego cabalga hacia el este por {zone:1441} hasta {area:2240}, en {area:439}. {npc:4454} y {npc:4630} están en los campamentos junto a la pista; {npc:4709} está junto al campamento goblin.",
		["Gives the {item:8585}"] = "Da el {item:8585}",
		["He runs off to keep Rizzle busy"] = "Sale corriendo para entretener a Rizzle",
		["Hearth to {area:976}."] = "Usa la piedra de hogar para ir a {area:976}.",
		["Pool by {area:979}"] = "Charca de {area:979}",
		["Ride back west to {area:976}."] = "Vuelve al oeste hasta {area:976}.",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch."] = "Vuelve al oeste hacia {area:976}. Los Bandidos y Ladrones Deambuladores ocupan las dunas del camino; cualquiera puede llevar un odre de agua.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cabalga hacia el este por las dunas hasta el puerto goblin de la costa noreste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Cabalga hacia el noroeste hasta la colmena Centipaar de las dunas. Cualquier Centipaar puede soltar trozos de insecto.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cabalga hacia el noroeste hasta el campamento de los trols Furiarena en {area:979}. Usa el {item:8584} en el borde de su charca; los trols están cerca, así que atrae primero a los más próximos.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Cabalga hacia el sur hasta {quest:3362}. Los Colectores de rocío Cardizal sueltan las glándulas; solo algunas están llenas, así que quédate con la Glándula cargada de rocío. Cardizales nudosos y Enraizadores Cardizal comparten el valle. Los Cardizales son de nivel 48-50, por encima del tuyo: atráelos de uno en uno.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside."] = "Cabalga hacia el sur, más allá del {area:1938}, hasta {area:981}, los túneles Hazzali; el equipo de Patagolpe está en lo más profundo.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cabalga hacia el sur hasta el campamento de excavación del {area:1938}. {npc:7771} te da un yelmo detector: póntelo para ver los montículos de {quest:3161}, abundantes en la arena alrededor del campamento y hacia el suroeste, hacia los ogros.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Cabalga hacia el sureste desde {area:439} hasta {zone:1446}. {area:976} está justo pasada la frontera.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first."] = "Cabalga hacia el sureste hasta {area:985}. {npc:7847} está en el centro del campamento Vagayermo del sur: despeja primero a su alrededor.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cabalga hacia el suroeste hasta la Base Machacaduna. Está llena de Toscos y Déspotas Machacaduna (46-48); {npc:12046} (49) está en el centro rodeado de guardias: acaba primero con ellos.",
		["Rizzle's plans"] = "Los planos de Rizzle",
		["The Wanted poster beside him"] = "El cartel de Se busca a su lado",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La tortuguita {npc:5955} se esconde en el extremo norte del valle. Llévala a casa con su pareja {npc:6015}, junto al agua justo al este de {area:977}: camina despacio y las bestias del desierto van a por ella, así que mantenla con vida.",
		["The pool by {area:979}"] = "La charca de {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "El mismo cartel: {npc:7847} llega mucho más tarde, después de {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later."] = "Los Pícaros Vagayermo, Magos oscuros Deambuladores y Asesinos Vagayermo, más duros, acampan al sureste de {area:976}, al sur de los bandidos. Deja a {npc:7847}, en el centro del campamento del sur, para más tarde.",
		["The {area:1938}"] = "El {area:1938}",
		["Wastewander bandits"] = "Bandidos Deambuladores",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Mientras {npc:4709} entretiene a Rizzle, sus planos quedan sin vigilancia en el campamento gnomo al otro lado de la pista.",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: la ruta te lleva allí a nivel 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, en el lado este del pueblo",
		["{npc:5955}'s escort"] = "La escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto a la torre de agua",
		["{npc:7408}, next to him"] = "{npc:7408}, a su lado",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "El siguiente ingrediente de {npc:7583} crece en {zone:1425} y la ruta nunca te trae de vuelta: omítelo.",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: su caja va a {area:702}, más adelante",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "La siguiente entrega de {npc:7881} vuelve a {area:35}: omítela.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, en la taberna del puerto",
		["{quest:2864}, north side of town"] = "{quest:2864}, en el lado norte del pueblo",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Jabalíes Cenicrín y Basiliscos Rocarroja comparten las laderas al suroeste del bastión. Evita a los Jabinfernos más al sur: son de nivel 52.",
		["Back to {area:144}"] = "De vuelta a {area:144}",
		["Boars and basilisks"] = "Jabalíes y basiliscos",
		["Fly from {area:144} to {area:150}, take the boat to {area:442} and fly to {area:702}."] = "Vuela de {area:144} a {area:150}, toma el barco a {area:442} y vuela a {area:702}.",
		["Fly from {area:348} to {area:42}."] = "Vuela de {area:348} a {area:42}.",
		["Hearth to {area:144}. The {zone:1427} guide starts at {area:1446}: from here, ride south into the {zone:1418}, west past the Horde town of {area:340} and up the trail into the gorge."] = "Usa la piedra de hogar para ir a {area:144}. La guía de {zone:1427} empieza en {area:1446}: desde aquí, cabalga hacia el sur hasta {zone:1418}, al oeste más allá del pueblo de la Horda de {area:340}, y sube por el sendero hasta la garganta.",
		["Hearth to {area:348}."] = "Usa la piedra de hogar para ir a {area:348}.",
		["Hearthstone on cooldown? Ride back north-west."] = "¿Piedra de hogar en reutilización? Vuelve cabalgando al noroeste.",
		["Ride back east to {area:1438} and fly to {area:144}."] = "Vuelve al este hasta {area:1438} y vuela a {area:144}.",
		["Ride back north to Ironband's camp."] = "Vuelve al norte hasta la Excavación de Vetaferro.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Cabalga hacia el este por la orilla sur del lago hasta la Excavación de Vetaferro.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Cabalga hacia el este por {zone:1430} hasta {zone:1435} y baja por el camino hacia el sur hasta {zone:1419}. El campamento de los magos de sangre es la primera parada junto al camino.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it."] = "Cabalga hacia el norte hasta {area:351}, en el centro de {zone:1425}. Barrosos verdes y mocos de jade se arrastran por todo el lugar.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Sigue primero por el camino hacia el este hasta el bastión: la {item:6091} caduca una hora después de {area:42}, y las bestias de los magos de sangre llevan más tiempo.",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Cabalga hacia el sur por el paso hasta el borde norte de {zone:1418}: allí los troggs Grutacanto excavan fuera de {area:1517}. Las urnas talladas y los grupos de champiñones magenta están en sus cuevas y túneles, fuera de la propia mazmorra.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down."] = "Cabalga hacia el sureste hasta {area:355}, el templo escalonado Vilrama del sur de {zone:1425}, y sube hasta arriba. Qiaga el Vigilante y {npc:8636} (élite, 50) están allí: toca la cima y baja enseguida.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Cabalga hacia el oeste: las Hienas risitas hambrientas deambulan por las colinas secas justo al sur del campamento de los magos de sangre; los Aguijoneros Scorpok (nivel 50) corretean por el centro del norte. Los buitres {npc:5982} vuelan en círculos sobre todo ello. Atráelos de uno en uno.",
		["Scorpoks and snickerfangs"] = "Scorpoks e hienas risitas",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Cruza el portal hasta {zone:1457}. El Templo de la Luna está en el sur de la ciudad.",
		["Temple of the Moon"] = "Templo de la Luna",
		["The bloodmages"] = "Los magos de sangre",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "La segunda ronda de los magos de sangre paga las mismas partes con un objeto de mejora y sin experiencia: omítela.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Los instructores de druidas están en el Enclave; {zone:1455} no tiene",
		["The {area:1517} dig"] = "La excavación de {area:1517}",
		["for {quest:2990} at {area:1438}, later"] = "para {quest:2990} en {area:1438}, más adelante",
		["the book on her table"] = "el libro de su mesa",
		["the soil comes from {zone:1449}, later"] = "la tierra viene de {zone:1449}, más adelante",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, en lo alto del árbol",
		["{npc:7740}, beside her"] = "{npc:7740}, a su lado",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "El siguiente encargo de {npc:7907} va a {zone:1446}: omítelo.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guárdala, las plumas llegan al final de la guía de {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "La siguiente tarea de {npc:8022}, {item:9471}, es una misión de {area:978}: omítela.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, en lo alto del bastión",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Para {npc:8256} en {zone:1455}, más adelante",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}. {area:1446} is the scaffolded camp on the north-west rim."] = "Desde {area:144}, cabalga hacia el sur hasta {zone:1418}, luego al oeste más allá del pueblo de la Horda de {area:340} (mantén la distancia) y sube por el sendero hasta {zone:1427}. {area:1446} es el campamento con andamios del borde noroeste.",
		["Golems and elementals"] = "Gólems y elementales",
		["Greater Lava Spiders"] = "Arañas de lava abrasadoras",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Los Gólems de guerra pesados patrullan el fondo de La Caldera bajo Kalaran; los Elementales de magma vagan entre ellos. Gólems y elementales sueltan el aceite; los elementales, los corazones.",
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "Kalaran Espada del Viento está en el borde de La Caldera, al sur de {area:1446}. Escucha su historia.",
		["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Cabalga hacia el este por La Caldera hasta {area:247}, en el sureste. El prisionero de la letrina de madera quiere 15 {item:4306} y ocho geólogos Hierro Negro ({npc:5839}) muertos de la excavación que la rodea. La letrina también se abre con la llave, si encontraste una.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Capataces y Esclavistas Hierro Negro azuzan a los esclavos por toda La Caldera, y cualquiera puede llevar una {item:10551}. Los Vapoherreros Hierro Negro trabajan en los hornos del centro (la {item:18959}) y los Vigías Hierro Negro están en las crestas del sur (el Telescopio de vigía). Cualquier {object:147516} puede soltar la {item:11818}: guárdala.",
		["The Grimesilt outhouse"] = "La letrina de Limugre",
		["The dwarf stands by the road at the dig site. Follow him north along the road and fight off the {object:147516} ambushes. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "El enano está junto al camino en la excavación. Síguelo hacia el norte por el camino y rechaza las emboscadas {object:147516}. Cuando termine, lee la {object:175704} que deja en el camino en {area:1959}.",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "El elfo de la noche está solo al oeste de {area:1446}. Escucha su historia.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La siguiente tarea del prisionero, El libro de contabilidad de {zone:1446}, te envía a {zone:1435} y {zone:1445}: omítela.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Las arañas deambulan por las mesetas y charcas de lava del suroeste de la garganta.",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre en el norte de La Caldera. Los planos secretos están en su cornisa superior; los Incendosaurios nadan en las charcas de lava más adentro, así que atráelos hasta el borde. Mantente lejos de {npc:14621} y sus guardias élite del fondo.",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: la guía anterior te trae aquí con la piedra de hogar, así que esto suele marcarse al instante",
		["{object:147516} dwarves"] = "Enanos {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus está junto al rey Magni en {object:171709}.",
		["Bind and train"] = "Vincula y entrena",
		["Bones and equipment"] = "Huesos y equipo",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Cruza el sur del cráter hasta {npc:9619}, junto a la rampa.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Los huesos de dinosaurio ({item:11114}) están en el suelo del suroeste, entre los estegodones: son élite, así que recoge los huesos a su alrededor y consigue el resto de los diemetradones. El {item:11112} de la expedición está en la jungla del suroeste.",
		["Eastern Pylon"] = "La Torre del Este",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Fly from {area:144} to {area:1537}."] = "Vuela de {area:144} a {area:1537}.",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775} en {zone:1444}: guárdala",
		["Four rune rubbings in {zone:1447}: keep it"] = "Cuatro calcos de runas en {zone:1447}: guárdala",
		["From {area:144} fly to {area:150}, take the boat to Theramore and fly on to {area:976}. {npc:9619}'s first quest in the crater needs level 48: finish the level here if you are short."] = "Desde {area:144} vuela a {area:150}, toma el barco a Theramore y sigue volando hasta {area:976}. La primera misión de {npc:9619} en el cráter requiere nivel 48: si te falta, termina el nivel aquí.",
		["Grind to 50"] = "Sube hasta el 50",
		["Grind to 51"] = "Sube hasta el 51",
		["Gryfe"] = "Gryfe",
		["Lar'korwi Mates and the raft"] = "Amigos de Lar'korwi ({npc:9683}) y la balsa",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Lleva a {npc:9999} al norte hasta {area:541}. Cuando se desmaye, usa {item:11804} en él para despertarlo.",
		["Northern Pylon"] = "La Torre del Norte",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Baja por la rampa al cráter: {npc:9619} acampa al pie.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Cabalga al este hasta {area:537}, súbela y usa {npc:10541} en las grietas de lava cerca de la cima.",
		["Ride north along the east side of the crater to {area:541}, the camp in the caves of the northern cliff. Give the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Cabalga hacia el norte por el lado este del cráter hasta {area:541}, el campamento en las cuevas del acantilado norte. Mantente lejos de los devilsaurios y estegodones élite. Recoge todos los cristales de poder y cada {object:157936} que encuentres a partir de aquí.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Cabalga al norte por el lado este hasta la meseta de los gorilas. {npc:9622}, un gorila de nivel 55, está en su cueva más profunda: limpia primero los gorilas de la entrada.",
		["Ride north along the western jungle back to the refuge."] = "Cabalga al norte por la jungla del oeste de vuelta al refugio.",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Cabalga al norte hasta {area:1943}, donde el robot está entre los gorilas. No entres en la cueva profunda de allí.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Cabalga al sur por los acantilados del este hasta {npc:9619}, al pie de la rampa.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Cabalga al sur por el lado este. Los diemetradones jóvenes ({npc:9162}) pastan en la jungla del este y los {npc:9165} vuelan cerca de los acantilados del este; ambos sueltan las escamas de {npc:9998}.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Cabalga al sur hasta {area:537}, en el centro del cráter, y luego al este hacia la jungla del este. Hay grupos de cristales por todo el cráter, muchos alrededor de {area:537}: coge unos cuantos de más de cada color. Los latigadores pétalo de sangre ({npc:6509}) y los trilladores sueltan los pétalos; el {item:11113} de la expedición está en un campamento abandonado de la jungla del este.",
		["Ride west back to the refuge."] = "Cabalga al oeste de vuelta al refugio.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Cabalga al oeste desde {npc:9619}: la colmena de silítidos ocupa el sur del cráter. Usa el vial de raspadura en un criadero, una cámara con larvas colgando. Las avispas y obreros Gorishi sueltan {quest:3764}; los {npc:9166} anidan en los acantilados del sur si aún necesitas matar alguno.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Sal de {area:976} cabalgando al oeste hasta la larga rampa que baja a {zone:1449}. {npc:9619} acampa al pie de la rampa, en la esquina sureste del cráter.",
		["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "Cabalga al oeste pasando {area:541} y baja al sur por el lado oeste hasta {area:543}: el goblin {npc:10302} está junto al agua.",
		["Running the {area:1417} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Hacer el {area:1417} en grupo en vez de matar bichos te lleva allí más rápido. Omite este paso para subir de nivel en solitario.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in the north-west of {zone:1446}, just north of {area:976}."] = "Hacer {area:978} en grupo en vez de matar bichos te lleva allí más rápido. La ciudad trol está en el noroeste de {zone:1446}, justo al norte de {area:976}.",
		["The Centipaar silithid crawl around the {area:982} in western {zone:1446}, just east of the crater ramp. The Workers are the easiest pulls."] = "Los silítidos Centipaar rondan {area:982}, en el oeste de {zone:1446}, justo al este de la rampa del cráter. Los trabajadores son los más fáciles de atraer.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Los amigos de Lar'korwi ({npc:9683}) merodean por la jungla al oeste de {npc:9619}. La balsa naufragada está en la orilla del lago; el pequeño fardo está en el agua a su lado. Guarda la brújula, el mapa y la llave para {npc:8737}. Cualquier bestia del cráter puede soltar {item:11116}: haz clic derecho en él.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "El trillanodonte muerto yace junto al agua, al norte de {npc:9619}.",
		["The east side"] = "El lado este",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55."] = "Los gorilas viven en {area:1943}, al este de {area:541}. Guarda sus pieles para {npc:9619}. No entres en la cueva más profunda: {npc:9622} es de nivel 55.",
		["The gorillas of {area:1943} come in small groups and drop nothing for you yet; {npc:9619}'s pelt quest comes later. Stay out of the deepest cave: {npc:9622} is level 55."] = "Los gorilas de {area:1943} van en grupos pequeños y aún no sueltan nada para ti; la misión de las pieles de {npc:9619} llega más tarde. No entres en la cueva más profunda: {npc:9622} es de nivel 55.",
		["The pelts come after loop 2, on the gorilla plateau"] = "Las pieles van después de la vuelta 2, en la meseta de los gorilas",
		["The pylon stands on the eastern cliffs."] = "La torre está en los acantilados del este.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "La torre está en la ladera al este del refugio. Los {npc:9166} vuelan en círculos por las laderas que la rodean: cuentan para {npc:9997} y sueltan las escamas de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "La torre está en los acantilados del oeste. Los {npc:9167} vuelan por todo el lado oeste.",
		["The relics are in the {zone:1428}: keep it"] = "Las reliquias están en {zone:1428}: guárdala",
		["The wooden sign beside {npc:9997}"] = "El cartel de madera junto a {npc:9997}",
		["Western Pylon"] = "La Torre del Oeste",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera en {object:32359}.",
		["grind on the Wastewanderers or Dunemaul ogres around {area:976}"] = "mata Vagayermos u ogros Machacaduna alrededor de {area:976}",
		["grind on {npc:5458} at {area:982}, {zone:1446}"] = "mata {npc:5458} en {area:982}, {zone:1446}",
		["grind on {npc:6514} at {area:1943}, {zone:1449}"] = "mata {npc:6514} en {area:1943}, {zone:1449}",
		["{area:537} and the eastern jungle"] = "{area:537} y la jungla del este",
		["{area:978} (optional)"] = "{area:978} (opcional)",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc en {zone:1447}, guárdala",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: la guía anterior te trae aquí con la piedra de hogar, así que esto suele marcarse al instante",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, al fondo de la cueva",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: los mocos están en {zone:1448}, guárdala",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} está justo fuera del refugio.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "La guarida de {npc:9684} está en la jungla al norte de {npc:9619}, bajo los acantilados del este: usa {item:11568} allí. {npc:9684} es de nivel 56: empieza con la salud al máximo.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9999}, el amigo de {npc:9997}, ha desaparecido.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, en la entrada del refugio",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} está sentado en la ladera sureste de {area:537}, en el centro del cráter.",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb back to {npc:8405} at the {area:1224}, above the ruins."] = "Vuelve a subir hasta {npc:8405} en {area:1224}, sobre las ruinas.",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Sube a la cima de {area:249} y planta la cabeza en el montículo de tierra blanda.",
		["Druid training"] = "Entrenamiento de druida",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina con {quest:4808} en {area:2255}, {zone:1452}: guárdala",
		["Fly from {zone:1455} to {area:150} and take the boat to {area:442}."] = "Vuela de {zone:1455} a {area:150} y toma el barco a {area:442}.",
		["Fly from {zone:1455} to {area:69}."] = "Vuela de {zone:1455} a {area:69}.",
		["Fly to {area:1438}."] = "Vuela a {area:1438}.",
		["Fly to {area:150} and take the boat to {area:442}, then the boat on to {area:702}."] = "Vuela a {area:150} y toma el barco a {area:442}; luego, el barco a {area:702}.",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Sigue el camino al oeste y luego sube al norte hasta el campamento goblin en {area:251}.",
		["From the {area:442} dock, fly to {area:415}."] = "Desde el muelle de {area:442}, vuela a {area:415}.",
		["Mosshoof Coursers"] = "Maledictores Pezuñamusgo ({npc:8761})",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Opcional: {npc:8395} quiere dos plumas de hipogrifo sin estropear ({item:10450}) de los hipogrifos alrededor de su campamento. Los datos no indican experiencia para ella.",
		["Optional: {npc:8888}'s ghost stands on his tomb on the great chain inside {area:254}, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting."] = "Opcional: el fantasma de {npc:8888} está sobre su tumba en la gran cadena dentro de la {area:254}, y solo los muertos pueden verlo. Si mueres cerca de la montaña de todas formas, lleva a tu espíritu hasta él antes de resucitar.",
		["Read the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript."] = "Lee la tablilla del campamento {object:147516} entre las ruinas, al suroeste de {area:251}, para copiar la transcripción.",
		["Ride back east along the road to the Vigil."] = "Vuelve al este por el camino hasta la Vigilia.",
		["Ride back to {area:1438} and fly to {area:348}. The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Vuelve a {area:1438} y vuela a {area:348}. Las plumas de lechúcico ({item:10819}) están por el suelo de {zone:1425}, al sur y al este de {area:348}, donde rondan los lechúcicos; los bichos de aquí ya son de nivel muy inferior al tuyo.",
		["Ride east along the road out of {zone:1440} into {zone:1447} to the Sentinels' camp at {area:3137}."] = "Cabalga al este por el camino que sale de {zone:1440} hacia {zone:1447} hasta el campamento de las centinelas en {area:3137}.",
		["Ride north out of {area:69} through the pass into the {zone:1428}; {area:2418} sits at the top, in the south-east of the Steppes."] = "Cabalga al norte desde {area:69} por el paso hasta {zone:1428}; {area:2418} está arriba, en el sureste de las Estepas.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Cabalga al noreste desde el santuario: {npc:8405} acampa en {area:1224}, en las colinas sobre el camino.",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "Nada hasta la islita frente al extremo sur de {zone:1447}: {npc:8392} espera junto al monumento.",
		["Thaurissan Relics"] = "Reliquias Thaurissan ({object:153556})",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Los ogros Pirontraña ocupan la gran roca al norte de la Vigilia, con los toscos en su lado este.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Los fantasmas altonatos rondan las ruinas alrededor del santuario; los sátiros Haldarr ocupan el campamento justo al norte.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Las nagas Látigo de Ira de las {area:1221} llevan {item:13815}. Las cuatro runas de {npc:8507} están entre las ruinas: usa su {item:10445} en cada una.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Los maledictores Pezuñamusgo ({npc:8761}) más cercanos pastan en las colinas al noreste de {area:1224}, hacia {area:1219}; una manada mayor recorre el terreno abierto del sur.",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered."] = "Las reliquias son las piedras talladas repartidas por las {area:250} alrededor de {area:251}: haz clic en ellas hasta recuperar la información.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "El santuario está en la esquina suroeste de {zone:1447}, al sur de {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Los lechúcicos están en {zone:1452}: guárdala",
		["The {area:1221}"] = "Las {area:1221}",
		["The {quest:4296}"] = "La {quest:4296}",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Usa el {item:12284} en un {npc:7047} de las laderas al este de {area:251} justo antes de que muera y despoja la esencia que deja.",
		["Wildkin feathers"] = "Plumas de lechúcico",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: los {npc:7864}, un 10 % aprox.",
		["{npc:5111}: the last guide binds here, so this usually ticks at once"] = "{npc:5111}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:7363} waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have."] = "{npc:7363} espera en el {area:2517}, la colina al suroeste del castillo. Los bichos de {zone:1419} del camino sueltan los fragmentos draenetistas imperfectos ({item:10593}); llévale los que tengas.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} acampa en {area:1219}, en el norte; su equipo está repartido por todo el {area:1220}, justo al sureste de él.",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty."] = "{npc:9176} y los orcos Roca Negra ocupan los campamentos y el bastión al pie de la {area:254}, al oeste de {area:251}. Atráelos de uno en uno; cualquier orco o huargo puede soltar un medallón, así que mátalos hasta tener cincuenta.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: los orcos Roca Negra sueltan los medallones, mantenla abierta por todas las Estepas",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455} no tiene instructor de druidas: toma el portal para subir a {zone:1457} y entrena en el {area:1658}; luego vuelve a bajar a {area:702}.",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "Termina en {zone:1413}: guárdala",
		["First crater"] = "Primer cráter",
		["Five feathers buy a little Timbermaw reputation"] = "Cinco plumas dan un poco de reputación con los Fauces de Madera",
		["Fly from {area:1998} to the Sanctuary's end of the road, or ride south along it."] = "Vuela desde {area:1998} al extremo del camino del Santuario, o cabalga al sur por él.",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Sigue el camino al norte hasta la entrada de la cueva de {area:1769}; {npc:15395} la vigila.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Sigue el camino al norte hasta el valle de cráteres y ve a cada cráter, matando las bestias entrópicas y los horrores entre ellos.",
		["Keep her alive until she is out of the cave"] = "Mantenla con vida hasta que salga de la cueva",
		["Oozes"] = "Mocos",
		["Ride east to the night elf camp at {area:1998}."] = "Cabalga al este hasta el campamento elfo de la noche de {area:1998}.",
		["Ride north out of {area:415} into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Cabalga al norte desde {area:415} hasta {zone:1448}. {npc:11554}, el fúrbolg, está junto al camino, justo al sur del {area:2479}.",
		["Ride north to {area:1769} (or fly back to {area:1998} first) and through the tunnel into {zone:1452}; follow the road east to the goblin town of {area:2255}."] = "Cabalga al norte hasta {area:1769} (o vuela antes a {area:1998}) y cruza el túnel hasta {zone:1452}; sigue el camino al este hasta el pueblo goblin de {area:2255}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa está en la salida de {zone:1452} del túnel: guárdala",
		["Second crater"] = "Segundo cráter",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "Entra en la cueva: {npc:11558} y {npc:11557} están justo dentro.",
		["Take the boat from {area:702} to {area:442} and fly to {area:415}."] = "Toma el barco de {area:702} a {area:442} y vuela a {area:415}.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "Los mocos malditos y corruptos se deslizan por los arroyos y charcas viles alrededor de {area:1763} y {area:1765}: mátalos y usa las jarras de moco vacías de Laris en sus restos.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Los fúrbolgs Muertobosque viven en el poblado justo al suroeste de {npc:11554}; guarda las plumas de penacho Muertobosque que sueltan.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}."] = "Los fúrbolgs Muertobosque de {area:1762} llenan las colinas al oeste de la cueva. Los vengadores pueden soltar un {quest:8470}.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back."] = "Los sátiros Fuego de Jade ocupan el claro al oeste del camino, con {npc:9454} al fondo.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Los antárboles Combadera de {area:1767}, al este de {area:2618}, llevan el {item:11503}.",
		["The vial is filled in {zone:1457}: keep it"] = "El vial se llena en {zone:1457}: guárdala",
		["The {area:2479}"] = "El {area:2479}",
		["Third crater"] = "Tercer cráter",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}; Trey Lightforge's remains lie beside her."] = "Usa la {item:12922} en el pozo de la luna corrupto del centro de {area:1763}. Si liberaste a {npc:11018}, vuelve a {area:1770} a por la súcubo {npc:9518}; los restos de Trey Lightforge yacen a su lado.",
		["{area:1763} again"] = "{area:1763} otra vez",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763} es el templo en ruinas al norte del claro. Algunos de sus cultores sueltan una {item:13140}, más o menos una de cada treinta muertes: abre la celda de {npc:11018} en {area:1770}, la cueva del fondo. Si cae, despeja la salida antes de liberarla; si no, sáltate sus misiones.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} es el valle de sátiros del noroeste, con {npc:10648} al fondo. Él suelta la {quest:939}; cualquier sátiro Fuego de Jade puede soltar {item:11674}.",
		["{item:13140}, a rare drop"] = "{item:13140}, botín poco común",
		["{npc:11016}, in {area:1770}"] = "{npc:11016}, en {area:1770}",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57"] = "{npc:11557}: treinta {quest:6031}, que entregas cuando vuelvas a pasar a nivel 57",
		["{npc:11558}: the Timbermaw speak to you only from Neutral"] = "{npc:11558}: los Fauces de Madera solo te hablan desde Neutral",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} espera en el extremo norte de {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, en las ruinas justo al este de {npc:11554}",
		["{quest:8470}, a rare drop"] = "{quest:8470}, botín poco común",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "Vuelve a las colinas: solo las Matriarcas Cardo Nevado y los patriarcas llevan los cuernos. Sigue matando yetis hasta el nivel 54: antes de eso, las misiones de lechúcicos de Harlo están en rojo.",
		["Follow the road east across the zone to the chapel."] = "Sigue el camino al este cruzando la zona hasta la capilla.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Sigue el camino al oeste hasta el campamento de {npc:9298}, junto a las aguas termales.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Sigue el camino del sur hacia el este hasta {zone:1423}; las ruinas de {area:2262} están al sur. El fantasma de {npc:10926} juega junto a la casa en ruinas del extremo sur.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Sigue las indicaciones de {npc:9298} hasta la entrada de {area:2256}, pasando a los gigantes Machacahielo: pásalos de uno en uno.",
		["For Kernda in {area:1769}: keep it"] = "Para Kernda en {area:1769}: guárdalo",
		["Free Darrowshire Spirits: talk to them"] = "Libera espíritus de Villa Darrow ({npc:11064}): habla con ellos",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Los yetis Cardo Nevado viven en las colinas al sur de {area:2244}, y las Quimeras venfresco en el valle hacia {area:2255}.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Guárdalo: Gregan, en {zone:1444}, prepara el elixir más adelante",
		["On {npc:10978}, by the inn"] = "Sobre {npc:10978}, junto a la posada",
		["Optional: {area:1417}"] = "Opcional: {area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Recoge los suministros alrededor del carro y recupera el amuleto de {npc:10301} de las lechubestias cercanas.",
		["Pristine Yeti Horns"] = "Cuernos de yeti prístinos",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Cabalga al norte hasta {area:2627}. {npc:12384} vive en la choza en ruinas y su libro de recibos está en la posada en ruinas cercana.",
		["Ride north-west back to the village."] = "Cabalga al noroeste de vuelta al pueblo.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Cabalga al sureste valle abajo hasta la caja dañada de {npc:10301}, en la nieve de {area:2245}, con su carro destrozado justo al este.",
		["Ride west along the road to the night elf village."] = "Cabalga al oeste por el camino hasta el pueblo de los elfos de la noche.",
		["Ride west along the road to {npc:10301}."] = "Cabalga al oeste por el camino hasta {npc:10301}.",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "¿No llegas al nivel 54 después de los yetis? Hacer {area:1417} (50-54) en grupo en vez de matar enemigos te lleva allí más rápido. Después vuelve a {area:2255}.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "El caldero Muertobosque de {zone:1448}: guárdalo",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "La Plaga alrededor de {area:2264}, al oeste de la capilla, suelta ambos tipos de Piedra de la Plaga; de ellos surgen espíritus de Villa Darrow ({npc:11064}): habla con cada uno para liberarlo.",
		["The Winterfall camp"] = "El campamento Nevada",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "El poblado de los fúrbolgs Nevada está al este de {area:2255}: chamanes (56-57), vigilantes del cubil (55-56) y ursas (57-58), todos por encima de ti. Mata primero a los chamanes, que curan, y atrae desde el borde. {npc:10738}, en la cueva del fondo, es élite: no entres.",
		["The next guide starts here and flies to {area:3197}."] = "La siguiente guía empieza aquí y vuela a {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Las ruinas rodean el lago helado al sur de {area:2253}. Recoge los cuatro fragmentos de reliquia que hay en las ruinas y las Plumas Lunadón del suelo, donde merodean los lechúcicos.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Las tres piezas de la muñeca están en las casas en ruinas de {area:2262}; al recoger una pueden aparecer fantasmas. Combínalas para formar la muñeca.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "El campamento Nevada del oeste está en las colinas entre {npc:11556} y {npc:9298}. Cualquier fúrbolg de aquí puede soltar un {item:12771} (más o menos uno de cada diez) y, rara vez, un {quest:8471}: haz clic derecho en el que caiga. Guarda el {quest:6031} que sueltan los fúrbolgs para Meilosh.",
		["The western Winterfall furbolgs drop the beads."] = "Los fúrbolgs Nevada del oeste sueltan las cuentas.",
		["The {area:2247}"] = "{area:2247}",
		["Walk through {area:1769} to {zone:1448} and fly on to the Eastern Kingdoms ({area:442}, the boat to {area:150}). Fly to {area:271} and ride north up the road through Alterac to {area:3197}."] = "Atraviesa {area:1769} hasta {zone:1448} y vuela hacia Reinos del Este ({area:442}, el barco a {area:150}). Vuela a {area:271} y cabalga al norte por el camino a través de Montañas de Alterac hasta {area:3197}.",
		["grind on {npc:7460} at the {area:2247}, {zone:1452}"] = "mata {npc:7460} en {area:2247}, {zone:1452}",
		["{item:12771}, a rare drop"] = "{item:12771}, botín poco frecuente",
		["{npc:10301}'s camp"] = "El campamento de {npc:10301}",
		["{npc:10301}'s supplies"] = "Los suministros de {npc:10301}",
		["{npc:10431}: keep both for the Plaguelands"] = "{npc:10431}: guarda ambos para las Tierras de la Peste",
		["{npc:10926}'s doll"] = "La muñeca de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} y {npc:10977} vienen después",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038}: {npc:12250} es un élite de nivel 54",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556} guarda la entrada de {area:1769}, al noroeste de {npc:9298}.",
		["{npc:11629}: keep it for {area:2262}"] = "{npc:11629}: guárdalo para {area:2262}",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "{npc:12250} es élite: se recomienda ir en grupo. Espera al fondo de {area:2261}, la cripta del suroeste de la zona.",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, en {zone:1422}: guárdala",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, para Meilosh más adelante",
		["{quest:8471}, a rare drop"] = "{quest:8471}, botín poco frecuente",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Andorhal Watches"] = "Relojes de Andorhal",
		["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "Vuelve al norte a {area:202}: ahora la caldera ofrece su propia tarea. Los necrófagos cercanos sueltan intensificadores somáticos.",
		["Buy one {item:13320} from {npc:11056} for Felstone's cauldron, right before you go: the quickeners vanish after 30 minutes."] = "Compra un {item:13320} a {npc:11056} para la caldera de Piedramácula justo antes de ir: los aceleradores desaparecen a los 30 minutos.",
		["Buy two more Arcane Quickeners for the {area:202}'s and Dalson's cauldrons, and ride straight there: they vanish after 30 minutes."] = "Compra dos aceleradores arcanos más para las calderas de {area:202} y de Dalson, y ve directo: desaparecen a los 30 minutos.",
		["Climb the hill west of {area:190} to look down on the town."] = "Sube a la colina al oeste de {area:190} para ver el pueblo desde arriba.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Cruza el río hacia el este hasta {area:2261}, la cripta del suroeste de la zona. El {object:177667} está dentro: la llave la lleva {npc:12248}, en el extremo noreste, que se hace en la siguiente guía.",
		["Cross the river west to {npc:1855}'s hut."] = "Cruza el río hacia el oeste hasta la cabaña de {npc:1855}.",
		["Diseased Grizzlies"] = "Griseznos malsanos",
		["Diseased Wolves"] = "Lobos malsanos",
		["Fly to {area:392}."] = "Vuela a {area:392}.",
		["For the druids of {zone:1457}: keep it"] = "Para los druidas de {zone:1457}: guárdala",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guárdala",
		["For {zone:1451}: keep it"] = "Para {zone:1451}: guárdala",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guárdala",
		["From {area:392}, fly to {area:2255} and ride south to {area:2250}."] = "Desde {area:392}, vuela a {area:2255} y cabalga al sur hasta {area:2250}.",
		["From {area:702}, fly to {area:1116}."] = "Desde {area:702}, vuela a {area:1116}.",
		["Gaeriyan in {area:976}: keep it"] = "Gaeriyan en {area:976}: guárdala",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "El cráneo de Horgus está en {area:2624} y la espada de Marduk en {area:2623}, cada uno donde luchan fantasmas; los canes de la Peste adultos cazan en las llanuras de en medio.",
		["Listen to his story"] = "Escucha su historia",
		["Mark {npc:10902} with the {item:12815}"] = "Marca la {npc:10902} con la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca la {npc:10903} con la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca la {npc:10904} con la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca la {npc:10905} con la {item:12815}",
		["More watches"] = "Más relojes",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ride back south to the camp."] = "Vuelve al sur hasta el campamento.",
		["Ride back to {area:3197} and fly to {area:150}, take the boat to {area:442} and fly to {area:702}; the portal leads up to {zone:1457}."] = "Vuelve a {area:3197} y vuela a {area:150}, toma el barco a {area:442} y vuela a {area:702}; el portal sube a {zone:1457}.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Cabalga al este hasta el río de la frontera: {npc:1855} vive en una cabaña pequeña en la orilla.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cabalga al norte por el camino hasta el Aserradero Crestanorte; {npc:11610} se esconde en el borde del campamento.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Cabalga al noroeste hasta la granja de Dalson. El diario está en el granero; un esqueleto errante lleva la llave del retrete, y {npc:10836} espera en el retrete con la llave del armario.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cabalga al noroeste hasta {area:2276}, en el borde de {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Cabalga al sur hasta {area:201}, donde {npc:11078} protege la caldera.",
		["Ride south-west to the camp."] = "Cabalga al suroeste hasta el campamento.",
		["Ride west along the road to the hot springs."] = "Cabalga al oeste por el camino hasta las fuentes termales.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Cabalga al oeste hasta {area:2627}. Los cachorros de can de la Peste ({npc:8596}), los murcipestes ({npc:8600}) y las larvas carroñeras ({npc:8603}) rondan sus bosques; llena la {item:15042} en los grandes termiteros y mata a los canes de la Peste demenciados ({npc:8598}) más al norte.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones."] = "Los despellejadores esqueléticos y los necrófagos esclavizantes rondan los campos al norte del campamento; toda la Plaga de aquí suelta piedras de la Plaga.",
		["Small lockboxes lie in the rubble all over Andorhal; each holds a watch."] = "Hay pequeñas cajas fuertes entre los escombros de todo Andorhal; cada una tiene un reloj.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Toma el barco al continente y cabalga al noreste hasta el campamento de {npc:14637} junto a {area:1119}.",
		["Temple of the Moon"] = "Templo de la Luna",
		["Ten {item:11040} from the {item:11020}"] = "Diez {item:11040} de la {item:11020}",
		["The Andorhal watchtowers"] = "Las atalayas de Andorhal",
		["The Scarlet Crusade"] = "La Cruzada Escarlata",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Los médicos, cazadores, caballeros y magos escarlata patrullan el aserradero y el camino hacia {area:190}.",
		["The cauldron now offers its own task; the skeletons around it drop Osseous Agitators."] = "Ahora la caldera ofrece su propia tarea; los esqueletos de alrededor sueltan agitadores óseos.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "La caldera está en {area:202}, junto a la granja de {npc:10739}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "La caldera está en {area:200}, al noreste de Piedramácula; su señor de la caldera está a su lado.",
		["The fields"] = "Los campos",
		["The next guide starts here in {area:392} and flies on to {area:976}."] = "La siguiente guía empieza aquí, en {area:392}, y vuela a {area:976}.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Los gigantes encogidos rondan {area:1119}; los elementales marinos vadean la costa al oeste.",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Usa el {item:12627} junto a los silos de grano para hacer salir parásitos temporales. {quest:5154} es uno de los tomos mohosos del ayuntamiento. Todos los esqueletos del pueblo sueltan {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Usa la {item:12815} al pie de cada una de las cuatro atalayas del borde de Andorhal, al norte del campamento.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Entra en {area:1769} y toma el ramal del túnel de {zone:1450} hasta {area:2361}.",
		["Zapped giants and sea elementals"] = "Gigantes machacados y elementales marinos",
		["grind on {npc:1796} at the {area:202}, {zone:1422}"] = "mata a {npc:1796} en {area:202}, {zone:1422}",
		["{area:190} overlook"] = "Mirador de {area:190}",
		["{area:199} cauldron"] = "Caldera de {area:199}",
		["{area:200} cauldron"] = "Caldera de {area:200}",
		["{area:201} cauldron"] = "Caldera de {area:201}",
		["{area:202} cauldron"] = "Caldera de {area:202}",
		["{item:12894}, at the monument"] = "{item:12894}, en el monumento",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "El {item:12954} está en el ayuntamiento de {area:190}, al oeste de {npc:1855}: los guardias escarlata están muy juntos.",
		["{item:12955} lies east of the barn at {area:201}."] = "El {item:12955} está al este del granero de {area:201}.",
		["{item:13320}, from {npc:11056}"] = "{item:13320}, de {npc:11056}",
		["{npc:10300} in {zone:1452}: keep it"] = "{npc:10300} en {zone:1452}: guárdala",
		["{npc:10300}: her escort comes later on the route"] = "{npc:10300}: su escolta llega más adelante en la ruta",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} espera en la posada en ruinas del lado oeste de Andorhal.",
		["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739} está junto a la granja de {area:202}, al noreste de los campos.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "El fantasma de {npc:10778} vaga junto a la casa de {area:199}, al oeste de {area:200}; su paquete está dentro.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} y {npc:7740} están junto al Templo de la Luna; llena el {item:11682} en el pozo de la luna de dentro.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "La granja de {npc:10927} está en la colina al este del campamento; el monumento de {npc:10936} está justo al norte.",
		["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, junto a las tumbas al sur de la capilla",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} protege la caldera de {area:199}, al oeste de Andorhal.",
		["{npc:11140} stands by Augustus' hut in {area:2627}."] = "{npc:11140} está junto a la cabaña de Augustus en {area:2627}.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach."] = "{npc:11613} recorre el aserradero Crestanorte al este de {npc:11610}; {npc:11611} protege la torre del acceso sur de {area:190}.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: las termitas vienen más tarde, en {area:2627}",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} es élite: conviene ir en grupo",
		["{npc:16256}: the last guide binds here, so this usually ticks at once"] = "{npc:16256}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} es élite de nivel 61",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal."] = "{npc:1852} es élite: conviene ir en grupo. Protege su filacteria en el centro de Andorhal.",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} en {area:976}: guárdala",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, en la costa al norte del pueblo",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: guárdala para {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "El campamento de {npc:7775} está al norte de {area:1119}. Vende el {item:11243} cuando tiene su cebo.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: guárdala para {zone:1446}",
		["{npc:8496}: keep it for Un'Goro"] = "{npc:8496}: guárdala para Un'Goro",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, en {area:1658}",
		["{object:175924}, in the farmhouse"] = "{object:175924}, en la casa de la granja",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, en {area:2268}: guárdala",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} en {zone:1450}: guárdala",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, donde se entrena en la siguiente guía, no tiene instructor de druidas",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Chromie in Andorhal: keep it"] = "Chromie en Andorhal: guárdala",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Los trituradores de arrastre excavan más al oeste; los tenazarios Latigosólido, cazadores Latigosólido y acechadores de piedra cazan en las mismas arenas.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Los artilleros de arrastre excavan en las dunas al noroeste del fuerte; los escórpidos Latigosólido y los arácnidos de arena deambulan por todas partes.",
		["Dredge and scorpids"] = "Arrastres y escórpidos",
		["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it."] = "Vuela desde {area:976} a {area:541}. La choza de {npc:8737} está en {area:538}, al oeste del refugio; {npc:9117} está colina arriba, detrás.",
		["Fly to {area:271} and ride north up the road toward Alterac: Haggerdin camps at {area:1056} beside it."] = "Vuela a {area:271} y cabalga al norte por el camino hacia las Montañas de Alterac: Haggerdin acampa en {area:1056}, junto a él.",
		["For {area:3197}: keep it"] = "Para {area:3197}: guárdala",
		["For {npc:10778}: keep it"] = "Para {npc:10778}: guárdala",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guárdala",
		["From {area:392}, fly to {area:976}."] = "Desde {area:392}, vuela a {area:976}.",
		["Its jars are filled on the next Un'Goro visit"] = "Sus jarras se llenan en la próxima visita a Un'Goro",
		["On {npc:7583}"] = "Con {npc:7583}",
		["Ride back to {area:3425} and fly to {area:392}."] = "Vuelve a {area:3425} y vuela a {area:392}.",
		["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Cabalga al este hasta la torre de {area:2742} en {area:2738}; súbela y mata a los emboscadores que surgen por el objeto incrustado.",
		["Ride east to {npc:13220}."] = "Cabalga al este hasta {npc:13220}.",
		["Ride north to the {area:2277}'s north-eastern edge."] = "Cabalga al norte hasta el borde noreste de {area:2277}.",
		["Ride on north to {area:3197} and fly to {area:2268}."] = "Sigue al norte hasta {area:3197} y vuela a {area:2268}.",
		["Ride out of the crater's north-western pass into {zone:1451} and on to {area:3425}."] = "Sal del cráter por el paso del noroeste hacia {zone:1451} y sigue hasta {area:3425}.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised."] = "Cabalga al suroeste hasta {area:2261}. El montón de tierra está dentro. {npc:11886} es élite: se recomienda ir en grupo.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Cabalga al suroeste hasta el campamento de {npc:7771} en el {area:1938}.",
		["Scourge Champions"] = "Campeones de la Plaga",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Los campeones de la Plaga (59) deambulan por {area:2270}, al norte de {area:2268}. Pasa el {item:13156} de {npc:11063} sobre cada uno que mates: las calaveras que resuenan son las que quiere. Atráelos de uno en uno.",
		["Sixty {item:2592}, if you carry them"] = "Sesenta {item:2592}, si los llevas",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Toma el barco de {area:392} a {area:35} y vuela a {zone:1453}.",
		["Take the {area:2257} to {zone:1455}."] = "Toma el {area:2257} hasta {zone:1455}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}."] = "Las bestias Tar se revuelcan en {area:538}; los elementales de fuego de {area:537}, en el centro, llevan la ceniza; las avispas gorishi de {area:540}, en el sur, llevan la glándula. Cualquier criatura del cráter puede soltar {item:11018}.",
		["The crater"] = "El cráter",
		["The next guide starts here in {area:392}."] = "La siguiente guía empieza aquí, en {area:392}.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Los druidas y centinelas torturados rondan el poblado en ruinas al suroeste de {npc:13220}.",
		["The western dunes"] = "Las dunas del oeste",
		["The {area:2742} tower"] = "La torre de {area:2742}",
		["Umber in {zone:1450}: keep it"] = "Umber en {zone:1450}: guárdala",
		["grind on {npc:8532} at the {area:2258}, {zone:1423}"] = "sube de nivel con {npc:8532} en {area:2258}, {zone:1423}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, de los campeones de la Plaga",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, de {npc:11886}",
		["{npc:14724}, by the tram"] = "{npc:14724}, junto al tranvía",
		["{npc:332}, in SI:7"] = "{npc:332}, en IV:7",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, que pasea por los canales",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} espera en el cementerio justo al este del pueblo; la lápida está cerca.",
		["{quest:3444} is in {area:392}"] = "{quest:3444} está en {area:392}",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} en {area:3197}: guárdala",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Osos Zarpira y lobos Zarpayel",
		["Araj is elite: grouping up is advised."] = "Araj es élite: se recomienda ir en grupo.",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber."] = "De vuelta en {area:1770}: {npc:9861} y {npc:9860} protegen a {npc:9517} en su cámara más profunda.",
		["Bronzebeard's Encampment"] = "Campamento Barbabronce",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Sube a {area:537}, en el centro del cráter, y usa el {item:14644} junto al lago de lava de la cima, con dos lingotes de torio en tus bolsas. Llena las jarras de muestra pura vacías de {npc:9616} con los mocos primarios de las charcas alrededor de la cresta.",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "Cruza el río al este de {npc:1855} hasta Valle del Terror. Los espíritus de {area:2627} rondan por el bosque.",
		["Dredge Crushers roam the dunes between {area:2743} and {area:3425}, on your way back. {npc:15181} only offers {quest:8304} from level 58."] = "Los trituradores de arrastre deambulan por las dunas entre {area:2743} y {area:3425}, de camino. {npc:15181} solo ofrece {quest:8304} a partir de nivel 58.",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Vuela a {area:3137} en {zone:1447} y cabalga al oeste por el camino hasta {area:2358}, justo pasada la frontera de {zone:1440}.",
		["Fly to {area:976}."] = "Vuela a {area:976}.",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Sigue el camino al norte hasta {area:1767}. Los vapuleadores Troncoferro llevan el corazón; termina las garras con los griseznos Zarpira y devastadores Zarpayel del norte.",
		["Follow the road south-west out of the pass to {area:3425}."] = "Sigue el camino al suroeste desde el paso hasta {area:3425}.",
		["Go back down to {area:702}, take the boat to {area:442} and the boat on to {area:17203}. Bring sixty Silk, sixty Mageweave and sixty {item:14047} for {npc:14722}: buy what you lack at the Auction House."] = "Vuelve a bajar a {area:702}, toma el barco a {area:442} y luego el barco a {area:17203}. Lleva sesenta de paño de seda, sesenta de tela de paño mágico y sesenta {item:14047} para {npc:14722}: compra lo que te falte en la casa de subastas.",
		["Grind to 58"] = "Sube a nivel 58",
		["Grind to 59"] = "Sube a nivel 59",
		["Grind to 60"] = "Sube a nivel 60",
		["Hand him the ten texts you kept"] = "Entrégale los diez textos que guardaste",
		["Havunth's camp sits just west of {area:3425}."] = "El campamento de Havunth está justo al oeste de {area:3425}.",
		["Hearth to {area:1519} and train your level 60 spells. This is the end of the leveling route: look at the reputation and dungeon guides next."] = "Usa tu piedra de hogar para ir a {area:1519} y entrena tus hechizos de nivel 60. Aquí termina la ruta de subida de nivel: mira después las guías de reputación y de mazmorras.",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Usa tu piedra de hogar para ir a {area:392} y vuela a {area:976}. Compra dos lingotes de torio en la casa de subastas de aquí para {quest:5801}.",
		["Into {zone:1451}"] = "Hacia {zone:1451}",
		["Irontree Stompers"] = "Vapuleadores Troncoferro",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Guarda el {item:11169}, las garras y el corazón que te devuelve",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "Sigue al oeste por el camino hasta el campamento de {npc:9298} junto a las aguas termales.",
		["Level 60"] = "Nivel 60",
		["Ride back north to {area:2255} and west along the road to the night elf village."] = "Vuelve al norte hasta {area:2255} y al oeste por el camino hasta el poblado elfo de la noche.",
		["Ride back south along the road to the Sanctuary."] = "Vuelve al sur por el camino hasta el Santuario.",
		["Ride back south-east to the hermit."] = "Vuelve al sureste hasta el ermitaño.",
		["Ride back south-west to {area:3197}."] = "Vuelve al suroeste hasta {area:3197}.",
		["Ride back to {area:3137} and fly to {area:2255}."] = "Vuelve a {area:3137} y vuela a {area:2255}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Cabalga al este hacia las colinas. Usa el {item:11169} para invocar a {quest:4005} y derrótalo para conseguir el tótem.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Cabalga al este hasta las ruinas de {area:2738}. El {object:179565} está entre los edificios en ruinas, vigilado por centinelas torturadas.",
		["Ride north along the west side to Mayna's small camp."] = "Cabalga al norte por el lado oeste hasta el pequeño campamento de Mayna.",
		["Ride north out of {area:415} into {zone:1448} to the druids' camp on the road just past the border."] = "Cabalga al norte desde {area:415} hasta {zone:1448}, al campamento de los druidas en el camino, justo pasada la frontera.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Cabalga al norte hasta el poblado de los fúrbolgs Muertobosque junto a la entrada de la cueva de {area:1769}.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Cabalga al norte hasta {area:541}. Usa {npc:10980} junto a {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Cabalga al norte por el camino hasta el aserradero y deja el barril de termitas en el centro.",
		["Ride south to {area:2250}. Protect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "Cabalga al sur hasta {area:2250}. Protege a {npc:10300} mientras enciende las antorchas camino del {object:177404}.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Cabalga al suroeste hasta el campamento enano cerca de las montañas del sur e interroga a {npc:15171} y {npc:15170}. La cartera de {npc:15190} está en la arena, justo al sureste del campamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Cabalga al suroeste hasta el campamento de {npc:7771} en el {area:1938}.",
		["Ride west along the crater's northern wall to the pass in the north-west corner that climbs into {zone:1451}."] = "Cabalga al oeste junto a la pared norte del cráter hasta el paso de la esquina noroeste que sube a {zone:1451}.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Hacer {area:2057} ({area:2298}, al sureste de {zone:1422}) o {area:2279} en vez de subir de nivel matando te lleva más rápido en grupo. Sáltate este paso para subir solo.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Hacer {area:2577} en {zone:1444} en vez de subir de nivel matando te lleva más rápido en grupo. Sáltate este paso para subir solo.",
		["Shaman training"] = "Entrenamiento de chamán",
		["Take the boat from {area:442} to {area:702}."] = "Toma el barco de {area:442} a {area:702}.",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "Toma la ruta de vuelo de {area:2361} y vuela a {area:442}.",
		["Take the portal up to {zone:1457}."] = "Toma el portal hasta {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Toma el camino al oeste, baja al cráter y cabalga hasta {area:540}, la cueva silítida del sur. La {npc:10041} espera en su cámara más profunda.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Toma el túnel de {area:1769} desde su entrada en {zone:1452}, al oeste de {npc:9298}, y sigue el ramal de {area:493} hasta {area:2361}. {npc:11939} estudia a orillas del lago.",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each want sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: 120 of each in all, from your bags or the Auction House."] = "Toma el {area:2257} hasta {zone:1455}. {npc:14724} y {npc:14723} quieren cada uno sesenta de paño de lana, sesenta de paño de seda y sesenta de tela de paño mágico, y luego sesenta {item:14047}: 120 de cada en total, de tus bolsas o de la casa de subastas.",
		["Ten more for {quest:8323}"] = "Diez más para {quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "La excavación del Martillo Crepuscular ocupa la esquina noroeste: hay fragmentos de tablilla en el suelo y los sirocosos y estruendores del desierto también los llevan. Cualquier cultor puede soltar un {item:20404}: guarda veinte, diez para {npc:15306} y diez para {npc:15194} más tarde.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "El ermitaño se esconde entre las rocas al sureste de {area:2738}.",
		["The {area:2479}"] = "El {area:2479}",
		["The {area:2739}"] = "El {area:2739}",
		["The {area:3098}"] = "El {area:3098}",
		["The {npc:7446} bears roam the snowy valley south of {area:2250}."] = "Los osos {npc:7446} recorren el valle nevado al sur de {area:2250}.",
		["Toward the north-west pass"] = "Hacia el paso del noroeste",
		["Twilight Tablet Fragments"] = "Fragmentos de tablilla ({item:20378})",
		["Twilight's Hammer cultists"] = "Cultores del Martillo Crepuscular",
		["Use the jars on slain oozes"] = "Usa las jarras en los mocos muertos",
		["Wait a moment for {npc:9116}"] = "Espera un momento a {npc:9116}",
		["You start in {area:392}, where the previous guide hearthed you. Fly to {area:415}."] = "Empiezas en {area:392}, donde la guía anterior te dejó con la piedra de hogar. Vuela a {area:415}.",
		["grind on {npc:11741} at the dunes east of {area:2743}, {zone:1451}"] = "sube de nivel con {npc:11741} en las dunas al este de {area:2743}, {zone:1451}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "sube de nivel con {npc:14564} en {area:2627}, {zone:1423}",
		["grind on {npc:7446} at the valley south of {area:2250}, {zone:1452}"] = "sube de nivel con {npc:7446} en el valle al sur de {area:2250}, {zone:1452}",
		["{area:1770} braziers"] = "Braseros de {area:1770}",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}."] = "{area:1770} es la cueva del fondo de {area:1763}, al oeste del camino. Usa el {item:12906} en los cuatro braseros del interior. Mata los osos Zarpira y lobos Zarpayel que encuentres para el {item:11172}.",
		["{area:2057} (optional)"] = "{area:2057} (opcional)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} es para niveles 58 a 60; {quest:5505} se entrega en {area:3197} más abajo.",
		["{area:2577} (optional)"] = "{area:2577} (opcional)",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577} es para niveles 55 a 60; matando {npc:7446} abajo llegas a 59 tú solo.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} espera en la posada en ruinas del lado oeste de Andorhal, la ciudad en ruinas al norte del campamento. {npc:1852} protege su filacteria en el centro del pueblo.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "El fantasma de {npc:10778} vaga junto a la granja de {area:199}, al oeste de Andorhal. Los necrófagos farfullantes del campo llevan la otra mitad del amuleto: combina las dos mitades.",
		["{npc:10924}: ends in {zone:1452}, keep it"] = "{npc:10924}: termina en {zone:1452}, guárdala",
		["{npc:11557}, if you have thirty {quest:6031}"] = "{npc:11557}, si tienes treinta {quest:6031}",
		["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw"] = "{npc:11558}, justo dentro de la cueva: solo desde Neutral con los Fauces de Madera",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "La casa de {npc:11801} está en {area:2361}, al este de {npc:11939}.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} ocupa el campamento de los cultores en el extremo suroeste.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, en el {object:2096}",
		["{npc:15174}, the innkeeper"] = "{npc:15174}, el posadero",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp."] = "{npc:17080} acampa fuera de {area:2743}, la colmena del oeste. Recoge una silitista en uno de los géiseres rojos cercanos y llévala al extractor de la Alianza de su campamento.",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, en las tiendas de la Alianza",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} es élite de nivel 61",
		["{npc:1855} (optional)"] = "{npc:1855} (opcional)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} vive en una pequeña choza junto al río fronterizo, al noreste del campamento maderero. Entrega {quest:5781} si la terminaste.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, en lo alto del {area:1658}",
		["{npc:4155}, in the bank"] = "{npc:4155}, en el banco",
		["{npc:6791}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6791}: la guía anterior te trae aquí con la piedra de hogar, así que esto suele marcarse al instante",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} en {zone:1457}: guárdala",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, en el Templo de la Luna",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, al fondo del refugio",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive."] = "{npc:9598} espera en {area:1767}. Escóltala fuera del bosque y mantenla con vida.",
		["{object:176091}, if you found the Firewater flask in {zone:1452}"] = "{object:176091}, si encontraste el frasco de agua de fuego en {zone:1452}",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} en {zone:1452}, guárdala",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} y las Tierras de la Peste",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train your level 60 spells with {npc:258098}."] = "{zone:1453} no tiene instructor de chamanes: toma el {area:2257} desde el {object:28027} hasta {zone:1455} y entrena tus hechizos de nivel 60 con {npc:258098}.",
} end)()
t.guides["forever/alliance/dwarf-gnome/01-dun-morogh"] = (function() return {
		["A few Frostmane Troll Whelps if you are short"] = "Algunas crías de trol Peloescarcha ({npc:706}) si te faltan",
		["A few more troggs outside if you are short"] = "Algunos troggs más fuera si te faltan",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Vuelve por el túnel a la cueva de {npc:257597} sobre la granja.",
		["Back to {area:77}"] = "Vuelve a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Vuelve con {npc:257446} en {area:77}. Te da el {item:6635}: toma el sendero marcado con escombros que sube al oeste desde el sur del valle hasta la piedra de espíritu de la cresta, bebe el sapta a su lado y habla con la {npc:5891}; después lleva su {item:6656} a Teo.",
		["Back to {npc:257597}"] = "Vuelve con {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of {area:87}."] = "Vuelve con {npc:6122}. Usa la {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que aparece. Después toca {zone:1436}, al oeste de {area:87}.",
		["Boars and bears"] = "Jabalíes y osos",
		["Cornelius is missing in the {area:136}: find him inside, then go back to Gretchen."] = "Cornelius ha desaparecido en {area:136}: encuéntralo dentro y vuelve con Gretchen.",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "Los Jabalíes del risco y los Osos negros jóvenes recorren los campos alrededor de {area:131} y del depósito.",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada misión de Grif Corazón Salvaje te da una {item:15908}: úsala en la bestia que indica y luego llévale la fusta a la herrería de {area:131}. Los Grandes jabalíes del risco, los Leopardos de la nieve y los Osos zarpahelada recorren los campos justo al sur y al este de {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa en la cresta que domina {area:134} desde el oeste. Habla con él para usar su visión lejana.",
		["Feather Charms, from the Frostmane Novices"] = "Talismanes de plumas, de los Novicios Peloescarcha",
		["Firewood"] = "Leña",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "Sigue el camino hasta el final, al este, hasta {area:806}, en el túnel de {zone:1432}.",
		["Follow the road east past the depot to {area:138}."] = "Sigue el camino al este pasando el depósito hasta {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Sigue el camino al noreste desde {area:131} hasta el depósito bajo el camino de {zone:1455}.",
		["Follow the road through the tunnel and north-east to {area:131}. Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. {npc:1252}, Eric and his campfire are outside the {area:2102}. {npc:6806}, {npc:1226} and {npc:1267} are inside. {npc:1872} works the forge."] = "Sigue el camino por el túnel y al noreste hasta {area:131}. Mata a los Jabalíes del risco por el camino: sus costillas caen antes de tener la misión de {npc:1267} y cuentan para ella. {npc:1252}, Eric y su hoguera están fuera de {area:2102}. {npc:6806}, {npc:1226} y {npc:1267} están dentro. {npc:1872} trabaja en la forja.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "Sigue el camino hasta {zone:1455} y ve a {object:32362}: {npc:5149}, {npc:6179} y {npc:6178} están en {object:32386}. {npc:6175}, un mendigo, deambula por la ciudad. Pide diez {item:2589}: los troggs y trols de {zone:1426} lo sueltan, y la casa de subastas lo vende.",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Sigue el camino hasta {zone:1455} y entrena con tu instructor de clase. El {area:2257} sale de {object:171524}, en el este de la ciudad. Tómalo hasta {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Del {quest:2997} que te da",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Las crías de trol Peloescarcha ({npc:706}) llenan las laderas al sur y al este del campamento de {npc:786}.",
		["Gnomes, bears and leopards"] = "Gnomos, osos y leopardos",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Atraviesa el túnel hasta {zone:1432}. Justo después, un sendero marcado con piedras sube por las colinas a la derecha del camino, hacia el norte, hasta el campamento de {npc:257808}.",
		["Hearth to {area:131}"] = "Usa la piedra de hogar para ir a {area:131}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Colgantes de oso garrahielo ({item:264356}), de las crías de trol Peloescarcha ({npc:706}) de las laderas sobre el campamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Sal de {zone:1453} por la puerta principal, ve al sur hasta {area:87} y al este por el camino hasta {area:62}. {npc:881} (nivel 9) está junto a su granja.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena el {item:7207} en su base.",
		["Leopards and boars"] = "Leopardos y jabalíes",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Los Gnomos parias de los alrededores de Las Birras y del camino de {area:133} llevan los engranajes y ruedas dentadas. Los Osos zarpahelada, los Jabalíes del risco mayores y los Leopardos de la nieve recorren las colinas alrededor del lago.",
		["Level 4 spells, before Gozwin's camp"] = "Hechizos de nivel 4, antes del campamento de Gozwin",
		["Minor Ice Elementals drift around the frozen lake by the refuge. The three rifles are in the snow around it."] = "Los Elementales de hielo menores flotan alrededor del lago helado junto al refugio. Los tres rifles están en la nieve a su alrededor.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Los Lobos jóvenes andrajosos recorren la nieve justo al sur de {area:77}.",
		["Ride back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Sal de {zone:1455} y cabalga al este por el camino hasta {area:212}. {npc:6177} yace muerto en su orilla: usa el {item:6866} en él. Los espías Hierro Negro que rondan el lago llevan el guion.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}."] = "Los Emboscadores Mentueso junto a {area:212}, al norte de la cantera, y los Partedorsales Mentueso más al este sueltan {quest:95214}.",
		["Rockjaw Bonesnappers prowl the quarry and {area:212}; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Los quebrantahuesos Mentueso ({npc:1117}) merodean por la cantera y {area:212}; los espías Hierro Negro se mueven a escondidas por la orilla del lago. Un espía suelta el {item:274268}.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "Los Aplastacráneos Mentueso llenan la cantera; los Emboscadores Mentueso junto a {area:212} sueltan el {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Los Troggs Mentueso y los Troggs Comepiedras fornidos excavan por todo el fondo del valle al sur de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff, then {npc:1699} in the distillery teaches you cooking."] = "Siéntate junto a la hoguera de Eric (escribe /sit) y espera al beneficio; luego {npc:1699}, en la destilería, te enseña cocina.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Los Jabalíes del risco pequeños pastan alrededor del campamento de {npc:714} y por el lado oeste del valle.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Los Leopardos de la nieve y los jabalíes recorren la nieve entre el rancho y la cantera. Herreros: los Lingotes de cobre se obtienen fundiendo {item:2770} o de los proveedores de mercancías.",
		["Speak with {npc:1699}"] = "Habla con {npc:1699}",
		["Spies and Bonesnappers"] = "Espías y quebrantahuesos",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Los Profetas Rompecantos (nivel 13) están entre los troggs del sur de {area:923}, al sur de {npc:257808}; los Geománticos Ratatúnel (nivel 12) trabajan en {area:149}, en el extremo norte del lago. Los troggs van en grupos y algunos atacan a distancia: atráelos de uno en uno.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Fire Spirit Stone"] = "La piedra del espíritu de fuego",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La Infusión de albaza hirviendo dura cinco minutos: ve directamente al norte hasta {npc:836}, dentro de {area:77}.",
		["The boars"] = "Los jabalíes",
		["The cold"] = "El frío",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "La leña está en la nieve alrededor del lago helado junto al refugio.",
		["The quarry lies south-east of the ranch."] = "La cantera está al sureste del rancho.",
		["The quarry troggs"] = "Los troggs de la cantera",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "El tranvía llega a {object:28027}. {npc:5480} entrena a los guerreros en {object:2100}; {npc:6089} y {npc:6090} están juntos junto a {object:2152}. {npc:6090} pelea contigo por su jarra.",
		["The troggs"] = "Los troggs",
		["The troll cave"] = "La cueva de los trols",
		["The tunnel"] = "El túnel",
		["The {area:2257}"] = "El {area:2257}",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}; {npc:1243} camps south-west of it, by the road to Coldridge."] = "{object:176785} está junto a {npc:271546}, al sur de {area:136}; {npc:1243} acampa al suroeste, junto al camino a Crestanevada.",
		["The {object:269} in the basement"] = "El {object:269} del sótano",
		["The {object:270} in the distillery"] = "El {object:270} de la destilería",
		["Use the {item:6866} on {npc:6177}"] = "Usa el {item:6866} en {npc:6177}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Empiezas delante de {area:77}, la sala de piedra del extremo norte del valle. {npc:658} espera fuera de la puerta.",
		["Young wolves"] = "Lobos jóvenes",
		["{area:131} and the depot"] = "{area:131} y el depósito",
		["{area:135} is the troll cave in the hills west of {area:137}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} es la cueva de los trols en las colinas al oeste de {area:137}. Mata a los rebanacabezas de la entrada y atraviésala hasta el fondo.",
		["{area:137} sits on the lake north-west of {area:135}."] = "{area:137} está junto al lago al noroeste de {area:135}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: el {object:176785}",
		["{item:2667}: the meat locker"] = "{item:2667}: la despensa de carne",
		["{item:2676} bushes grow on the hills around {area:137}."] = "Los arbustos de {item:2676} crecen en las colinas alrededor de {area:137}.",
		["{item:2686}, from {npc:1247} in the distillery"] = "{item:2686}, de {npc:1247} en la destilería",
		["{item:277976}, in the camp"] = "{item:277976}, en el campamento",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "El {item:286325} está junto al lago helado, entre los elementales de hielo.",
		["{item:2894}, from {npc:1247}"] = "{item:2894}, de {npc:1247}",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: Gnomos parias",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: Gnomos parias",
		["{item:5026} and the {item:6652}"] = "{item:5026} y la {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geománticos Ratatúnel",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, junto a la piedra de espíritu",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, junto a la piedra de espíritu",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: Profetas Rompecantos",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: espías Hierro Negro",
		["{npc:10090} in {zone:1455} takes it"] = "La recoge {npc:10090} en {zone:1455}",
		["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090} está en {object:32390}; {npc:258785}, en {object:32386}; {npc:6120}, en {object:32383}.",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: domestícalo con la {item:15908}",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: domestícalo con la {item:15908}",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: domestícalo con la {item:15908}",
		["{npc:1226}, next to {npc:6806}"] = "{npc:1226}, al lado de {npc:6806}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}: la recoge {npc:258785} en {zone:1455}",
		["{npc:1226}: {npc:376} in {zone:1453} takes it"] = "{npc:1226}: la recoge {npc:376} en {zone:1453}",
		["{npc:1231}, at the smithy"] = "{npc:1231}, en la herrería",
		["{npc:1254} and {npc:1256}"] = "{npc:1254} y {npc:1256}",
		["{npc:1266} camps in {area:801}, south of Brewnall. His meats are in the locker in {npc:1271}'s cave to the north-east of his camp: grab them and leave quickly."] = "{npc:1266} acampa en {area:801}, al sur de Las Birras. Sus carnes están en la taquilla de la cueva de {npc:1271}, al noreste de su campamento: cógelas y sal rápido.",
		["{npc:1269}, by the depot"] = "{npc:1269}, junto al depósito",
		["{npc:12738}, next to him"] = "{npc:12738}, a su lado",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: con tiempo límite, cinco minutos para llegar con {npc:836} en {area:77}",
		["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373} vigila los barriles de {item:2686} del sótano de la destilería. Compra una {item:2686} a {npc:1247}, haz clic en el barril vigilado y luego entrégale la cerveza a {npc:1373} desde su ventana de misión (no hay misión que aceptar); después, el barril sin vigilar acepta {spell:8553}.",
		["{npc:1373}, beside the barrel"] = "{npc:1373}, junto al barril",
		["{npc:1377}, at the depot"] = "{npc:1377}, en el depósito",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: solo herreros",
		["{npc:1960} waits at the {area:808}; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960} espera en {area:808}; el cadáver del enano está subiendo el paso al oeste de él.",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} guarda el túnel de salida del valle, al este de {area:77}; {npc:6782} está a su lado, en la boca.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, en la cantera",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, dentro de {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} y tu {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} espera en una cueva sobre la granja al noroeste de {area:806}; el sendero de subida empieza detrás de la granja.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} te da el {item:6636}. Sube a la cima sobre su campamento, bebe el sapta junto a la piedra de espíritu y derrota a la {npc:5893}; después coloca su {item:6655} en el {object:61934}, en lo alto del santuario de la Llama eterna.",
		["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}, el instructor de chamanes, al norte de {object:32372}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: la recoge {npc:257597}, junto a la Puerta Sur",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} está junto a {npc:8416}, en la puerta de {area:77}. El campamento de Gozwin está en las colinas justo al noroeste; el {npc:269075} merodea a su alrededor.",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376} está en la catedral.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, dentro de {area:77}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de los magos de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recoge {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:6179}: Redemption"] = "{npc:6179}: Redención",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: una runa para {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: lee la {quest:98581}",
		["{npc:6806}, in the distillery"] = "{npc:6806}, en la destilería",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, al lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. La {item:10438} está en la nieve al sur, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: cógelos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, bajo la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:836}, inside {area:77}"] = "{npc:836}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:8416}, by the door of {area:77}"] = "{npc:8416}, junto a la puerta de {area:77}",
		["{npc:895}, the hunter trainer"] = "{npc:895}, el instructor de cazadores",
		["{npc:912}, the warrior trainer"] = "{npc:912}, el instructor de guerreros",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:926}, the paladin trainer"] = "{npc:926}, el instructor de paladines",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, el instructor de magos, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
		["{quest:313} is the wendigo cave south-west of {area:131}. Flintfire's shipments lie on the cave floor."] = "{quest:313} es la cueva de los wendigos al suroeste de {area:131}. Los envíos de Fuegosílex están en el suelo de la cueva.",
		["{zone:1455} class quests"] = "Misiones de clase de {zone:1455}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tía\" Bernice Pedregosa",
		["Back south to the {area:120}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "Vuelve al sur hasta {area:120}, junto al camino a {zone:1436}. {npc:963} está fuera del cuartel, con {npc:955} a su lado.",
		["Back to the Cathedral of Light."] = "Vuelve a la Catedral de la Luz.",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Vuelve con {npc:6122} el Vinculaoscuro. Usa el {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que aparece.",
		["Bait ingredients"] = "Ingredientes del cebo",
		["Billy plays in the {area:64}, east of the mine."] = "Billy Maclure juega en {area:64}, al este de la mina.",
		["Boar meat"] = "Carne de jabalí",
		["Chunks of Boar Meat"] = "Trozos de carne de jabalí",
		["Crystal Kelp Fronds"] = "Hojas de kelp de cristal",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Los Zahoríes bribones Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en el poblado múrloc de la orilla noreste.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Los Matones Defias acampan en el claro al este de la abadía y por el lado este del valle.",
		["Follow the hills south to the tower, on the road west."] = "Sigue las colinas hacia el sur hasta la torre, en el camino al oeste.",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Sigue el sendero hacia el norte hasta la mina. Los Trabajadores kóbold pululan fuera; cualquier kóbold del valle puede soltar {object:83763}.",
		["Follow the road east past the {area:91} to the bridge."] = "Sigue el camino hacia el este pasando {area:91} hasta el puente.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:5497} está en el Sagrario del Mago, la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in {object:2100} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6171} y {npc:6173} están en la Catedral de la Luz; {npc:6174} está en {object:2100} y pide diez {item:2589} (lo sueltan los humanoides; se vende en la casa de subastas).",
		["Follow the road south out of the valley to {area:87}. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "Sigue el camino hacia el sur, fuera del valle, hasta {area:87}. {npc:295} está en la Posada Orgullo de León; {npc:240}, frente a la herrería al otro lado del camino; {npc:253}, delante de la posada; y {npc:241}, junto al camino al sur de ella.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Sigue el camino hacia el sur, fuera de {area:87}, hasta {area:64}. {npc:251} Maclure espera junto a la casa.",
		["Follow the road west back to {area:87}."] = "Sigue el camino hacia el oeste de vuelta a {area:87}.",
		["Follow the road west back to {area:87}; {npc:6306} and Jason stand on the lake shore before town."] = "Sigue el camino hacia el oeste de vuelta a {area:87}; {npc:6306} y Jason están en la orilla del lago antes del pueblo.",
		["Follow the road west past Westbrook into {zone:1436}, then south along it to {area:108}. Thor, the gryphon master, stands on the hill."] = "Sigue el camino hacia el oeste pasando el Cuartel de Arroyoeste hasta {zone:1436} y luego al sur por él hasta {area:108}. Thor, el maestro de grifos, está en la colina.",
		["From the {quest:2998} he gives you"] = "Del {quest:2998} que te da",
		["Fun with Elementals: {npc:248464}"] = "Álbum de fotos: diversión con elementales: {npc:248464}",
		["He stands by the river west of the farm."] = "Está junto al río, al oeste de la granja.",
		["Head north-west across the fields to the {quest:91736}, north of the {area:120}. Hand it four Shiny Red Apples for a {item:247824}."] = "Ve al noroeste a través de los campos hasta {quest:91736}, al norte de {area:120}. Échale cuatro Manzanas rojas lustrosas para obtener un {item:247824}.",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Los Obreros kóbold trabajan en los túneles de la mina. {npc:248362} espera tras el segundo giro a la derecha.",
		["Large Candles"] = "Velas grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} al pie de ella.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Libros perdidos: Mineros kóbold y Tuneladores",
		["Murloc Foragers and Lurkers line the river south of the bridge. {npc:473}, a Defias, walks the {area:62} west of it. Finish the Prowlers and Young Forest Bears on the way. {npc:248278} roams the murloc shore too: right-click the head it drops. {npc:248278} is elite: grouping up is advised."] = "Los Batidores múrloc y los Rondadores ocupan el río al sur del puente. {npc:473}, un Defias, recorre {area:62}, al oeste. Termina con los Merodeadores y los Osos del bosque jóvenes por el camino. {npc:248278} también ronda la orilla de los múrlocs: haz clic derecho en la cabeza que suelta. {npc:248278} es élite: se recomienda ir en grupo.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "Los múrlocs y los Correcorrientes múrloc ocupan la orilla este; los Montones de chatarra están en su campamento.",
		["Murlocs and the Collector"] = "Múrlocs y el Coleccionista",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "Al noreste del campamento maderero. Los Zahoríes bribones Defias acampan en las orillas del lago.",
		["Painted Gnoll Armbands"] = "Bandas gnoll pintadas",
		["Red Burlap Bandanas"] = "Arpilleras rojas",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Ride back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Vuelve a salir pasando por {area:87} y sigue el camino al este hasta {area:62}. {npc:881} (nivel 9) está junto a la casa de la granja.",
		["Ride back out through {area:87} and east to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Vuelve a salir pasando por {area:87} y ve al este hasta {area:86}. {npc:6172} yace al sur del lago: usa el {item:6866} en él. Los Zahoríes bribones Defias de alrededor llevan el {item:6846}.",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border. {npc:100}, a level 12 gnoll, walks among them and carries the {item:1307}: right-click it."] = "Los Jabatos Zarparrío y los Avanzados ocupan las colinas al sur del cuartel, a lo largo de la frontera con {zone:1436}. {npc:100}, un gnoll de nivel 12, anda entre ellos y lleva el {item:1307}: haz clic derecho en él.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["She sits inside the farmhouse."] = "Está sentada dentro de la casa de la granja.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Está junto a su carro, en el viñedo al este de la abadía.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Está fuera, en la entrada de la mina. {npc:248362}, dentro, es élite: se recomienda ir en grupo.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Manzanas rojas lustrosas, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Siéntate (/sentarse) junto a su hoguera hasta tener {spell:1229451}",
		["South down the road to the {area:64}."] = "Al sur por el camino hasta {area:64}.",
		["Speak with {npc:1430}"] = "Habla con {npc:1430}",
		["Stonetusk Boars graze between the vineyards and the farm."] = "Los Jabalíes colmillopétreo pastan entre los viñedos y la granja.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Defias camp"] = "El campamento Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Las trampas de pesca ({object:694772}) están en la orilla oeste del lago.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house."] = "La granja Pedregosa está al oeste de la mina. La vieja Pedregosa y la \"Tía\" Bernice están junto a la casa.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "El campamento está al noreste del puente. Los Fajos de madera están alrededor del campamento y en el bosque al norte.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Las cajas de uvas están en los viñedos, detrás de los Defias. {npc:103} espera junto a la cabaña del extremo este del valle.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The kobold camp"] = "El campamento kóbold",
		["The lake shore"] = "La orilla del lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mina está al oeste de los viñedos. Los Mineros kóbold y los Tuneladores llenan ambos niveles; {npc:248464}, un kóbold con nombre, tiene el álbum de fotos en los túneles inferiores. {npc:248464} es élite: se recomienda ir en grupo.",
		["The murloc camp"] = "El campamento múrloc",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Los múrlocs de la orilla este sueltan el kelp. Desolladores: los Lobos grises del bosque recorren el bosque entre el lago y {area:91}; los Merodeadores, más al este, también dan pieles.",
		["The vineyards and {npc:103}"] = "Los viñedos y {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way."] = "La {item:247813}, el Hacha empapada y la Caja de herramientas empapada están en el río al sur del puente. {npc:330}, una jabalina enorme, hoza en {area:62}, al oeste del río, con su {npc:390}: aparta primero a los cerditos. Mata Merodeadores y Osos del bosque jóvenes por el camino.",
		["The {quest:91736}"] = "{quest:91736}",
		["Torn Murloc Fins"] = "Aletas de múrloc rotas",
		["Use the {item:6866} on {npc:6172}"] = "Usa el {item:6866} en {npc:6172}",
		["Walk into the mine"] = "Entra en la mina",
		["Walk through the mine"] = "Recorre la mina",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Empiezas delante de la abadía. {npc:823} está al pie de la escalinata; {npc:197}, dentro de la sala; {npc:951} y {npc:247229}, en la biblioteca de la derecha; {npc:196}, fuera, en la esquina noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Los Lobos jóvenes y los Lobos madereros recorren los campos junto a la abadía.",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "su rastreador de kóbolds muestra los kóbolds en los que hacer clic en el camino a {area:87}",
		["{area:18} and the wolves"] = "{area:18} y los lobos",
		["{item:247824}, from the still"] = "{item:247824}, del alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Jabalíes colmillopétreo",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} del campamento Defias",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Zahoríes bribones Defias",
		["{npc:1430} cooks in the inn's kitchen."] = "{npc:1430} cocina en la cocina de la posada.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: domestícalo con la {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, el instructor de magos, dentro de la abadía",
		["{npc:247229}, in the library"] = "{npc:247229}, en la biblioteca",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} y {npc:248248} están al pie de la torre.",
		["{npc:248277} keeps watch at {area:798}, east of the murloc shore. Then head north-west back to the bridge."] = "{npc:248277} vigila en {area:798}, al este de la orilla de los múrlocs. Después vuelve al noroeste, hasta el puente.",
		["{npc:248415} stands behind the Abbey, by the stables."] = "{npc:248415} está detrás de la abadía, junto a los establos.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, junto a la abadía",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} está con los instructores de {area:87}. Cada una de sus misiones te da una {item:15908}: úsala en la bestia que te indique y devuélvele la vara. Los Jabalíes Ocultorroca y los Osos del bosque jóvenes recorren las colinas al sur de {area:64}; los Lobos grises del bosque, el bosque al este de {area:18}.",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, a su lado: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} vigila el puente del camino al este; {npc:248265} está justo al otro lado.",
		["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399} acampa al noreste de la posada; {npc:6306}, {npc:383} y {npc:1651} están en la orilla de {area:18}, al este del pueblo.",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279}, en {zone:1453}, lo recibe (02-westfall)",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: lo recibe {npc:5497}, en {zone:1453}",
		["{npc:375}, the priest trainer"] = "{npc:375}, la instructora de sacerdotes",
		["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377}: {npc:376}, en {zone:1453}, recibe ambos",
		["{npc:459}, outside the Abbey"] = "{npc:459}, fuera de la abadía",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: domestícalo con la {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: lo recibe {npc:6122}, en {zone:1453}",
		["{npc:6171}: Redemption"] = "{npc:6171}: Redención",
		["{npc:6306}: skinners only, the pelts are skinned"] = "{npc:6306}: solo desolladores, las pieles se desuellan",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, junto a los establos al sur de la abadía",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} excavan en los viñedos al noreste de la abadía. De vez en cuando uno suelta un {quest:91741}: haz clic derecho en él.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: domestícalo con la {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de vuelta en la escalinata de la abadía",
		["{npc:911}, the warrior trainer"] = "{npc:911}, el instructor de guerreros",
		["{npc:915}, the rogue trainer"] = "{npc:915}, el instructor de pícaros",
		["{npc:925}, the paladin trainer"] = "{npc:925}, el instructor de paladines",
		["{npc:927}: {npc:6171} in {zone:1453} takes it"] = "{npc:927}: lo recibe {npc:6171}, en {zone:1453}",
		["{npc:952}, upstairs"] = "{npc:952}, en el piso de arriba",
		["{npc:955}: he wants your {item:247824}"] = "{npc:955}: quiere tu {item:247824}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood."] = "{object:694855} crece en los campos alrededor de los viñedos y de la granja Pedregosa; los Jabalíes colmillopétreo de alrededor dan la sangre.",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} está dentro de {area:57}, no en la colina de encima: entra por la boca y ve por la izquierda hasta el fondo de la mina; no subas las escaleras. Los Bandidos Defias de los viñedos sueltan de vez en cuando una {item:1972}: haz clic derecho en ella.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} y {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sentarse junto a la hoguera de {npc:265811} hasta que tengas {spell:1229451}",
		["Back at {area:256}"] = "De vuelta en {area:256}",
		["Back to the moonwell."] = "Vuelve al pozo de la luna.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Vuelve a lo alto de {area:256}. El {object:654846} está a su lado.",
		["Bloodfeather harpies"] = "Arpías Plumasangre",
		["Boat to {zone:1453}"] = "Barco a {zone:1453}",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada misión de Dazalar te da una {item:15908}: úsala en la bestia que nombra y devuélvele la vara en {area:186}. Los rondadores Tejemadera merodean alrededor del poblado; los acechadores sable de la noche y los estridadores estrígidos recorren el bosque al sur.",
		["East to {area:260}"] = "Al este, hacia {area:260}",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolta a {npc:275744} fuera del túmulo; {npc:2081} en {area:186} recibe el informe.",
		["Fandral in {zone:1457} takes it"] = "La recibe Fandral en {zone:1457}",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}. Nightsabers and Webwood Lurkers keep roaming the road east. {object:126158} is in the house on the hill at the east end of the village."] = "Los conos inferi están bajo los árboles alrededor de {area:186} y {npc:2150}. Los sables de la Noche y los rondadores Tejemadera siguen por el camino al este. {object:126158} está en la casa de la colina, en el extremo este del poblado.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "Vuela otra vez a {area:702} y toma el portal hasta {npc:4217}; luego vuelve a volar a {area:442} para el barco.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Sigue el camino al suroeste desde {area:188}. {npc:2150} está sentado junto a él, justo al este de {area:186}.",
		["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "Sigue el camino al oeste hasta {zone:1457}. {npc:4241} está en la {area:1659}, justo al entrar en la ciudad. {npc:3516} está en el {area:1658}, en el extremo norte de la ciudad, y {quest:922} justo al sur; {npc:4092} y {npc:7999} están en el Templo de la Luna, en el extremo sur. {npc:7316} está en el oeste de la ciudad, camino del portal rosa que baja a la Aldea Rut'theran.",
		["From the harbour walk into {object:2100}. {npc:5480} trains warriors there; {npc:6089} and {npc:6090} stand together by the {object:2152}. {npc:6090} fights you for his mug."] = "Desde el puerto entra en {object:2100}. {npc:5480} entrena a los guerreros allí; {npc:6089} y {npc:6090} están juntos junto al {object:2152}. {npc:6090} pelea contigo por su jarra.",
		["From {area:17203}, ride through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "Desde {area:17203}, cruza las puertas de la ciudad hacia {zone:1429} y sigue el camino al oeste hasta {zone:1436}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Los emboscadores Tuercepinos se esconden a lo largo del camino al oeste de {area:258}.",
		["Gnarlpine Mystics and Ferocitas camp north-east of {area:260}. Ferocitas drops the {item:8049}: open it for the jewel."] = "Los místicos Tuercepinos y Ferocitas acampan al noreste de {area:260}. Ferocitas suelta la {item:8049}: ábrela para conseguir la joya.",
		["Gnarlpine Shamans"] = "Chamanes Tuercepinos",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vuelve a bajar a {area:702} y vuela a {area:442}. El {object:177525} está en las colinas justo al este del poblado: usa el {item:15208} allí, derrota a Lunaclaw y habla con el {npc:12144}.",
		["Hearth to {area:186}"] = "Usa tu piedra de hogar para ir a {area:186}",
		["Learn the {area:442} flight path on the hill south of the inn, then cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path in {area:2361} and fly to {area:702} (by way of {area:442})."] = "Aprende la ruta de vuelo de {area:442} en la colina al sur de la posada y lanza {spell:18960}. {npc:11802} está en {area:2361}; el {quest:5929} está en el bosque al noroeste. Aprende la ruta de vuelo de {area:493} en {area:2361} y vuela a {area:702} (pasando por {area:442}).",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Sal de {area:188} por el sendero al sureste de {area:256}: {npc:6780} está a su lado, donde baja hacia el camino a {area:186}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:8584} waits in the trees west of the cave mouth; {npc:1994} sits deep inside."] = "Los sables de la Noche sarnosos y los jabalíes Cardo deambulan al norte de {area:256}, camino de la cueva. {npc:8584} espera entre los árboles al oeste de la entrada de la cueva; {npc:1994} está al fondo.",
		["Nightsabers"] = "Sables de la Noche",
		["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east. The moonwell is at the west edge of {area:260}."] = "Los sables de la Noche, las lechuzas estrígidas y los rondadores Tejemadera rondan por todo {area:186} y a lo largo del camino al este. El pozo de la luna está en el borde oeste de {area:260}.",
		["North to {area:257}"] = "Al norte, hacia {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Al noreste desde la guarida de Ursal, de vuelta a {area:186}.",
		["Sentinel Arynia again"] = "Centinela Arynia otra vez",
		["South of Zenn. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Al sur de Zenn. {npc:2080} cuida sus arbolitos en la orilla; los brotes azotadores y los brezomaderas deambulan a su alrededor, y los {quest:919} crecen entre ellos.",
		["South of the pools. The {object:6751} grows by the Hold."] = "Al sur de las charcas. La {object:6751} crece junto al bastión.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Al sureste de Dolanaar, hasta {npc:2080}. Los brotes azotadores deambulan a su alrededor en la orilla.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Al suroeste del túmulo. El pozo de la luna está junto a las charcas.",
		["Speak with the {quest:5929}"] = "Habla con el {quest:5929}",
		["Speak with {npc:6286}, south of the inn"] = "Habla con {npc:6286}, al sur de la posada",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs."] = "Toma el portal hasta {area:702}. {npc:10118} está en el muelle, {npc:3838} junto a los hipogrifos.",
		["Take the portal up from {area:702} to {npc:4217} in the {area:1658}."] = "Toma el portal de {area:702} hasta {npc:4217}, en el {area:1658}.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Toma otra vez el camino al noroeste desde {area:186}; sigue tendida a su lado, camino de {zone:1457}.",
		["Take the road north-west from {area:186} towards the {area:264}; she lies hurt beside it."] = "Toma el camino al noroeste desde {area:186} hacia el {area:264}; ella yace herida a su lado.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade."] = "Las arpías Plumasangre anidan en las laderas al oeste y al norte del claro.",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "El túmulo está al sur del camino. {npc:275744} está retenida dentro, {npc:7317} duerme en lo más hondo y los cuatro cofres de reliquias están en las salas inferiores.",
		["The moonwell and {npc:8584}"] = "El pozo de la luna y {npc:8584}",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "El pozo de la luna está en el centro del claro. La {object:6752} crece en su extremo norte.",
		["The moonwell sits north of {area:256}; {npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "El pozo de la luna está al norte de {area:256}; {npc:8584} está un poco más al noroeste. {quest:3522} dura cinco minutos: llena la redoma y ve directo a él.",
		["The named harpies"] = "Las arpías con nombre",
		["The road to {zone:1457}"] = "El camino a {zone:1457}",
		["The {area:478}"] = "El {area:478}",
		["The {object:177525}"] = "El {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Los {object:4406} están al fondo de {area:257}: toma el sendero central, luego a la izquierda donde se divide, hasta la cornisa alta. Los grells sueltan champiñones jacinto; los lirios alunados crecen junto a las charcas al norte de {area:256}.",
		["Use the {item:5185} at the moonwell"] = "Usa la {item:5185} en el pozo de la luna",
		["Use the {item:5619} at the moonwell"] = "Usa la {item:5619} en el pozo de la luna",
		["Use the {item:5621} at the moonwell"] = "Usa la {item:5621} en el pozo de la luna",
		["Use the {item:5623} at the moonwell"] = "Usa la {item:5623} en el pozo de la luna",
		["Walk Lynessa out and keep her alive"] = "Saca a Lynessa y mantenla con vida",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}."] = "Ve al sur por el lado oeste de la isla. Ursal merodea por el extremo sur, debajo del {area:478}.",
		["Webwood Lurkers"] = "Rondadores Tejemadera",
		["Webwood Spiders"] = "Arañas Tejemadera",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Empiezas al pie de {area:256}, el gran árbol de {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Los sables de la Noche jóvenes y los jóvenes jabalíes Cardo deambulan alrededor de {area:256}. Los grells llevan {item:3297} en el bosque al oeste del árbol, donde están los tótems Tuercepinos.",
		["{area:186} again"] = "{area:186} otra vez",
		["{area:186} quests"] = "Misiones de {area:186}",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:736}, outside the barrow"] = "{area:736}, fuera del túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, junto a {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, en el Templo de la Luna: Fragmentos estelares",
		["{npc:1992}, south of the tree"] = "{npc:1992}, al sur del árbol",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: domestícalo con la {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: domestícalo con la {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro de la cueva, abajo o arriba en la cornisa; ve por la derecha.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: domestícalo con la {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto al sendero",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: un sigilo para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: la recibe {quest:922} en {zone:1457}",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, en la rampa del árbol",
		["{npc:2150}, on the way back"] = "{npc:2150}, a la vuelta",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulla el camino al oeste de la aldea: si no está en la flecha, sigue el camino hasta encontrarla.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, en el camino al oeste del poblado",
		["{npc:265811}, by the campfire"] = "{npc:265811}, junto a la hoguera",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034} y {npc:272044} vuelan justo al oeste del pozo de la luna, {npc:272046} más al norte.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, en lo alto del árbol",
		["{npc:3515}, south of the inn"] = "{npc:3515}, al sur de la posada",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, en el {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}, junto al pozo de la luna",
		["{npc:3567}, back in {area:186}"] = "{npc:3567}, de vuelta en {area:186}",
		["{npc:3593}, the warrior trainer"] = "{npc:3593}, el instructor de guerreros",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}, el instructor de pícaros",
		["{npc:3595}, inside the tree"] = "{npc:3595}, dentro del árbol",
		["{npc:3595}, the priest trainer, inside the tree"] = "{npc:3595}, el instructor de sacerdotes, dentro del árbol",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}, el instructor de cazadores",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, el instructor de druidas en {area:256}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: la recibe {npc:11401} en {zone:1457}",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: la recibe {npc:4217} en {zone:1457}",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}, en el Templo de la Luna",
		["{npc:4146} in {zone:1457} takes it"] = "La recibe {npc:4146} en {zone:1457}",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, en el {area:1658}: {spell:5149}",
		["{npc:4200}'s fish stall is by the docks. Then take the boat to {zone:1453}."] = "El puesto de pescado de {npc:4200} está junto a los muelles. Luego toma el barco a {zone:1453}.",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}, en el {area:1658}",
		["{npc:7318}, in the den"] = "{npc:7318}, en la guarida",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}, encima de {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583}, al este del árbol",
		["{object:673378}, just west of the moonwell"] = "{object:673378}, justo al oeste del pozo de la luna",
		["{object:7510}, beside him"] = "{object:7510}, a su lado",
		["{quest:488} and the Starbreeze moonwell"] = "{quest:488} y el pozo de la luna de Brisa Estelar",
		["{quest:917} and the antidote"] = "{quest:917} y el antídoto",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: lanza {spell:1259799} y Fusión de las Sombras, y luego entrégasela a {npc:3595}",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Usa /sentarse junto a la hoguera de {npc:263664} hasta obtener {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Los rastreatormentas y soldados de a pie Al'Aketh acampan justo al norte de {npc:257944} y sueltan la reliquia; los chilladores al oeste de ella sueltan las plumas y las garras; el {item:265105} crece junto al arroyo al oeste de ella.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De vuelta en {quest:92529}: los clamatormentas y {npc:251662} llenan el pueblo, los clamatormentas llevan los suministros robados y {npc:251966} está en el extremo sur.",
		["Back to Shen'dar"] = "Vuelve a Shen'dar",
		["Back to the Hermit"] = "Vuelve con el ermitaño",
		["Back to {area:16622}"] = "Vuelve a {area:16622}",
		["Back to {npc:255853} by the falls north-east of {area:16638}, on the way north to the shrine."] = "Vuelve con {npc:255853} junto a las cascadas al noreste de {area:16638}, de camino al norte hacia el santuario.",
		["Bandit Highwaymen"] = "Bandidos salteadores",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon está en la sala del trono de {object:2117}, en el extremo norte de la ciudad. Luego sal por la puerta principal hacia {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Lanza {spell:1259705} sobre la línea ley",
		["Desperate times"] = "Tiempos desesperados",
		["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "Cada misión de Quel'ana te da una {item:15908}: úsala en la bestia que indica y devuélvele la vara en {area:16638}. Los reptadores Canzalvaje pueblan la orilla al oeste del pueblo; los vuldren alfa y los zancavendavales malhumorados rondan {area:16626} alrededor de la granja de los Campovento. Su hermana {npc:254411} está a su lado.",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Ábrete paso al norte hasta {area:16629}. Guardianes, clamaespíritus y maestros del acero defienden el acceso; {npc:253576} espera en la puerta del santuario, y {npc:253590}, dentro del sanctasanctórum.",
		["Find Fillion and his bedroll"] = "Encuentra a Fillion y su petate",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Sigue el camino al sur hasta {area:16624}. {npc:263664} acampa junto al fuego al oeste del pueblo; {npc:251523} y {npc:251903} están en el centro.",
		["For {npc:234} at {area:108}"] = "Para {npc:234} en {area:108}",
		["Havoc in Falaath"] = "Caos en Falaath",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Ve al norte hacia {area:16631}. {npc:257944} acampa en su parte este.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them."] = "Ve al noroeste hasta los nidos de hipogrifo de los acantilados occidentales. El {item:263493} está alrededor de los nidos; la matriarca patrulla entre ellos.",
		["Heal 7 druids in the Nightfang Den, then find {npc:258130}"] = "Sana a 7 druidas en la Nightfang Den y luego busca a {npc:258130}",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena el {item:7207} en su base.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Level 6 spells"] = "Hechizos de nivel 6",
		["Listen to {npc:257554}"] = "Escucha a {npc:257554}",
		["Lorthuna waits on the eastern shore of the isle, east of the {area:16629}."] = "Lorthuna espera en la costa este de la isla, al este de {area:16629}.",
		["Meet Valennia at the gate"] = "Reúnete con Valennia en la puerta",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Al norte de las piñas: los huecos ventosos flotan alrededor del campamento de refugiados, las {item:266433} están entre las tiendas y {npc:259013} yace en su extremo norte.",
		["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "Al noroeste de Valanaar, siguiendo el camino: {npc:273017} vigila a los {quest:98512}; el cultor muerto yace justo al norte de él.",
		["Prideclaws and Galestriders"] = "Garramanadas y zancavendavales",
		["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "Las garramanadas y los zancavendavales rondan los pastizales al sur del pueblo. Los zancavendavales sueltan tanto los huevos como la carne.",
		["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "Reúne a Valennia, {npc:251968} (al oeste del pueblo) y {npc:252475}",
		["Raw Windstones and the {npc:251404}"] = "Piedras de viento en bruto y la {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Las manzanas tempestuosas maduras y los bandidos hambrientos están en el huerto junto a la granja, {quest:92683} en los campos al noreste, y los zancavendavales malhumorados por todas partes. El {npc:250929} está en el campo al noreste de la granja.",
		["Search the dead cultist"] = "Registra al cultor muerto",
		["Search the wardrobe"] = "Registra el armario",
		["Shen'dar turn-ins"] = "Entregas en Shen'dar",
		["Skycutter to {area:279}"] = "Cortacielos a {area:279}",
		["Skyhoppers"] = "Saltanubes",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Los saltanubes pululan por los campos al oeste de {area:16638}.",
		["Speak with {npc:251903} and {npc:254089}, north-west of the village"] = "Habla con {npc:251903} y {npc:254089}, al noroeste del pueblo",
		["Stand with {npc:252800} against {npc:252863}"] = "Lucha junto a {npc:252800} contra {npc:252863}",
		["Standing our ground"] = "Nos mantenemos firmes",
		["Take the road south-east. {npc:257006} and {npc:252448} stand by the road west of {area:16638}; Windsong Crawlers line the shore further west, around 51,70."] = "Toma el camino al sureste. {npc:257006} y {npc:252448} están junto al camino al oeste de {area:16638}; los reptadores Canzalvaje pueblan la orilla más al oeste, hacia 51,70.",
		["Tame it with the {item:15908}"] = "Domestícalo con la {item:15908}",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Los bandidos salteadores ocupan las colinas al norte de la granja.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Los bandidos de las Tierras Altas acampan al noreste del pueblo. \"Malabrisa\" Bennic espera en el extremo norte de su campamento.",
		["The Highlands bandits"] = "Los bandidos de las Tierras Altas",
		["The Novice Seers practise in the clearing west of Shen'dar."] = "Los videntes novatos practican en el claro al oeste de Shen'dar.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Las piedras de viento en bruto brillan en el suelo justo al sur de la arboleda. {quest:92463} revolotea sobre el prado más al este, de camino a {npc:249363}.",
		["The Windfield farm"] = "La granja de los Campovento",
		["The Windstone Formations"] = "Las formaciones de piedras de viento",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Las formaciones de piedras de viento están en la loma al oeste del campamento de Fillion.",
		["The bounty board"] = "El tablón de recompensas",
		["The class trainers stand together in the grove"] = "Los instructores de clase están juntos en la arboleda",
		["The dead cultist"] = "El cultor muerto",
		["The eastern watchtower"] = "La atalaya oriental",
		["The hippogryph roost"] = "El nidal de hipogrifos",
		["The missing scholar"] = "El erudito desaparecido",
		["The refugees' camp"] = "El campamento de refugiados",
		["The road to {area:16638}"] = "El camino a {area:16638}",
		["The skycutter"] = "El cortacielos",
		["The skycutter docks at the tower south of {area:16638}. It lands by the Kirin Tor camp on the lake shore west of {area:279}."] = "El cortacielos atraca en la torre al sur de {area:16638}. Aterriza junto al campamento del Kirin Tor en la orilla del lago al oeste de {area:279}.",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "La {item:254871}",
		["The {object:581822}"] = "La {object:581822}",
		["The {object:581822} lies by the path west of {area:16638}; Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "La {object:581822} está junto al sendero al oeste de {area:16638}; el campamento de Fillion está al noroeste, y las matriarcas chilladoras anidan justo al oeste del campamento.",
		["Use {spell:1259416}"] = "Usa {spell:1259416}",
		["Village quests"] = "Misiones del pueblo",
		["Vuldren and Cirrusflies"] = "Vuldren y moscas de cirro",
		["Windshaper Novice Seers"] = "Videntes novatos Formavientos",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Te despiertas en {area:16622}. {npc:251362} está a tu lado; {npc:251361} está a unos pasos al oeste, y {npc:251368}, junto al borde sur de la arboleda.",
		["{area:16622} turn-ins"] = "Entregas en {area:16622}",
		["{area:16624} again"] = "De nuevo {area:16624}",
		["{area:16638} turn-ins"] = "Entregas en {area:16638}",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, el destino de Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, el traidor",
		["{item:262668}: by the wind shrine south of {quest:92529}"] = "{item:262668}: junto al santuario del viento al sur de {quest:92529}",
		["{item:263993}: {npc:257196}, west of the shrine's approach"] = "{item:263993}: {npc:257196}, al oeste del acceso al santuario",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} vigila al este de la arboleda. Los {npc:251143} y los convertidos Al'Aketh ({npc:251160}) se reúnen justo al norte de ella; la línea ley se alza más al norte: lanza sobre ella tu habilidad racial {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} y moscas de cirro molestas rondan el prado justo al sureste de la arboleda.",
		["{npc:250926} and {npc:251115}"] = "{npc:250926} y {npc:251115}",
		["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926} merodean por el bosque justo al oeste de la arboleda; los ursera carroñeros tienen su guarida más al oeste, con {npc:251115}, la matriarca, al fondo.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: una nota de tu instructor",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: lee la {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: la {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, el instructor de druidas, en la planta baja del árbol detrás de {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, la instructora de magos: lee primero el {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, en la atalaya",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, en la atalaya",
		["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle."] = "{npc:252095} acampa al sur de la guarida de los ursera. Los matones Al'Aketh ocupan el campamento al suroeste de ella; {npc:256935} está en el centro.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} defiende la torre occidental, al suroeste de Falaath. {npc:256966} y los guardias caídos yacen justo al sur de ella.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, el instructor de magos",
		["{npc:252377}: {npc:257196} waits at the {area:16629}"] = "{npc:252377}: {npc:257196} espera en {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} defiende la atalaya al norte de {area:16638}. El campamento Al'Aketh está justo al oeste de la torre, con sus sanadores hacia 65,68 y 65,65; {npc:252666} está en su extremo norte. Los Al'Aketh de allí sueltan Windstone Charms.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} y {npc:252476} están en el extremo norte de {area:16638}; {npc:252475} y {npc:253204}, en el extremo sur.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} espera junto al portal de los cielonatos",
		["{npc:252800} again"] = "De nuevo {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} lleva la granja de las tierras bajas del suroeste.",
		["{npc:253590}, in the sanctum"] = "{npc:253590}, en el sanctasanctórum",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}."] = "{npc:254151}, {npc:258130} y {npc:258134} están al noreste de {npc:257944}; {npc:253622} está al este de ellos. Haalien también suelta una {quest:94490}.",
		["{npc:254588}: tame it with the {item:15908}"] = "{npc:254588}: domestícalo con la {item:15908}",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} acecha en las colinas al suroeste del pueblo, de camino de vuelta. {npc:254589} es élite: conviene ir en grupo.",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853} espera junto a las cascadas al noreste de {area:16638}. {npc:258443} merodea por {area:16623} al oeste de {area:16638}, junto al camino que tomarás después.",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} espera en la entrada de {quest:92529}, al sur de Shen'dar. La {spell:1254832} te permite entrar entre los fieles.",
		["{npc:257944} again"] = "De nuevo {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}, la misiva",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, en las tierras altas al suroeste del cultor",
		["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "{npc:259084} está junto al portal de los cielonatos, donde aterriza el zepelín. El portal te lleva a {zone:1453}.",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}, junto a {npc:259084}: para {npc:5504} en {zone:1453}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, el instructor de druidas de {zone:1453}, te enseña {spell:18960}. La bienvenida de {npc:11802} espera a tu viaje de {spell:499} al final de {zone:1439}.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} vive al oeste de {npc:257944}. Los conos de semilla de céfiro ({object:613238}) están en el bosque entre su cabaña y {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "En el {area:2362}",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. Fly to {area:702} afterwards."] = "Lanza {spell:18960}. Une las dos mitades en {item:15885} cerca del {area:2362}, en la orilla noroeste del lago, y luego ve a ver a {npc:11802} en {area:2361}. Después, vuela a {area:702}.",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. {npc:11798} flies druids to {area:1638}."] = "Lanza {spell:18960}. Une las dos mitades en {item:15885} cerca del {area:2362}, en la orilla noroeste del lago, y luego ve a ver a {npc:11802} en {area:2361}. {npc:11798} lleva a los druidas a {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. Los adornos de altar ({item:15877}) están en los contenedores del fondo de {area:656}, bajo {area:2361}: lleva uno al {area:2362}, en la orilla noroeste, úsalo allí y habla con {npc:11799}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. Los adornos de altar ({item:15877}) están en el fondo de {area:656} y desaparecen en pocos minutos: lleva uno a nado directamente al {area:2362}, en la orilla noroeste, úsalo allí y habla con {npc:11799}.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies under the water off the north coast, west of the {area:443}."] = "Vuela de {area:2361} a {area:442}. {object:177792} está bajo el agua frente a la costa norte, al oeste de {area:443}.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Ride north-west to the coast: the {object:177790} lies on the sea floor off the shore."] = "Toma el barco de {area:442} a {zone:1453} y vuela a {area:108}. Cabalga al noroeste hasta la costa: la {object:177790} está en el fondo del mar frente a la orilla.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Toma el portal para subir hasta {npc:4217} en {area:1658}.",
		["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies on the coast west of the {area:240}, north of the {area:228}."] = "Toma el vuelo de {npc:11798} a {zone:1456}, vuela a {zone:1454} y toma el zepelín a {zone:1420}; {zone:1421} está al sur de {zone:1458}. La {object:177790} está en la costa al oeste de {area:240}, al norte de {area:228}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower, north of the {area:380}."] = "{object:177792} está en el borde norte de {area:382}, junto a la torre de Ventura y Cía., al norte de {area:380}.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Tu forma de viaje acuática: nada rápido y respira bajo el agua, y además un cinturón y un ídolo.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de un {object:177785} del lago",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: une las mitades en el altar",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} está en {area:1639}.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} está en {area:1658}.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "A nivel 10 te llega la llamada de un druida: {npc:3064} en {area:222} o {npc:6746} en {zone:1456} (también sirve la carta de {npc:6929} en {zone:1454}). Cualquiera de ellos te envía con {npc:3033} en {area:1639}, en {zone:1456}.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "A nivel 10 te llega la llamada de un druida: {npc:3602} en {area:186}, Denatharion en {zone:1457} o Theridran en {zone:1453}. Cualquiera de ellos te envía con {npc:4217} en el Enclave Cenarion de Darnassus.",
		["Back to {npc:255853} by the falls."] = "Vuelve con {npc:255853} junto a las cascadas.",
		["Back to {npc:3033} on {area:1639}."] = "Vuelve con {npc:3033} en {area:1639}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Learn the {area:493} flight path while you are here."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. Aprende la ruta de vuelo de {area:493} ya que estás aquí.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path, then fly to {area:702} (by way of {area:442}) and take the portal up to {zone:1457}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; el {quest:5929} está en el bosque al noroeste. Aprende la ruta de vuelo de {area:493}, vuela a {area:702} (pasando por {area:442}) y toma el portal para subir a {zone:1457}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the woods to the north-west. {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; el {quest:5930} está en el bosque al noroeste. {npc:11798}, en {area:2361}, lleva volando a los druidas a {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Vuelve volando a {area:702} y toma el portal para subir con {npc:4217}.",
		["Fly from {area:702} to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vuela de {area:702} a {area:442}. {object:177525} está en las colinas justo al este del pueblo: usa allí el {item:15208}, derrota a Garraluna y habla con el {npc:12144}.",
		["Skyboat from {area:279}"] = "Barco celeste desde {area:279}",
		["Skyboat from {zone:1456}"] = "Barco celeste desde {zone:1456}",
		["Skyboat to {zone:2521}"] = "Barco celeste a {zone:2521}",
		["Speak with the {quest:5929}"] = "Habla con el {quest:5929}",
		["Speak with the {quest:5930}"] = "Habla con el {quest:5930}",
		["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer."] = "El portal de los cielonatos te lleva a {zone:1453}. {npc:5504} es el instructor de druidas de la ciudad.",
		["The {object:177525}"] = "{object:177525}",
		["The {object:177525} stands in the pass from {zone:1412} into the {zone:1413}. Use the {item:15710} there, defeat Lunaclaw and speak to the {npc:12144}."] = "{object:177525} está en el paso de {zone:1412} a {zone:1413}. Usa allí el {item:15710}, derrota a Garraluna y habla con el {npc:12144}.",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Tu forma de tanque: Forever ya no enseña {spell:5487} en el instructor; te la dan estas misiones. También abre {area:493}.",
		["or whichever of the three letters you carry"] = "o la carta que lleves de las tres",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} está en {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} y {npc:258443}",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623}, west of {area:16638}."] = "{npc:255853} espera junto a las cascadas al noreste de {area:16638}. {npc:258443} merodea por {area:16623}, al oeste de {area:16638}.",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118} espera donde aterriza la aeronave de {zone:2521}, en el norte de {zone:1412}, junto a {zone:1456}.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} está junto a {npc:259084} y el portal de los cielonatos, al oeste de {area:279}, donde aterriza el cortacielos de {zone:2521}. {npc:2543} ofrece la misma misión.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} está en {area:1639}.",
		["{npc:3033} trains druids on {area:1639}."] = "{npc:3033} entrena a los druidas en {area:1639}.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; las cartas de Pala y Gryshka llevan al mismo sitio",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; las cartas de Denatharion y Theridran llevan al mismo sitio",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} está en {area:1658}.",
		["{spell:5487} and {area:493}"] = "{spell:5487} y {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} se aprende en {zone:2521}. Omite esto si sigues en la isla; si no, toma el barco celeste en los acantilados al sur de {area:17045}, al norte de {zone:1456}.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} se aprende en {zone:2521}. Omite esto si sigues en la isla; si no, toma el barco celeste en el lado norte de {area:279}.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Vuelve con {npc:9619}, en la esquina sureste de {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer offers the same quest."] = "Lanza {spell:18960}. {npc:12042} está en {area:2361}; tu instructor de clase ofrece la misma misión.",
		["Experience in Un'Goro at 50 and two healing potions; Forever removed the Classic item choice."] = "Experiencia en Un'Goro a nivel 50 y dos pociones de sanación; Forever eliminó la elección de objeto de Classic.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Vuela a {area:976} y cabalga al oeste hasta la larga rampa que baja a {zone:1449}: {npc:9619} acampa al pie, en la esquina sureste del cráter.",
		["Gorishi Stings and {item:22434}"] = "Aguijones Gorishi y {item:22434}",
		["The Gorishi wasps, workers and reavers of the hive in the south of the crater drop the stings; the Bloodpetal Sprouts that give the {item:22434} grow all over the crater's western half."] = "Las avispas, obreras y atracadoras Gorishi de la colmena del sur del cráter sueltan los aguijones; los Brotes pétalo de sangre que dan {item:22434} crecen por toda la mitad oeste del cráter.",
		["The {area:1417}"] = "El {area:1417}",
		["Use the {item:22432} on a {npc:6498}. Devilsaurs are elite (level 54-55) and roam the crater: grouping up is advised."] = "Usa {item:22432} en un {npc:6498}. Los devilsaurios son élite (nivel 54-55) y recorren el cráter: se recomienda ir en grupo.",
		["{area:1477} lies in the {area:74} in the {zone:1435}. {npc:8580} guards the bottom of the temple: a dungeon boss, so bring a group."] = "{area:1477} está en {area:74}, en {zone:1435}. {npc:8580} guarda el fondo del templo: es un jefe de mazmorra, así que lleva un grupo.",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: apuñálalo con {item:22432}",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "De vuelta con {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702}."] = "Vuelve con {npc:11802} en {area:2361} y luego vuela a {area:702}.",
		["Back to {npc:11802} in {area:2361}, then take {npc:11798}'s flight to {area:1638}."] = "Vuelve con {npc:11802} en {area:2361} y luego toma el vuelo de {npc:11798} a {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; aprende allí la ruta de vuelo si no la tienes.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Toma el portal para subir hasta {npc:4217} en el {area:1658}.",
		["The relics of the Barrow Dens"] = "Las reliquias del Túmulo",
		["The {area:2363}"] = "El {area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Tu forma de sigilo y cuerpo a cuerpo: en Forever, {spell:768} se obtiene a nivel 20 con esta cadena, no con el instructor.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} está en {area:1639}.",
		["{npc:4217} stands in the {area:1658}. Skyborne without the Rut'theran flight path: take the boat from {area:442}."] = "{npc:4217} está en el {area:1658}. Si eres cielonato y no tienes la ruta de vuelo de Rut'theran, toma el barco desde {area:442}.",
		["{quest:98342} (Tauren) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98342} (tauren) espera en la colina del sur sobre el puente; el {npc:272054} (cielonatos), al sur de los puentes gemelos. Las reliquias están en el {area:2363}, al este del lago: sal de tu forma, pulsa la estatua de la entrada para obtener cinco minutos de sigilo, evita a los espíritus del interior y coge una de cada reliquia; la {item:280680} está a los pies de la estatua del gato blanco. Una reliquia no da botín mientras otro jugador la despoja: espera un momento y vuelve a intentarlo.",
		["{quest:98394} (Night Elves) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (elfos de la noche) espera en la colina del sur sobre el puente; el {npc:272054} (cielonatos), al sur de los puentes gemelos. Las reliquias están en el {area:2363}, al este del lago: sal de tu forma, pulsa la estatua de la entrada para obtener cinco minutos de sigilo, evita a los espíritus del interior y coge una de cada reliquia; la {item:280680} está a los pies de la estatua del gato blanco. Una reliquia no da botín mientras otro jugador la despoja: espera un momento y vuelve a intentarlo.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}."] = "De vuelta en {area:442}.",
		["Cast {spell:18960} and see {npc:11802}, then fly to {area:702} and take the portal up to {zone:1457}."] = "Lanza {spell:18960} y habla con {npc:11802}; luego vuela a {area:702} y toma el portal para subir a {zone:1457}.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}."] = "Lanza {spell:18960} y habla con {npc:11802}; luego toma el vuelo de {npc:11798} a {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Then fly to {area:442}."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. Luego vuela a {area:442}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}. {npc:11798} lleva a los druidas a {area:1638}; desde allí, vuela a {area:380}.",
		["From the {area:380} ride north to {area:384} and fill the {item:15842} at the {object:19464}."] = "Desde {area:380}, cabalga al norte hasta {area:384} y llena el {item:15842} en la {object:19464}.",
		["Lost Barrens Kodos roam the plains north and west of the {area:380} and around the {area:388}; each drops a horn. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Los kodos de los Baldíos Perdidos ({npc:3234}) deambulan por las llanuras al norte y al oeste de {area:380} y alrededor de {area:388}; cada uno suelta un cuerno. Los herboristas encuentran {item:2449} por todo el norte de {zone:1413}.",
		["Ride north-east from {area:442} to {area:445} and fill the {item:15844} at the mouth of the cave by the falls."] = "Cabalga al noreste desde {area:442} hasta {area:445} y llena el {item:15844} en la entrada de la cueva junto a la cascada.",
		["Sickly Gazelles"] = "Gacelas enfermas",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it from {npc:1313} (Alchemy Supplies) in {zone:1453} or on the Auction House."] = "Las flores de hongo lunar ({object:177750}) crecen en las cuevas de los lechúcicos de las colinas justo al este de {area:442}; los lechúcicos de allí son irritables. La {item:2449} requiere {skill:182}: los herboristas la recogen por todo {zone:1439}; los demás la compran a {npc:1313} (Suministros de alquimia) en {zone:1453} o en la casa de subastas.",
		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "Usa el {item:15826} en las gacelas enfermas: pastan al norte del camino que cruza {area:380} de este a oeste.",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "Usa el {item:15826} en los {npc:12298}. Deambulan por {zone:1439}, desde el {area:456} al norte hasta la frontera con {zone:1440} al sur.",
		["{item:15851} and {item:2449}"] = "{item:15851} y {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} y cuernos de kodo",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}; los herboristas la recogen en las llanuras",
		["{npc:12296}: use the salve on them"] = "{npc:12296}: usa el ungüento en ellas",
		["{npc:12298}: use the salve on them"] = "{npc:12298}: usa el ungüento en ellos",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} está en {area:1639}.",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448} está en {area:380}. ¿No tienes {skill:182}? {npc:3490}, a pocos pasos, vende {item:2449}, de tres en tres hasta que repone.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} está en el {area:1658}.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "En Forever ya no se aprende {spell:8946} con el instructor: te lo enseña esta cadena, que además da una bolsa de medicinas.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "De vuelta con los Ancestros",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "El carcaj de Hastat necesita {item:18704}. {npc:6109}, un jefe del mundo para una banda, recorre el sur de {zone:1447} y lo suelta casi siempre; los vermis de cobalto de {zone:1452} lo sueltan muy rara vez. Omite el resto de esta guía si no quieres el carcaj.",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "Sin confirmar en Forever. En Classic, usar {item:18707} con {item:18724} en las bolsas creaba Rhok'delar, y Vartrus te daba entonces {item:18715} ({spell:425121}).",
		["Onyxia"] = "Onyxia",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "Onyxia suelta {item:18705}; es la jefa de banda de 40 jugadores de {area:2159}, una cueva en {area:511}, al sur de {zone:1445}.",
		["Rhok'delar and Lok'delar"] = "Rhok'delar y Lok'delar",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "La cadena del arco épico de cazador: en Classic, el bastón y el tendón se convertían en Rhok'delar y Lok'delar (sin confirmar en Forever).",
		["The {item:18703}"] = "La {item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "El {object:179703} aparece en {area:2717} cuando {npc:12018} se rinde; contiene la {item:18703} aproximadamente la mitad de las veces. {area:2717} es una banda de 40 jugadores dentro de {area:254}. Haz clic derecho en la hoja para empezar la misión.",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "Vartrus, Estoma y {npc:14526} están juntos en el norte de {zone:1448}. Alianza: el punto de vuelo más cercano es {area:1998}; Horda: {area:1997}.",
		["from the {item:18703}"] = "de la {item:18703}",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, de {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, de Onyxia",
		["{item:18707}, by Vartrus"] = "{item:18707}, de Vartrus",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Lok'delar en Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: el carcaj, lo último de esta guía",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "{npc:14527}, una trol, está en el oeste de {zone:1449}. Habla con ella y se convierte en {npc:14533}, con una mascota propia. Solo y sin tu mascota.",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "{npc:14529}, un humano, está en el oeste de {zone:1428}. Habla con él y se convierte en {npc:14534}. Solo y sin tu mascota.",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "{npc:14531}, un tauren, espera en el noreste de {zone:1452}. Habla con él y se convierte en {npc:14535}. Lucha contra cada demonio solo y sin tu mascota: cualquier tipo de ayuda hace que desaparezca. Despoja la cabeza.",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "{npc:14536}, un gnomo, está en el suroeste de {zone:1451}. Habla con él y se convierte en {npc:14530}. Solo y sin tu mascota; mantente lejos de los escarabajos que invoca.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "A nivel 50 cualquier instructor de cazadores de la Alianza la ofrece: {npc:5516} en {object:28027} de {zone:1453}, {npc:5116} en {object:32390} de {zone:1455} o Dorion en el Enclave Cenarion de {zone:1457}.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "A nivel 50 cualquier instructor de cazadores de la Horda la ofrece: {npc:3352} en {object:172958} de {zone:1454} o {npc:3039} en {area:1641}, en {zone:1456}.",
		["Experience"] = "Experiencia",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Experiencia a nivel 50 por {zone:1447} y el {area:1417}; Forever eliminó la elección de objeto de Classic.",
		["Morphaz in the {area:1417}"] = "Morphaz en el {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Morphaz es un jefe dragón élite dentro del {area:1417}, una mazmorra para cinco jugadores: lleva un grupo. El templo está en medio de {area:74}; bucea hasta él para llegar a la entrada. Horda: vuela a {area:75}; Alianza: vuela a {area:42} o a {area:1438} y sigue cabalgando.",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "Los maledictores Pezuñamusgo ({npc:8761}) pastan por todo {zone:1447}; más o menos uno de cada doce suelta un par de cuernos perfectos ({item:20017}).",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "Los vándalos marinos recorren las costas de {zone:1447}: los Vándalos marinos jóvenes de la orilla noreste y los vándalos marinos de la costa este sueltan las escamas el doble de a menudo que los Grandes vándalos marinos de la orilla sur.",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, dentro del {area:1417}",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} vive en lo alto de los acantilados al noreste de {area:1221}. Alianza: vuela a {area:3137}; Horda: vuela a {area:1237}.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (Alianza)",
		["{quest:8151} (Horde)"] = "{quest:8151} (Horda)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "De vuelta con Lydros",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "Vuela al Bastión Plumaluna (Alianza) o a {area:1099} (Horda) y cabalga hasta {area:2577}, en el centro de {zone:1444}. {npc:14368} espera en el Ateneo, la biblioteca, a la que se llega por el ala oeste (o por el ala norte con una {item:18249}).",
		["Hydrospawn"] = "Hidromilecio",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "Hidromilecio, un elemental de agua, vive en el Barrio Alabeo (La Masacre Este): persigue al diablillo Pusillín hasta que se vuelva para luchar, limpia la sala de los sátiros y baja por la rampa en espiral hasta el estanque.",
		["Shen'dralar reputation"] = "Reputación con los Shen'dralar",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} de nivel 60, de una biblioteca de {area:2577}: bebida para ti y tu grupo.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: Hidromilecio",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Human and Gnome mages in their late 20s."] = "Una toga o una blusa para magos humanos y gnomos de nivel 27-29 aprox.",
		["Back to Andromath"] = "Vuelve con Andromath",
		["Carrion Recluses"] = "Ermitaños carroñeros",
		["Carrion Recluses lurk in the woods of western {zone:1431} and each one drops the silk. The Black Widow Hatchlings further east drop it now and then."] = "Los Ermitaños carroñeros acechan en los bosques del oeste de {zone:1431} y todos sueltan la seda. Las Viudas negras reproductoras, más al este, la sueltan de vez en cuando.",
		["Ride east through {zone:1429} into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library."] = "Cabalga hacia el este por {zone:1429} hasta las Montañas Crestagrana. La torre de Ilgalar, el mago caído, está en el este de la zona; el tratado está en su biblioteca.",
		["The {area:96}"] = "{area:96}",
		["{npc:1309} works at {object:23296} in the {object:2101}."] = "{npc:1309} trabaja en {object:23296}, en el {object:2101}.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} entrena a los magos en {object:32362} de {zone:1455}. Después, toma el {area:2257} desde {object:171524} hasta {zone:1453}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}."] = "{npc:5497} está en la torre del {object:2101}.",
		["{quest:1939} is in the Wizard's Sanctum too."] = "{quest:1939} también está en esa torre.",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Un orbe de mano izquierda o un bastón para el final de la treintena, a tu elección.",
		["Back to {npc:6546}. She opens a mana rift beside her cottage: kill twelve {quest:1957} within ten minutes."] = "Vuelve con {npc:6546}. Abre una falla de maná junto a su cabaña: mata doce Oleadas de maná ({quest:1957}) en diez minutos.",
		["The Burning Blade Summoners work the {area:602} in southern {zone:1443}; any of them carries an {item:7291}."] = "Los Invocadores Filo Ardiente ocupan {area:602}, en el sur de {zone:1443}; cualquiera de ellos lleva un {item:7291}.",
		["{area:1517} is a dungeon in the northern {zone:1418}, by the {object:178824}: a group of five. Defeat the {npc:7023} inside for its power source."] = "{area:1517} es una mazmorra al norte de {zone:1418}, junto a la {object:178824}: un grupo de cinco. Derrota al {npc:7023} del interior para conseguir su fuente de energía.",
		["{item:7515} and Stave"] = "{item:7515} y bastón",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}, en la torre de los magos de {object:2101} de {zone:1453}, te envía con {npc:6546}; Bink, en {zone:1455}, da la misma misión.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, uno de los instructores de magos de {zone:1454}, te envía con {npc:6546}; {npc:4568} en {zone:1458} y {npc:3048} en {zone:1456} dan la misma misión.",
		["{npc:6546} draws the demon out of the orb beside her cottage. The {npc:6549} is elite: grouping up is advised. You have three minutes before it slips back into the orb."] = "{npc:6546} saca al demonio del orbe junto a su cabaña. El {npc:6549} es élite: se recomienda ir en grupo. Tienes tres minutos antes de que vuelva a meterse en el orbe.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}."] = "La cabaña de {npc:6546} está en lo profundo del pantano al oeste de Isla de Theramore, justo al norte de {area:508}.",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Vuelve con {npc:8395} y sube a la torre.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Vuelve con {npc:8395}, que te teletransporta a la torre.",
		["Back to {zone:1447}, {npc:8395} and the tower."] = "Vuelve a {zone:1447}, con {npc:8395} y a la torre.",
		["Experience"] = "Experiencia",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Experiencia a nivel 50 por {zone:1447} y {area:1417}; Forever quitó la elección de objeto de Classic.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to {npc:8379}."] = "Vuela a {area:3137} (Alianza) o {area:1237} (Horda). {npc:8395} acampa al pie de la torre de su maestro: desde el cruce del camino principal de {zone:1447} en {area:1221}, ve recto al norte hasta los acantilados. Te teletransporta arriba con {npc:8379}.",
		["Morphaz"] = "Morphaz",
		["Morphaz, a green drake, waits deep in the {area:1477}, the {area:1417} in the {area:74}: a group of five, level 50-54. Kill him for the {item:20085}."] = "Morphaz, un draco verde, espera en lo más hondo de {area:1477}, {area:1417} en {area:74}: grupo de cinco, nivel 50-54. Mátalo para obtener el {item:20085}.",
		["The Spitelash Sirens walk the ruins and beaches around the {area:1221} and the bay; they carry the coral."] = "Las sirenas Látigo de Ira recorren las ruinas y playas alrededor de {area:1221} y la bahía; llevan el coral.",
		["The blood elves camp along the cliffs of north-eastern {zone:1447}; Blood Elf Surveyors and Reclaimers drop the dust."] = "Los elfos de sangre acampan en los acantilados del noreste de {zone:1447}; los peritos y reivindicadores elfos de sangre sueltan el polvo.",
		["The {item:20085}"] = "El {item:20085}",
		["{item:20085}: Morphaz"] = "{item:20085}: Morphaz",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, el maestro mago, está en la torre de {object:2101} de {zone:1453}; Dink, en {zone:1455}, da la misma misión.",
		["{npc:7311}, one of {zone:1454}'s mage trainers, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}, uno de los instructores de magos de {zone:1454}, la da; también {npc:4567} en {zone:1458} y {npc:3047} en {zone:1456}.",
		["{npc:8379} again"] = "De nuevo {npc:8379}",
		["{npc:8379}, in the tower"] = "{npc:8379}, en la torre",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an orb at 10 for Horde mages, worth a short trip back to the {area:368}."] = "Un bastón o un orbe a nivel 10 para magos de la Horda; merece la pena volver un momento a las {area:368}.",
		["Back to Un'thuwa"] = "Vuelve con Un'thuwa",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Un'thuwa",
		["Un'thuwa stands in {area:367}, on the {zone:1411} coast south of {area:362}."] = "Un'thuwa está en {area:367}, en la costa de {zone:1411}, al sur de {area:362}.",
		["Wade across to the {area:368}, south-east of Sen'jin. Zalazane placed the heaps among his huts on the main isle: click a heap to destroy it."] = "Cruza vadeando hasta las {area:368}, al sureste de Sen'jin. Zalazane puso los montones entre sus chozas de la isla principal: haz clic en un montón para destruirlo.",
