t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165}, in the north of {zone:1455}."] = "A nivel 16, {npc:1234}, en {area:2102} de {area:131}, te envía con {npc:5165}, en el norte de {zone:1455}.",
		["At 16 {npc:3599} in {area:186} sends you to {quest:2259} in {zone:1457}."] = "A nivel 16, {npc:3599}, en {area:186}, te envía con {quest:2259} en {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}."] = "A nivel 16, {npc:917}, el instructor de pícaros de la Posada Orgullo de León en {area:87}, te envía con {npc:6946} en {zone:1453}.",
		["Back to {npc:6966}"] = "Vuelve con {npc:6966}",
		["Ride east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} waits on the west side of {area:69} and gives you {item:5060}."] = "Cabalga hacia el este por {zone:1429} hasta las Montañas Crestagrana, o vuela a {area:69}. {npc:6966} espera en el lado oeste de {area:69} y te da {item:5060}.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Tu primer trabajo de forzar cerraduras a nivel 16: la caja fuerte de {npc:6966} en {quest:2282}, para {quest:2300}.",
		["{npc:6946} stands beside {npc:332} at {quest:2300} in {object:2100}. Dwarves and Gnomes take the {area:2257} from {zone:1455}; Night Elves take the boat from {area:442} to {area:17203}."] = "{npc:6946} está junto a {npc:332} en {quest:2300}, en {object:2100}. Enanos y gnomos: tomad {area:2257} desde {zone:1455}; elfos de la noche: tomad el barco de {area:442} a {area:17203}.",
		["{quest:2282} stands east of {area:69}, up off the road. Open {object:121264} there."] = "{quest:2282} está al este de {area:69}, subiendo fuera del camino. Abre allí {object:121264}.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "A nivel 16, {npc:3170}, el instructor de pícaros de {area:362}, te envía con {npc:3401} en {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "A nivel 16, {npc:6467}, en {object:36073}, te envía con {npc:3401} en {zone:1454}. Acepta también {quest:1998}; se hace en {zone:1421} al final de esta guía.",
		["Back to {npc:6467}"] = "De vuelta con {npc:6467}",
		["Back to {npc:7161}"] = "De vuelta con {npc:7161}",
		["Fly or ride to {area:392} on the {zone:1413} coast. {npc:7161} stands in town with his Gizmotronic Apparatus: buy an {item:7970} and {item:5060} from the apparatus before you go."] = "Vuela o cabalga hasta {area:392}, en la costa de {zone:1413}. {npc:7161} está en el pueblo con su aparato gizmotrónico: cómprale al aparato un {item:7970} y {item:5060} antes de irte.",
		["South along the coast from {area:392}, at the Southsea pirates' camp. If an unusually hostile parrot attacks you, use the {item:7970} on it (the quest's own advice)."] = "Al sur de {area:392} por la costa, en el campamento de los piratas de los Mares del Sur. Si te ataca un loro inusualmente hostil, usa el {item:7970} en él (consejo de la propia misión).",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south into Silverpine. {quest:1998} stands north-east of the {area:228}."] = "Toma el zepelín de {zone:1454} a {zone:1458} y cabalga al sur hasta el Bosque de Argénteos. {quest:1998} está al noreste de {area:228}.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Diez {item:7676}, la bebida de energía de los pícaros, de los trabajos de forzar cerraduras de la Horda a nivel 16.",
		["The Kirin Tor keep their reports at {area:233}, in south-east Silverpine: pick the lock on the {object:103815}."] = "El Kirin Tor guarda sus informes en {area:233}, en el sureste del Bosque de Argénteos: fuerza la cerradura de la {object:103815}.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}."] = "Los no-muertos toman el zepelín desde las torres a las afueras de {zone:1458} hasta {zone:1411}. {npc:3401} y {quest:2379} están en {object:172960}, el cañón bajo {object:172982}.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} y {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: diez {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay down"] = "/lay down",
		["At 20 {npc:332} at SI:7 in {object:2100} sends you to {npc:7024} in {zone:1436}."] = "A nivel 20, {npc:332}, en el IV:7 de {object:2100}, te envía con {npc:7024} en {zone:1436}.",
		["Back to {npc:7207}"] = "De vuelta con {npc:7207}",
		["Everything is in {zone:1453}: the Gumps sell {item:3421}, the {item:8431} lies in the city, and the nearest vendors sell a {item:3372} and a {item:4371}."] = "Todo está en {zone:1453}: los Gump venden {item:3421}, el {item:8431} está en la ciudad y los mercaderes más cercanos venden un {item:3372} y un {item:4371}.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "En Forever, {spell:2842} se aprende con esta cadena, no con el instructor; incluye la receta de {item:7676}.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Cabalga al norte por el Bosque de Elwynn hasta {zone:1453}; Mathias Shaw está en el IV:7, en {object:2100}.",
		["The cure's ingredients"] = "Los ingredientes de la cura",
		["{item:7908}, in the {object:123214}"] = "{item:7908}, en el {object:123214}",
		["{npc:7024} watches {npc:7053}'s tower from the hills in the far east of {zone:1436}, by the {zone:1431} border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "{npc:7024} vigila la torre de {npc:7053} desde las colinas del extremo este de {zone:1436}, junto a la frontera con {zone:1431}. El {npc:7051} (nivel 23) que guarda la torre lleva su llave; el diario de Klaven está en el cofre de arriba.",
		["{npc:7207} works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined."] = "{npc:7207} trabaja en el sótano del IV:7, el Cuartel. Escribe /lay down a su lado para que te examine.",
		["{spell:2842} (Alliance)"] = "{spell:2842} (Alianza)",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salute a {npc:3401}",
		["At 20 {npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Target him and type /salute."] = "A nivel 20 {npc:3401} está en {object:172960}, el cañón bajo {object:172982}. Selecciónalo y escribe /salute.",
		["Back to {npc:3401}"] = "Vuelve con {npc:3401}",
		["Fly back to {zone:1454}."] = "Vuelve volando a {zone:1454}.",
		["Fly to the {area:380} and ride north to the Venture Co. tower north of the {area:382}. In sight of the tower, fire the {item:8051} twice, then /salute {npc:7233} before he attacks you."] = "Vuela a {area:380} y cabalga al norte hasta la torre de Ventura y Cía. al norte de {area:382}. A la vista de la torre, dispara la {item:8051} dos veces y luego haz /salute a {npc:7233} antes de que te ataque.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever enseña {spell:2842} con esta cadena, no el instructor; la receta de {item:7676} viene con ella.",
		["Stay stealthed. {npc:7287} carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it."] = "Permanece en sigilo. {npc:7287} lleva la llave de la torre; Gallywix (élite) y su caja fuerte están en lo alto de la torre. Mata a dos de cada: zánganos, patrulleros y vigías de los alrededores.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south through {zone:1421} to {area:272} in {area:287}. {npc:2391} stands in {area:272}; wait beside him while he brews the cure."] = "Toma el zepelín de {zone:1454} a {zone:1458} y cabalga al sur por {zone:1421} hasta {area:272}, en {area:287}. {npc:2391} está en {area:272}; espera a su lado mientras prepara la cura.",
		["Wait for the cure"] = "Espera la cura",
		["{item:8051}, twice, in sight of the tower"] = "{item:8051}, dos veces, a la vista de la torre",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (élite)",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: guarda la {item:8051}",
		["{spell:2842} (Horde)"] = "{spell:2842} (Horda)",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 an {item:17126} from {npc:13936} starts this; the data gives it to you through {npc:332} or {npc:918} in {zone:1453}, or Gest or Ormok in {zone:1454}. The quest hands you the {item:17125} for {npc:6707}."] = "A nivel 24, una {item:17126} de {npc:13936} inicia esto; según los datos, te la dan {npc:332} u {npc:918} en {zone:1453}, o Invitor u Ormok en {zone:1454}. La misión te da el {item:17125} para {npc:6707}.",
		["At 36, {npc:13085} sends you after Barton's scouting report. Barton leads a Syndicate party at {area:280}, in the east of the {zone:1416}: pick his pocket, do not kill him."] = "A nivel 36, {npc:13085} te envía a por el informe de exploración de Barton. Barton dirige un grupo del Sindicato en {area:280}, en el este de {zone:1416}: róbale, no lo mates.",
		["Back to {npc:13085}"] = "De vuelta con {npc:13085}",
		["Horde fly to {area:272}, Alliance to {area:271}. The manor hides in the hills east of {area:272}, up a path into the {zone:1416}; the Rite of Cunning is passing its way in."] = "La Horda vuela a {area:272}; la Alianza, a {area:271}. La mansión se oculta en las colinas al este de {area:272}, subiendo por un sendero hacia {zone:1416}; el Rito de Astucia consiste en encontrar la forma de entrar.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and its first jobs."] = "Abre la {area:3486}, la casa oculta de los pícaros en las colinas de Alterac, y sus primeros trabajos.",
		["Rite of Cunning"] = "Rito de Astucia",
		["The {item:17126}"] = "La {item:17126}",
		["{item:275482}: pickpocket Barton"] = "{item:275482}: róbaselo a Barton",
		["{npc:13936} reputation"] = "Reputación con {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress in eastern {area:287}, south of the manor. Quick and quiet, says {npc:13085}."] = "{npc:266216} está dentro de {area:275}, la fortaleza del Sindicato en el este de {area:287}, al sur de la mansión. Rápido y en silencio, dice {npc:13085}.",
		["{npc:6766}: {quest:6701}, repeatable"] = "{npc:6766}: {quest:6701}, repetible",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. The Timbermaw Shamans in {zone:1447}'s northern hills drop the bag, about one in thirty."] = "La Alianza vuela a {area:3137}; la Horda, a {area:1237}. Los chamanes Fauces de Madera de las colinas del norte de {zone:1447} sueltan la bolsa, más o menos uno de cada treinta.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "A nivel 50, la tiene {npc:3328} en {object:172960}; también {npc:4583} en {object:36073} de {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} and Fenthwick in {zone:1455}."] = "A nivel 50, la tiene {npc:918} en {object:2100} de {zone:1453}; también Syurna en {zone:1457}, y {npc:5165} y Fenthwick en {zone:1455}.",
		["Back to Xylem"] = "De vuelta con Xylem",
		["Lord Ravenholdt"] = "Lord Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz en el {area:1417}",
		["Morphaz, a green drake, is an elite boss deep in the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the {area:74}; swim down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on."] = "Morphaz, un draco verde, es un jefe de élite en lo más hondo del {area:1417}, una mazmorra de nivel 50: lleva un grupo de cinco. El templo está en {area:74}; bucea hasta la entrada. Horda: vuela a {area:75}. Alianza: vuela a {area:1438} y sigue cabalgando.",
		["Ravenholdt reputation"] = "Reputación con Ravenholdt",
		["Ravenholdt reputation and experience at 50; Forever removed the Classic item choice."] = "Reputación con Ravenholdt y experiencia a nivel 50; Forever eliminó la elección de objeto de Classic.",
		["The Forest Oozes of southern {zone:1447} drop the fragments."] = "Los mocos del bosque del sur de {zone:1447} sueltan los fragmentos.",
		["{area:3486} hides in the hills east of {area:272}, up a path into the {zone:1416}. Horde fly to {area:272}, Alliance to {area:271}."] = "La {area:3486} se oculta en las colinas al este de {area:272}, subiendo por un sendero hacia {zone:1416}. La Horda vuela a {area:272}; la Alianza, a {area:271}.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, dentro del templo",
