t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Un bastón, objeto de mano izquierda o toga para la cincuentena; un encargo propio de {npc:14470}, no un paso de la cadena del Corcel nefasto.",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448}."] = "A nivel 50 {npc:3326}, en {object:172960}, te envía con {npc:14470} en {zone:1448}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448}."] = "A nivel 50 {npc:4563}, en {object:36082}, te envía con {npc:14470} en {zone:1448}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448}."] = "A nivel 50 {npc:461}, en {object:2164}, en {object:2101}, te envía con {npc:14470} en {zone:1448}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448}."] = "A nivel 50 {npc:5172}, en {zone:1455}, te envía con {npc:14470} en {zone:1448}.",
		["The Irontree treants in northern {zone:1448} drop the {item:20613}; the Tainted Oozes around {area:1763} the {item:20614}."] = "Los ents Troncoferro del norte de {zone:1448} sueltan {item:20613}; los Mocos corruptos de alrededor de {area:1763}, {item:20614}.",
		["The six troll guardians of the {area:1417}, a level 50 dungeon, each drop a Voodoo Feather: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance."] = "Los seis guardianes trols del {area:1417}, una mazmorra de nivel 50, sueltan cada uno una pluma vudú: lleva un grupo de cinco. El templo está en medio de {area:74}; bucea hasta él para llegar a la entrada.",
		["The {area:1417}"] = "El {area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613} y veneno de sangre",
		["{npc:14470} again"] = "{npc:14470} de nuevo",
		["{npc:14470} waits beside {npc:14469} in central {zone:1448}, just east of {area:1763}. This chain is {npc:14470}'s own and is not part of the Dreadsteed chain; Niby and {npc:14470} also give the {item:18762} chain here."] = "{npc:14470} espera junto a {npc:14469} en el centro de {zone:1448}, justo al este de {area:1763}. Esta cadena es propia de {npc:14470} y no forma parte de la del Corcel nefasto; Niby y {npc:14470} también dan aquí la cadena de {item:18762}.",
		["{npc:14470} wants one {item:14256}: the Jadefire satyrs and the demons of {area:1763} drop it."] = "{npc:14470} quiere una {item:14256}: la sueltan los sátiros Fuego de Jade y los demonios de {area:1763}.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "Un segundo demonio seductor, el sayaad masculino, y una bolsa para llevar tus fragmentos de alma.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}."] = "A nivel 20, {npc:6122}, en el sótano de {object:2164} de {object:2101}, te envía con {npc:6244} en {zone:1413}.",
		["Back to {npc:6122} in the {object:2164}. Place the figurine at the summoning circle in the crypt below him and defeat the incubus it calls."] = "Vuelve con {npc:6122} en {object:2164}. Coloca la figurilla en el círculo de invocación de la cripta que hay debajo y derrota al íncubo que aparece.",
		["From {area:415} take the road west to {area:413}: the figurine lies in a house among the trees north of the post."] = "Desde {area:415}, toma el camino al oeste hasta {area:413}: la figurilla está en una casa entre los árboles al norte del puesto.",
		["Incubus (Alliance)"] = "Íncubo (Alianza)",
		["{npc:6122}: he binds the incubus to you"] = "{npc:6122}: te vincula al íncubo",
		["{npc:6244} camps in the southern {zone:1413}, east of the road north-east of {area:378}: come in from the east and keep clear of the Horde guards."] = "{npc:6244} acampa en el sur de {zone:1413}, al este del camino, al noreste de {area:378}: acércate desde el este y evita a los guardias de la Horda.",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "Un segundo demonio seductor, el sayaad masculino, y una bolsa para tus fragmentos de alma.",
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers offer the incubus, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one: this guide follows whichever {quest:1472} you took."] = "A nivel 20, {npc:5875}, en la {object:172960} bajo el {object:172982}, te envía con {npc:5909}, a pocos pasos. Dos instructores ofrecen el íncubo, {npc:5875} aquí y {npc:5675} en {zone:1458}, y solo puedes aceptar uno: esta guía sigue la {quest:1472} que hayas aceptado.",
		["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "Vuelve con {npc:5675} en el {object:36082}. Pon los corazones en el círculo de invocación bajo él y derrota al íncubo que aparece.",
		["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "Vuelve con {npc:5875} en la {object:172960}. Lleva el pañuelo al círculo de invocación de la tienda de {npc:3216}, cerca, y derrota al íncubo que aparece.",
		["Incubus (Horde)"] = "Íncubo (Horda)",
		["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "{area:422} está en el sur de {zone:1440}, al sur del {area:431}. Las bestias de pantano Sombramatorral alrededor del lago sueltan {item:190232}, una de cada veinte aprox.",
		["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333} trabaja de sastre para los magos de {area:279} en {area:233}, en el este del {zone:1421}. Consigue su corazón.",
		["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334} trabaja en {area:392}, en la costa de {zone:1413}. Toma el zepelín a {zone:1411} y sigue a caballo o volando hasta {area:392}.",
		["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363} lleva {object:173018}, al este de la {object:172960} por la calle principal. Te pide que busques a su pareja, Krilge.",
		["{npc:5675}: he binds the incubus to you"] = "{npc:5675}: vincula el íncubo a ti",
		["{npc:5875}: he binds the incubus to you"] = "{npc:5875}: vincula el íncubo a ti",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "La versión de {object:1661}, para brujos que aceptaron {quest:1472} de {npc:5675} en lugar de la de {npc:5875}. A nivel 20, {npc:5675}, en el {object:36082}, te envía con {npc:5693}, en el templo justo al norte de él.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Un orbe para la mano izquierda o un bastón para el nivel 35-39 aprox., por el camino del manáfago o del infernal, a tu elección.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:3326}, en la {object:172960}, te envía con {npc:6266} en {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "A nivel 35, {npc:4563}, en el {object:36082}, te envía con {npc:6266} en {area:392}. El zepelín de {zone:1420} vuela a {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:461}, en {object:2164}, en el {object:2101}, te envía con {npc:6266} en {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:5172}, en {zone:1455}, te envía con {npc:6266} en {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, wait while she completes the {item:15108}, then speak to her again."] = "Vuelve con {npc:6266} a la torre sobre {area:392} con el orbe purificado. En el camino del manáfago, espera mientras termina {item:15108} y luego vuelve a hablar con ella.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit first: {npc:6546}'s cleansing follows it."] = "Primero vuelve con {npc:6266} a la torre sobre {area:392} con el espíritu: la purificación de {npc:6546} viene después.",
		["Choose an acolyte"] = "Elige un acólito",
		["On the infernal path, wait while {npc:6266} completes the {item:15107}, then speak to her again."] = "En el camino del infernal, espera mientras {npc:6266} termina {item:15107} y luego vuelve a hablar con ella.",
		["Orb of Orahil"] = "Orbe de Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, {npc:6252}'s infernal path with the Orb or {item:15105}. The guide follows the one you take."] = "Elige un acólito: solo puedes aceptar una de sus misiones. El camino del manáfago de {npc:6254} acaba con el orbe o {item:15106}; el camino del infernal de {npc:6252}, con el orbe o {item:15105}. La guía sigue el que elijas.",
		["The demon's spirit"] = "El espíritu del demonio",
		["The demons of {area:602}, in southern {zone:1443}, have all you need. Burning Blade Summoners carry the {item:7291}. On the felhound path, use the {item:12647} on a {npc:4678}, a felhound, and kill it for its spirit; on the infernal path, use the {item:12646} on a {npc:4676} and kill it."] = "Los demonios del {area:602}, en el sur de {zone:1443}, tienen todo lo que necesitas. Los Invocadores Filo Ardiente llevan {item:7291}. En el camino del manáfago, usa {item:12647} en un {npc:4678}, un manáfago, y mátalo para conseguir su espíritu; en el camino del infernal, usa {item:12646} en un {npc:4676} y mátalo.",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait for the orb"] = "Espera el orbe",
		["{item:12648}, from a {npc:4678}"] = "{item:12648}, de un {npc:4678}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, de un {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, de los Invocadores Filo Ardiente",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: te da {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: te da {item:12647}",
		["{npc:6266} and her two acolytes stand in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266} y sus dos acólitos están en la torre de la colina sobre {area:392}, junto a {npc:6251}.",
		["{npc:6546} lives at her farm in western {zone:1445}. She calls the {npc:6549} out of the {item:7291}; it is elite: grouping up is advised."] = "{npc:6546} vive en su granja del oeste del {zone:1445}. Saca al {npc:6549} del {item:7291}; es de élite: se recomienda ir en grupo.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your late 20s, for fragments from two dungeons."] = "Un orbe de mano izquierda o un bastón raros para el final de la veintena, a cambio de fragmentos de dos mazmorras.",
		["Back to {npc:6247}"] = "De vuelta con {npc:6247}",
		["The Shadowfang Darksouls inside {area:236}, a level 20-30 dungeon, drop the Large Fragment about one time in five: bring a group. The keep stands south of the {area:228}."] = "Los Almanegra Colmillo Oscuro de {area:236}, una mazmorra de nivel 20-30, sueltan el fragmento grande más o menos una vez de cada cinco: lleva un grupo. El castillo está al sur de {area:228}.",
		["The Twilight Acolytes inside {area:2797}, a level 24-32 dungeon, each drop a {item:6914}: bring a group. The entrance is in the ruins on the north-west coast of {zone:1440}."] = "Cada Acólito Crepuscular de {area:2797}, una mazmorra de nivel 24-32, suelta un {item:6914}: lleva un grupo. La entrada está en las ruinas de la costa noroeste de {zone:1440}.",
		["{item:6914}, from the Twilight Acolytes"] = "{item:6914}, de los Acólitos Crepusculares",
		["{item:6915}, from the Shadowfang Darksouls"] = "{item:6915}, de los Almanegra Colmillo Oscuro",
		["{npc:6247} camps in the southern {zone:1413}, east of the road north-east of {area:378}."] = "{npc:6247} acampa en el sur de {zone:1413}, al este del camino, al noreste de {area:378}.",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Un objeto raro de mano izquierda para tus niveles 50, de {npc:14469} y {npc:14470} en {zone:1448}, el campamento que también ofrece Pedido de un diablillo.",
		["At 50 {npc:14469} and his imp {npc:14470} wait in central {zone:1448}, just east of {area:1763}."] = "A nivel 50, {npc:14469} y su diablillo {npc:14470} esperan en el centro de {zone:1448}, justo al este de {area:1763}.",
		["Back to {npc:14469}"] = "Vuelve con {npc:14469}",
		["The Felguard Sentries around the {area:72}, in southern {zone:1419}, carry its essence."] = "Los centinelas guardia vil que rodean {area:72}, en el sur de {zone:1419}, llevan su esencia.",
		["The Jaedenar Legionnaires, a short way west of {npc:14469}, carry {area:1763}'s essence."] = "Los legionarios Jaedenar, un poco al oeste de {npc:14469}, llevan la esencia de {area:1763}.",
		["The Legashi satyrs of northern {zone:1447} carry {zone:1447}'s essence."] = "Los sátiros Legashi del norte de {zone:1447} llevan la esencia de {zone:1447}.",
