} end)()
t.guides["forever/collectibles/pets/dark-whelpling"] = (function() return {
		["Black whelps"] = "Crías negras",
		["The Searing Whelps of the {area:511} in southern {zone:1445} (level 42) and the Scalding Whelps of eastern {zone:1418} (level 41) drop it about once in 900 kills in our data. The waypoint is the {area:511}; the {zone:1418} whelps are the same grind."] = "Las crías abrasadoras de {area:511}, en el sur de {zone:1445} (nivel 42), y las crías hirvientes del este de {zone:1418} (nivel 41) lo sueltan más o menos una vez cada 900 muertes según nuestros datos. El punto de ruta es {area:511}; las crías de {zone:1418} son el mismo farmeo.",
		["The {area:511}"] = "{area:511}",
} end)()
t.guides["forever/collectibles/pets/disgusting-oozeling"] = (function() return {
		["Oozes drop the {item:20768}: the Vile Slimes, Large Vile Slimes and Devouring Oozes of Western Plaguelands, and the oozes of {zone:1448}, {zone:1449} and {zone:1423}, at about 0.07-0.09% per kill in our data. The waypoint is a {npc:1806} spawn in eastern {zone:1422}."] = "Los mocos sueltan {item:20768}: las babosas viles, las grandes babosas viles y los mocos devoradores de Tierras de la Peste del Oeste, y los mocos de {zone:1448}, {zone:1449} y {zone:1423}, con un 0.07-0.09% por muerte según nuestros datos. El punto de ruta es un lugar de aparición de {npc:1806} en el este de {zone:1422}.",
		["Open the {item:20768}"] = "Abre {item:20768}",
