t.guides["forever/collectibles/pets/mechanical-chicken"] = (function() return {
		["Each robot starts with a distress beacon that mobs in its zone drop (about 1-2.5% per kill in our data). Start in {zone:1444}."] = "Cada robot empieza con una baliza de socorro que sueltan los enemigos de su zona (un 1-2.5% por muerte según nuestros datos). Empieza en {zone:1444}.",
		["Escort OOX-09/HL"] = "Escolta a OOX-09/HL",
		["Escort OOX-17/TN"] = "Escolta a OOX-17/TN",
		["Escort OOX-22/FE"] = "Escolta a OOX-22/FE",
		["Most {zone:1425} mobs can drop OOX-09/HL's beacon (about 1-2.5% per kill in our data)."] = "Casi todos los enemigos de {zone:1425} pueden soltar la baliza de OOX-09/HL (un 1-2.5% por muerte según nuestros datos).",
		["Most {zone:1446} mobs can drop OOX-17/TN's beacon (about 0.5-3% per kill in our data)."] = "Casi todos los enemigos de {zone:1446} pueden soltar la baliza de OOX-17/TN (un 0.5-3% por muerte según nuestros datos).",
		["Rescue OOX-09/HL"] = "Rescata a OOX-09/HL",
		["Rescue OOX-17/TN"] = "Rescata a OOX-17/TN",
		["Rescue OOX-22/FE"] = "Rescata a OOX-22/FE",
		["Take the beacon to OOX-09/HL at the head of the river near {area:351}, then escort it to the shore beyond Overlook Cliff."] = "Lleva la baliza a OOX-09/HL, en el nacimiento del río cerca de {area:351}, y escóltalo hasta la orilla más allá de Los Acantilados Dominantes.",
		["Take the beacon to OOX-17/TN in {zone:1446}, then escort it to {area:977}. Its turn-in is in {area:35} too."] = "Lleva la baliza a OOX-17/TN en {zone:1446} y escóltalo hasta {area:977}. Su entrega también está en {area:35}.",
		["Take the beacon to OOX-22/FE in a cave near {area:1105}, then escort it to the dock on the {area:1108}. Its turn-in is in {area:35}; keep it for later."] = "Lleva la baliza a OOX-22/FE, en una cueva cerca de {area:1105}, y escóltalo hasta el muelle de {area:1108}. Su entrega está en {area:35}; déjala para más tarde.",
		["{item:8623} in {zone:1446}"] = "{item:8623} en {zone:1446}",
