t.guides["forever/reputation/thorium-brotherhood"] = (function() return {
		["Back to Burninate"] = "Vuelve con Cremación",
		["Keep turning in {area:2717} materials and {item:11099} at Lokhtos until Exalted."] = "Sigue entregando materiales de {area:2717} y {item:11099} a Lokhtos hasta Exaltado.",
		["Restoring Fiery Flux Supplies repeats in three versions: {item:3356}, Iron Bars or {item:4234}, each with Coal and an {item:18944}. Incendosaurs (level 47-49) in the north of {zone:1427} drop a scale every time; Burninate himself sells Coal."] = "Fabricar fluido ardiente se repite en tres versiones: con {item:3356}, Lingotes de hierro o {item:4234}, cada una con Carbón y una {item:18944}. Los Incendosaurios (nivel 47-49) del norte de {zone:1427} sueltan siempre una escama; el propio Cremación vende Carbón.",
		["The plans lie in the {area:1443} of the Cauldron, guarded by {object:147516} dwarves. {object:147516} dwarves also drop {item:18945}, which Burninate takes for Gaining Acceptance."] = "Los planos están en {area:1443} de La Caldera, custodiados por enanos {object:147516}. Los enanos {object:147516} también sueltan {item:18945}, que Cremación acepta para Ganarse el respeto.",
		["The {area:2717} materials carry the rest: Fiery Cores drop from Firewalkers, Flameguards and Firelords, and Lava Cores from Lava Elementals, Lava Reavers and Molten Destroyers there. {item:11382} comes from Molten Destroyers and rarely elsewhere."] = "Los materiales de {area:2717} dan el resto: los Núcleos ígneos caen de los caminafuegos, guardias llamarada y señores del fuego, y los Núcleos de lava de los Elementales de lava, Atracadores de lava y Destructores fundidos de allí. {item:11382} sale de los Destructores fundidos y, rara vez, de otros sitios.",
		["Thorium Brotherhood Reputation"] = "Reputación: Hermandad del torio",
		["{area:1446}, on the scaffolds in the north-west of {zone:1427}, is the Brotherhood's outpost. The {faction:59} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:1446}, en los andamios del noroeste de {zone:1427}, es el puesto avanzado de la Hermandad. La {faction:59} empieza en Neutral. La ventaja de Legado Diplomático de Forever aumenta la reputación obtenida.",
		["{area:2717} materials: Favor Amongst the Brotherhood, {item:17010}, {item:17011}, {item:17012} and {item:11382}, all repeatable at Lokhtos."] = "Materiales de {area:2717}: El favor de la Hermandad, {item:17010}, {item:17011}, {item:17012} y {item:11382}, todos repetibles con Lokhtos.",
		["{faction:59} to Exalted"] = "{faction:59} hasta Exaltado",
		["{faction:59} to Revered"] = "{faction:59} hasta Reverenciado",
		["{item:11099}: Favor Amongst the Brotherhood, {item:11099} at Lokhtos, repeatable."] = "{item:11099}: El favor de la Hermandad, {item:11099} con Lokhtos, repetible.",
		["{item:18942} supplies to Friendly"] = "Suministros de {item:18942} hasta Amistoso",
		["{npc:12944} to Honored"] = "{npc:12944} hasta Honorable",
		["{npc:12944} trades in the Grim Guzzler inside {area:1584}. His Favor Amongst the Brotherhood turn-ins take {item:11099} (mined from Dark Iron Deposits with {skill:186}), {item:11382}, {item:17010}, {item:17011} and {item:17012}. {npc:14387} at the {area:1445} entrance offers attunement to the {area:2717}."] = "{npc:12944} comercia en el Tragapenas, dentro de {area:1584}. Sus entregas de El favor de la Hermandad piden {item:11099} (extraído de Depósitos de los Hierro Negro con {skill:186}), {item:11382}, {item:17010}, {item:17011} y {item:17012}. {npc:14387}, en la entrada de {area:1445}, ofrece la armonización con {area:2717}.",
		["{npc:14624}: Restoring Fiery Flux Supplies"] = "{npc:14624}: Fabricar fluido ardiente",
} end)()
